window.__D("text/likkutei-sichot/c080",{"p":[[1300101018,"קודם התהוות הנבראים וכמו שהוא מאיר בתוך הנבראים — מבוארות היטב שתי הדיעות<sup data-n=\"19\">19</sup> בענין ה„אור דיום ראשון\" שהיא: א) מדריגת ה־כתר ב) מדריגת החסד:\nדזהו מההפרש בין בחי' כתר לבחי' חסד: כתר הוא למעלה מכל סדר השתלשלות העולמות — והוא האור דיום ראשון כמו שהוא קדום ולמעלה מכל סדר הבריאה; אבל מדריגת ה־חסד, שהיא תחילת ההשתלשלות וה־ראשונה שבשבעת ימי הבנין, הריהי „יומא דאזיל עם כולהו יומין\"<sup data-n=\"20\">20</sup> (היינו שכל עיקר ההתהוות הוא מספי' החסד) — וזוהי גם בחי' ההארה (והמטרה) דאור יום הראשון הנמ־שכת וממשכת „אור, כי טוב\" — (חסד) בכל נברא בשי\"ב.\nז. ובזה יובן מ\"ש בזהר ד„אור\" הוא בגימטריא „רז\" ומוסברת השיי־כות ביניהן: דכמו שהוא באדם, הרי המטרה שקבע קודם הפעולה באה אז לידי גילוי רק במחשבתו וכוונתו של הפועל, ועיקר התגלותה של המטרה בפועל ממש ובכל מילואה הוא דוקא בסיום הפעולה והשלמתה — אבל בכל משך זמן הפעולה עצמה הרי היא אצלו בהעלם ובמדה מצומצמת<sup data-n=\"21\">21</sup> (רק כפי הנחוץ לכוון את הפעולה לתכ־ליתה);",[["19","19","הובאו ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158670154\" data-slug=\"or-hatorah-hb\" data-id=\"8158670154\">אוה\"ת</a> דרושי חנוכה (שה, ב)."],["20","20","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381028\" data-slug=\"likkutei-torah\" data-id=\"4001381028\">ראה זח\"ג קצא, ב</a>. נתבאר בע\"ח שכ\"ה ד\"ב. פע\"ח שהה\"ס פ\"א. לקו\"ת האזינו עו, ב. ועוד."],["21","21","והיינו דנוסף לזה שאינו בגילוי כ\"כ כמו לפני הפעולה, הרי מכיון שהיא מלובשת בהפעולה — היא רק הארה בלבד מבחי' הכוונה כמו שהיא לפני הפעולה (ומובן מזה שרק הארה מהאור שנברא ביום ראשון (בחי' חסד ולא בחי' כתר) האירה בכל מאמר פרטי). ועד\"ז הוא למעלה: כיון שהמטרה והתכלית של הבריאה הוא „אור\", לכן אין ה„אור\" מתגלה בכל מהותו אלא בזמן שהבריאה מגיעה לתכליתה, היינו בגמר סדר עבודת הבירורים בסוף השית אלפי שנין דהוי עלמא, אבל עד עת־קץ ההיא, עם שה„אור\" (המ־טרה) נמצא (וגם פועל בה) בהבריאה, אבל רק בבחי' „רז\" וסוד — ב־העלם, עד שיתגלה לע\"ל. וזהו גם פירושו של מארז\"ל, שה־אור דיום ראשון נגנז לע\"ל — היינו שנתעלם בבחי' „רז\" עד הזמן דלע\"ל. אמנם „גניזה\" הרי פירושה שהוא יש ונמצא במקום הגנוז, וכנ\"ל שמעין מה„אור\" ההעלמי נמשך בבריאה וגם נותן בה כוח ועוז להגיע אל המטרה. ואיפה „נגנז האור\", שמשם הוא פועל בבריאה? — אמרו חכמינו ז\"ל ש־הקב\"ה גנזו בתורה 22). וביאור הדבר: כמו בכל פעולה, הרי מובן, שה־מטרה מתעלמת ונגנזת (עד גמר הפעו־לה) בתוכה של הפעולה עצמה, דהיינו שהיא טמונה בעניני פעולה כאלו שעל ידם היא מכוונת את הפעולה לתכליתה — כן הוא גם בה„אור\" דיום ראשון שהוא המטרה והתכלית של כל הבריאה כולה: התגלות ה„אור\" הזה לע\"ל הוא ע\"י העבודה של עכשיו 23) בלימוד התורה וקיום המצות, ז.א. שבהם ועל ידם תגיע הבריאה למטרתה ותכליתה, ומובן איפוא, שאין המטרה גנוזה ---"],["22","22","מדרש רות בזהר חדש פה, א (עייג\"כ זח\"א רסד, א. זח\"ב קמט, א), ובדגל מחנה אפרים פ' בראשית בשם הבעש\"ט. כתר ש\"ט (קרוב לתחלתו) ההי' בשם הבעש\"ט כו' (באריכות). ובכ\"מ. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380383\" data-slug=\"likkutei-torah\" data-id=\"4001380383\">לקו\"ת במדבר יח, ד</a>. שם דברים פט, ד. דרך אמונה סה, א. וכל העם תרצ\"ט ס\"ג. ועוד."],["23","23","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>."]]],[1300101019,"אלא בהם. ומכיון דכל העבודה דקיום המצות באה מהתורה ולימודה — כמארז\"ל<sup data-n=\"24\">24</sup> „גדול תלמוד שמביא לידי מעשה\" — נמצא שעיקר גניזתו של ה„אור\" הוא בתורה.\nח. ההוראה מכל הנ\"ל בעבודה ברורה ופשוטה לכאו\"א:\n„יהי אור\" — היא־היא המטרה והתכלית של כל עבודת הנבראים, שהאדם יברר את חלקו בעולם עד שיהפך ל„אור\". וכל זמן שלא האיר את העולם באור התורה והמצות — גם כשהצליח בעבודתו לגרש מעולמו את „החושך\" והרע (ע\"ד „ישב ולא עבר עבירה\"<sup data-n=\"25\">25</sup>) אבל לא נהפך עדיין על ידו לאור וטוב (ע\"י „ועשה טוב\") — לא מילא את תפקידו ולא השלים את כוונתה ומטרתה של הבריאה —\nכי תכלית כוונת הבריאה בכללותה, ותכלית בריאת האדם בפרט ובעיקר, הוא לא רק העבודה ד„סור מרע\" — לפעול העדר ומניעת החושך, כי אם גם (בעיקר) העבודה ד„ועשה טוב\" לעשות ולהפך את העולם לאור וטוב.\nוכשם שהסדר בבריאת העולם ע\"י הקב\"ה הוא:\nא) שמיד בראשית הבריאה, ביום ראשון ובמאמר ראשון, קבע הקב\"ה את מטרתה, ולאח\"ז ברא את העולם על כל ברואיו;\nב) שמאידך גיסא, הרי בכל הנבראים נאמר בהם „טוב\", והיינו שה„אור\" והמטרה של הבריאה נמשך והאיר בכל מאמר ובריאה פרטית בכדי שיתאימו להכוונה.\nכן צריך להיות הסדר בעבודת האדם:\nא) מיד כשניעור משנתו (בב\"י בבוקר וכמו\"כ בכל שעה ושעה<sup data-n=\"26\">26</sup> ונעשה „ברי' חדשה\"<sup data-n=\"27\">27</sup> (בדוגמת יום ראשון של הבריאה<sup data-n=\"28\">28</sup>), הנה ראשית דבר הוא קביעות המטרה — שצ\"ל קבוע ומונח אצלו (איינגעקארבט און אפגעלייגט), שמטרת כל פעולותיו היא — יהי אור<sup data-n=\"29\">29</sup>; ורק אז, לאחרי הנחה והחלטה זו, יכול הוא לגשת לפרטי עשיותיו ופעולותיו;\nב) ונוסף לזה צ\"ל השתדלות מיו־חדת, שהמטרה של „יהי אור\" תורגש גם לאח\"כ, בכל שעה ובכל פרט מעסקיו ומעשיו במשך היום.\nט. והנה כמו שהוא בנידון כללות הבריאה כולה, שתכליתה היא — „אור\", כן הוא גם בנוגע לבריאתה הפרטית של (מציאות<sup data-n=\"30\">30</sup> החושך עצ־מה, שכוונת מטרת בריאתה היא",[["24","24","קדושין מ, ב."],["25","25","שם לט, סע\"ב."],["26","26","כי בכל רגע ורגע מתהוות כל ה־בריאה מחדש ממש כמו במעשה בראשית (ראה שער היחוד והאמונה בתחילתו)."],["27","27","ילקו\"ש תהלים רמז תשב. שו\"ע אדה\"ז מהדו\"ק סד ס\"א. ס\"ו ס\"א."],["28","28","להעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381148\" data-slug=\"likkutei-torah\" data-id=\"4001381148\">לקו\"ת שה\"ש ד, ד</a> שהת־חדשות ההתהוות דמע\"ב בכל יום היא ב„טובו\" בחינת אור (כי טוב) שנברא ביום ראשון."],["29","29","ומכיון שהאדם יכול לאמור „אור\" על ענין שבאמת הוא חשך [וע\"ד מ\"ש (ישעי' ה, כ) שמים חשך לאור גו'] ע\"י ההוראה „גנזו בתורה\" שה„אור\" שהאדם צריך לקבעו למטרת כל פעולותיו וכו' צ\"ל אור שהתורה אומרת עליו שהוא אור."],["30","30","שני הטעמים (המבוארים בפנים) להתהוות החושך שייכים רק ב„מציאות ה־חשך\", ולא בהעדר האור (ראה ד\"ה ויקח תרצ\"ה פכ\"ט), כי המציאות דחשך מכיון שהוא היפך האור ומנגדו א) אפ\"ל העבודה לבחור באור. ב) בזה גופא שהוא היפך האור ומנגדו יש לו שייכות לאור ולכן אפשר להפכו משא\"כ בהעדר האור (וע\"ד המבואר בתו\"ש"]]],[1300101020,"[לא רק בכדי לאפשר להאדם לבחור בטוב. דהרי לולא מציאות ה־„חושך\" (והרע) לא הי' שייך ענין הבחירה באור. שלפי\"ז מציאות החושך אינה איזה ענין של תכלית לעצמה, אלא אמצעי שע\"י תושג המטרה. אלא שגם בחשך גופא יש תכלית<sup data-n=\"31\">31</sup>]\n„לאהפכא חשוכא לנהורא\", שהאדם ע\"י עבודתו יהפוך אותו עצמו ל־אור<sup data-n=\"32\">32</sup>.\nי. והנה בכדי שלא יחשוב האדם בנפשו: איך יוכל לעשות מהעולם, שהוא „תוהו ובהו וחושך\", שיהפך ויהי אור — ועאכו\"כ להפוך את החושך עצמו לאור — ע\"ז נאמר לפני זה „בראשית\" גו': „בשביל ישראל שנק' ראשית ובשביל התורה שנק' ראשית\"<sup data-n=\"33\">33</sup>. שכוונת התהוות ה־עולם (והחושך) היא מלכתחילה<sup data-n=\"34\">34</sup> בשביל ישראל ובשביל התורה — שישראל ע\"י התורה יהפכו אותם לאור — וכוונה זו הרי היא עצמה הסיוע והנתינת כח להצליח בעבודה זו.\nוע\"י העבודה בשית אלפי שנין, להאיר את העולם באור התורה וה־מצות נזכה לגילוי דלעתיד שיתגלה האור שנברא ביום ראשון, ועד ש„לא יהי' לך עוד השמש לאור יומם גו' והי' לך הוי' לאור עולם\"<sup data-n=\"35\">35</sup> בביאת משיח צדקנו בקרוב ממש.\n(משיחת ליל שמח\"ת, תשכ\"ו)",[["","","(ע' 10. וראה גם קונטרס התפלה פ\"ח) שנה\"ב הנק' „שור\" להיותו „נוגח\" „ובועט\" בענינים של קדושה יש בו מעלה על נה\"ב הנקרא „עז\" שאינו מתפעל כלל משום דבר, כי זה גופא מה שה„שור\" מתפעל מקדושה (שהרי הוא נוגח ובועט) מורה שיש לו שייכות לקדושה). ועפ\"ז מובן מאמר הצ\"צ (להרשב\"ץ): חשך קען מען ניט מעלה זיין נאָר מען דאַרף עס מדחה זיין — אף שמבואר בכ\"מ שהתכלית היא „אתהפכא חשוכא לנהורא\" — כי כוונת הצ\"צ היתה לא להמציאות וחשך (דהרי אצל הרשב\"ץ לא הי' שייך חשך כזה), כ\"א, ל„העדר האור\"."],["31","31","ואופ\"ל שבזה מחולקים ר\"י ור\"נ בב\"ר רפ\"ג, אם האורה נבראת תחלה (גם לפני בריאת שו\"א): ר\"נ סובר שבריאת האור הי' לאחרי בריאת (העולם כפי שהוא חשוך, היינו) החשך. כלומר, שצריך להעלות את החושך, אבל לדעתו העלאתו היא ע\"י שהאדם מת־גבר על עצמו ובוחר בטוב ואור ולא בחשך. ולכן הוא סובר ש„העולם נברא תחלה\" — לפני האור והמטרה ומחוצה לה. דהיינו שהחשך אינו נכלל בכל עניני הבריאה שמ־טרתן הוקבעה לפניהן — להפכן לאור, אבל בריאת מציאות החשך, מכיון שאין הכוונה להפך אותו עצמו לאור, נברא מקודם — ז.א. בלי מטרה עצמית. ור\"י סובר, שגם בריאת מציאות החושך היא בכדי שהאדם יהפוך אותה לאור. ולכן אומר ש„האורה נבראת תחילה\" והיינו שהמטרה של כל הבריאה — „יהי אור\" — כוללת גם מציאות החשך, לעשות אור."],["32","32","הטעם לזה שיש גם „העדר האור\" — אף שאינו מאפשר ענין הבחירה באור, וגם א\"א להפכו (כבהערה 30) — כי א) אינו „יש\", כ\"א מצב שנתהווה בדרך ממילא בהסתלקות האור. ב) זהו מעין האין שצ\"ל בין יש ליש (ד\"ה תפול עליהם אימתה — תורת חיים פ' בשלח ע' רסו, א. ובכ\"מ)."],["33","33","פרש\"י ר\"פ בראשית. וראה גם ב\"ר רפ\"א. ויק\"ר פל\"ו ד."],["34","34","והיינו שזהו ענינה של הבריאה גופא (ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061102\" data-slug=\"likkutei-sichot\" data-id=\"1300061102\">לקו\"ש ח\"ו ע' 91</a> ואילך) ולכן מובן שהבריאה עצמה מסייעת לזה."],["35","35","ישעי' ס, יט."]]],[1300101021,"א. כבר דובר כ״פ<sup data-n=\"1\">1</sup>, שדרכו של רש״י ליישב בפירושו את כל דבר הקשה בפי׳ הפשוט של הכתובים. ובמקום שמתעוררת איזו קושיא ב־פשטות הבנתם של הכתובים ואין הוא עומד עלי׳ לפרשה וליישבה — ה״ז גופא הוכחה שלדעתו של רש״י אין זו קושיא כלל<sup data-n=\"2\">2</sup>, עד שאין צורך להעיר עלי׳ ולפרשה, כי הענין מובן ומתפרש מעצמו.\nעפ״ז צלה״ב: מהו טעמו של רש״י במה שאינו מעיר מאומה ביישובה של קושיא פשוטה, לכאורה, המתעוררת בלימוד הפסוקים דפרשתנו<sup data-n=\"3\">3</sup>; וכדלהלן.\nממ״ש<sup data-n=\"3\">3</sup> „ויאמר הנחש וגו׳״ (ופע־מיים) ואין רש״י מפרש כלום מה טיבה של אמירה זו של הנחש (דלא ככו״כ מפרשים<sup data-n=\"4\">4</sup>), מוכח שפירושה של תיבת „ויאמר״ הוא בפשטות — בזמן ההוא הי׳ הנחש בטבעו<sup data-n=\"5\">5</sup> מדבר, כמו בנ״א (אף שלא מצינו כזאת בשום בע״ח אחר); והיות שהנחשים עכשיו (שהם „זרעך״<sup data-n=\"6\">6</sup> של אותו נחש) אין להם כשרון הדיבור, הרי בע״כ צ״ל שלאחר זמן נלקח ממנו כשרון זה, ומסתבר לומר שזה אירע בנחש<sup data-n=\"7\">7</sup> ה־קדמוני: בהקללות שנתקלל בהן הנחש עבור חטאו<sup data-n=\"8\">8</sup>, היתה גם הקללה שלא יוכל לדבר עוד. אלא דא״כ אי״מ: למה לא פירש הכתוב שנתקלל הנחש גם בזה שנסתם פיו מלדבר? קושיא בפשטות הבנת הכתוב, ואיננו מוצאים תירוץ עלי׳ בפרש״י.\nואין לתרץ, שמטעם זה גופא (מכיון שממין הנחשים בזה״ז מוכח ש„נסתם פיו״ של אותו נחש הקדמוני בסיבת הקללה על חטאו) אין הכתוב צריך לפרשו; ומחמת גודל פשיטות הענין רש״י אין צריך להסביר מדוע לא נתפרש בכתוב.\n— כי בזה מתורץ רק הא דהכתוב (ופרש״י) אין צריך להודיענו דבר המובן מעצמו; אבל בנדו״ד הרי ה־קושיא היא: למה לא נזכר זה ב־דברי „ה׳ אלקים אל הנחש״ במה יהי׳ עונשו?\nב. והנה לכאורה אפשר הי׳ לתרץ שעונש זה נכלל במ״ש „ארור אתה מכל הבהמה ומכל חית השדה״, דמכיון שנאמר „ארור אתה מכל הבהמה ומכל",[["1","1","ראה גם לקמן ע׳ 129. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131105\" data-slug=\"likkutei-sichot\" data-id=\"1300131105\">לקו״ש חי״ג ע׳ 105</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300141106\" data-slug=\"likkutei-sichot\" data-id=\"1300141106\">חי״ד ע׳ 94</a>."],["2","2","כי כשאין תירוץ ע״ד הפשט — כותב רש״י „איני יודע״ (תולדות כח, ה) וכיו״ב."],["3","3","ג, א־ד."],["4","4","ראה תורה שלימה כאן. וש״נ."],["5","5","דהרי אין לומר שהקב״ה עשה נס מיוחד בכדי שיוכל הנחש לדבר עם חוה אז (ראה חזקוני עה״פ. ועוד) כי: א) כשאתונו של בלעם דיברה, היפך הטבע, מפורש בכתוב (בלק כב, כח) „ויפתח ה׳ את פי האתון״ בכדי לתרץ איך אפשר שאתון תדבר *), וא״כ גם כאן הי׳ צריך לפרש. ב) ועיקר: וכי יעשה הקב״ה נס מיוחד, למעלה מגדרי הטבע, בכדי לנסות את חוה וכ״ש — בכדי להחטיא אותה וכו׳? *) ובחז״ל (אבות פ״ה מ״ו) שהי׳ צ״ל בריאה מיוחדת בע״ש ביה״ש."],["6","6","פרשתנו שם, טו."],["7","7","יחידי — ובדרך ממילא הי׳ כן בכל זרעו."],["8","8","שם, יד. טו."]]],[1300101022,"חית השדה״, גרוע מכל הבע״ח, הרי מובן שיסתם פיו מלדבר (כמו שהוא בנוגע לזה שהי׳ „ערום מכל וגו׳״ ולאחרי הקללה ניטלה ממנו הערמה), דאל״כ אין הוא „ארור״ מכל גו׳, כ״א ואדרבא חשוב מכולם ביתרון דחוש הדבור — ולכן לא הי׳ הקב״ה צריך לפרטו בפני עצמו.\nאבל עפ״ז אי״מ: למה פירט העונש ד״על גחונך תלך״? הלא גם עונש זה נכלל ב״ארור אתה מכל גו׳״ דכולל ג״כ „כל חי׳ הרומשת״ שאין לה רגלים<sup data-n=\"9\">9</sup> — ובמילא מובן שנכלל בזה שגם העונש ד״קציצת הרגלים״, שלא תהי׳ עדיפות בנחש לגבי ה־רמשים.\nובשלמא אם הי׳ בא ענין זה בתור סיפור התורה לנו, מן ההכרח הי׳ לפרש העונש „דקציצת הרגלים״, כי לולא זאת לא היינו יודעים דמעיקרא היו לו רגלים ונענש ונקצצו, אבל בהאמירה להנחש (שזה הוא מה ש־נכתב בכתוב) „ארור אתה מכל״ שכולל גם העונש ד״על גחונך תלך״ כנ״ל, א״כ הרי מיותר מש״כ אחר זה „על גחונך תלך״?\nומזה מוכח לכאורה ש״ארור אתה מכל וגו׳״ נאמר כהקדמה כללית לה־עונשים המפורטים להלן<sup data-n=\"10\">10</sup>, ולא היתה הכוונה בתיבות אלו עצמן להעונשים הפרטים — ושוב הדרא קושיא ל־דוכתא: למה לא פורש בהאמירה שיוקח ממנו כשרון הדבור?\nג. אמנם באמת י״ל שהפירוש בזה הוא כנ״ל (ש״ארור אתה מכל וגו׳״ היינו הקללה שיסתם פיו) — ובהק־דים מה שאמר הקב״ה להנחש בתחלת דבריו: „כי עשית זאת (ארור אתה מכל וגו׳)״ — דלכאורה תיבות אלו מיותרות הן<sup data-n=\"11\">11</sup>, דהרי מהמשך הסיפור מובן ופשוט שהעונש הוא עבור ה־חטא<sup data-n=\"12\">12</sup>? וי״ל כי הכוונה בזה להסבירו במה הוא ארור מכל ולמה בזה דוקא — היינו שבאותו דבר ש״עשית זאת״, בזה (במדה כנגד מדה<sup data-n=\"13\">13</sup> ) יהי׳ „ארור״.\nוהנה הדבר העיקרי שעל ידו הי׳ אפשר להיות כללות פעולתו של ה־נחש להחטיא את חוה (שבאה באופן מסוים ע״י שהי׳ ערום, וכדלקמן) הי׳ כח הדיבור שלו, כי בלעדו לא הי׳ יכול לבוא בדברי הסתה לחוה<sup data-n=\"14\">14</sup>, ולכן ע״פ הנ״ל במילא מובן שהעונש",[["9","9","שהרי גם קודם החטא היו חיות כאלו (ראה פרשתנו א, כד (ובפרש״י שם) א, כה)."],["10","10","כהפי׳ השני בחזקוני עה״פ."],["11","11","ואף שפרש״י „מכאן שאין מהפכים בזכותו של מסית שאילו שאלו למה עשית זאת וכו׳״ — הרי מזה שכותב „מכאן וכו׳״ מוכח שזהו דבר הנלמד מכאן, אבל לא שזהו הטעם למה כתובין תיבות אלו, ובפרט — שגם בלא תיבות אלו נדגש שלא שאל אותו הקב״ה „למה עשית זאת״, אלא ש ע״י תיבות אלו, ה״ז מתחזק. (ודוחק לומר שאם לא הי׳ כתוב „כי עשית זאת״, הי׳ אפ״ל ששאלו, ורק שלא נכתב בתורה)."],["12","12","אבל ממ״ש אח״כ (ג, יז) „ולאדם אמר כי שמעת לקול אשתך וגו׳״ (ראה אוה״ח כאן, חזקוני כאן) — הרי בלא תיבות אלו אינו ברור למה נענש, שהרי הצטדק „האשה אשר נתתה עמדי היא נתנה וגו׳״ (שם, יב), ולכן הוצרך לפרש כי שמעת לקול אשתך גו׳."],["13","13","ראה פרש״י נח ז, יא. יתרו יח, יא. נשא ה, כד. ועוד. וכן מובן בפשטות."],["14","14","משא״כ „ואיבה אשית בינך ובין האשה וגו׳״ לא נכלל ב״כי עשית זאת ארור אתה וגו׳״, אף שגם בזה פרש״י „אתה לא נתכוונת אלא שימות אדם כו׳ ותשא את חוה כו׳ לפיכך ואיבה אשית״, היינו שמהגורמים ל״כי עשית זאת״ היתה האהבה"]]],[1300101023,"„כי עשית זאת ארור אתה מכל וגו׳״, מכוון בעיקר<sup data-n=\"15\">15</sup> לכח הדבור שלו (וגם להערמה שלו); והיינו שהנחש יהי׳ גרוע (״ארור״) בענין זה מכל הבהמות והחיות — היינו שלא זו בלבד שלא יעלה עליהם ביתרון דכח הדבור, אלא שגם עוד תחסר לו התכונה שישנה בהם — להשמיע קולות שונות: נהי־מה, שאגה וכו׳, מה שאינה עוד בה־נחש, כי נסתם פיו לגמרי<sup data-n=\"16\">16</sup>.\nועפ״ז מובן שהקללה ד״על גחונך תלך״, היות וההליכה ברגל לא הי׳ גרם לחטא ההסתה, אינה נכנסת בכלל „כי עשית זאת ארור אתה וגו׳״, ולכן מן הצורך לפרטו, כמו שצריך לפרט שאר הקללות („ועפר תאכל וגו׳ ואיבה אשית וגו׳״) מפני שלא נכללו בארור אתה.\nד. אולם יש להקשות בעצם הענין: למה הי׳ צריך לקללו שיהי׳ גם גרוע (בחוסר השמעת קול) מכל החיות? לכאורה הי׳ די לענשו בנטילת כח דיבורו (הדבר שהביאו לידי חטא) וישאר בדומה לכל הבהמה וגו׳?\nאמנם קושיא זו מיושבת בדרך ממילא במה שכבר כתבה התורה ב־הקדמה לפרשה זו: עה״פ „והנחש הי׳ ערום מכל חית השדה אשר עשה ה׳ אלקים״ ופרש״י: „ערום מכל — לפי ערמתו וגדולתו היתה מפלתו, ערום מכל ארור מכל״, דבפשטות כוונת רש״י היא\n[לא לפרש כוונת כל הכתוב „והנחש הי׳ ערום וגו׳״<sup data-n=\"17\">17</sup>,\nדא״כ: א) הו״ל להעתיק מן הכתוב גם תיבות „והנחש (ולהוסיף) וגו׳״ (ועכ״פ להעתיק<sup data-n=\"18\">18</sup> — „הי׳ ערום וגו׳״) ובזה יהי׳ מובן שבא לתת טעם למה נכתב כל הענין הלזה. ב) לפי״ז מספיק אם הי׳ כתוב בקרא „והנחש הי׳ ערום מכל חית השדה״ מבלי להוסיף „אשר עשה ה״א״. ג) ועיקר: כוונת הכתוב, במה שאמר „והנחש הי׳ ערום וגו׳״ מובנת בפשטות: היות ותמוה הדבר איך הי׳ יכול הנחש להטעות את חוה שהיתה במעלה גדולה בהיותה יצירת „כפיו״ של הקב״ה (כמ״ש<sup data-n=\"19\">19</sup> „ויקח אחת מצלעותיו וגו׳ ויבן ה״א וגו׳ לאשה״)<sup data-n=\"20\">20</sup>, לזה מקדים הכתוב שה־",[["17","17","כמו שפי׳ במשכיל לדוד."],["18","18","אם נאמר שתיבת „והנחש״ אינה מיותרת, כי בלא״ה הי׳ צריך לכתוב „ויאמר הנחש אל האשה וגו׳״."],["19","19","פרשתנו ב, כא."],["20","20","וי״ל שזהו גם מהטעמים דרש״י לפרש (ג, ד) „דחפה עד שנגעה בו, אמר לחוה *), ולעומת זה נתקלל ב״ואיבה אשית וגו׳״ — כי: א) לא האהבה לחוה עצמה גרמה לזה, כמובן (וכדיוק לשון רש״י (ג, א): „ראה אותם וכו׳״), ובמילא לא הי׳ מובן מעצמו שנכלל „ואיבה אשית וגו׳״ בהקללה [עד שבכלל הוצרך רש״י לפרש הטעם על קללה זו]. ב) ועיקר: אין זה דבר שעל ידו החטיאה, כ״א זוהי סיבה להחטא."],["15","15","אבל מובן שאין זה כל כוונתו — וכלולה בזה גם הקדמה כללית, וכדלעיל. וגם מרמז לעוד ענין כפרש״י על התיבות „מכל הבהמה ומכל חית השדה״."],["16","16","ועפ״ז יומתק פרש״י עה״פ (פרשתנו שם, טו) „ואתה תשופנו עקב״: „ולשון תשופנו כמו נשף בהם (ישעי׳ מ, כד) כש־הנחש בא לנשוך הוא נושף כמין שריקה כו׳ כתב לשון נשיפה בשניהם״ — שכוונתו בזה, שאצל שאר בהמות וחיות ישנם עכ״פ קולות וכו׳, משא״כ בנחש רק „כמין שריקה״. *) וגם בהדברים שאמר הנחש בגלוי, הראה שרוצה הוא טובת האשה וכו׳ („ונפ־קחו עיניכם והייתם כאלקים יודעי טוב ורע״), שבפשטות הרי זה ענין של קירוב הדעת וכו׳."]]],[1300101024,"„נחש הי׳ ערום״, ולא ערום סתם, כ״א „מכל חית השדה אשר עשה ה״א״<sup data-n=\"21\">21</sup>, ולכן הי׳ ביכלתו להטעותה<sup data-n=\"22\">22</sup>: אלא שכוונתו לפרש]\n— מהו הטעם להדגשת קרא „וה־נחש הי׳ ערום מכל וגו׳״<sup data-n=\"23\">23</sup> — ולא נאמר בקיצור „והנחש הי׳ ערום״, או „ערום מאד״, ומשו״ז הי׳ ביכלתו להטעות את חוה<sup data-n=\"24\">24</sup>?\nע״ז פרש״י שהכתוב (ע״י הוספת תיבת „(ערום) מכל״ בא לתרץ ה־קושיא הנ״ל (שבתחלת הסעיף) — למה היתה מפלתו גדולה כ״כ, שיהי׳ גרוע מכל החיות? — וע״ז הוא ה־תירוץ: „לפי ערמתו וגדולתו היתה מפלתו״, ולכן מוסיף הכתוב שהי׳ „ערום מכל״, להודיענו שלעומת זה נענש אח״כ להיות „ארור מכל״.\nה. והנה עפ״י הנ״ל יובן ג״כ מ״ש רש״י כפי׳ על תיבת „ערום״ — „ערמתו וגדולתו״ — דלכאורה: מהו הפי׳ של „וגדולתו״? דאין לומר שפירושה גדולות בגשמיות, או בכח גשמי וכיו״ב, דא״כ מה ענינה כאן, בהקדמה זו שבאה לבאר איך יכול להטעות את חוה וכו׳?\nואין לומר ש„וגדולתו״ הוא פירוש לתיבת „ערמתו״, דא״כ למה לכתוב מעיקרא „ערמתו״ (שזוהי לשון הכ־תוב עצמו „ערום״), ולפרשו — הו״ל לכתוב רק תיבת „גדולתו״ בלבד<sup data-n=\"25\">25</sup>, והי׳ מובן מעצמו שבאה לפרש תיבת „ערום״?\nוגם: מנ״ל לרש״י — בפי׳ הפשוט של הכתובים — שבתיבת „ערום״ מרומז עוד ענין?\nאמנם עפ״י הנ״ל ה״ז מובן: מכיון שכוונת פסוק זה היא להסביר במה הי׳ כחו ויכלתו של הנחש להחטיא את חוה, הרי בהכרח לומר שבנוסף ע״ז שהי׳ ערום<sup data-n=\"26\">26</sup> היתה לו עוד",[["","","לה כשם שאין מיתה בנגיעה כך אין מיתה באכילה״ — כי בלא״ה אינו מוסבר עדיין כל צרכו איך הי׳ יכול להטעותה, ולכן צ״ל שהראה לה שבפועל אינה מתה (ואף ש„הוסיפה על הציווי״ באמירתה „ולא תגעו בו״ (פרש״י שם) — כבר עמדו ע״ז ה־מפרשים)."],["21","21","אבל לא שהי׳ ערום גם ממנה *) (כמ״ש הרא״ם והגו״א) — כי א״כ העיקר חסר מן הספר ודוקא בהטפל מאריך „מכל הבהמה ומכל חית השדה״! אלא הכוונה שהי׳ ערום בכלל (ולא ממנה) — ובמילא מובנת האפשריות להטעותה (אף שבד״כ היתה היא ערומה ממנו). וראה לקמן הערה 24."],["22","22","ואין להקשות דגם זה מובן מעצמו, ממ״ש אח״כ „אף כי אמר אלקים לא תאכלו מכל עץ הגן״ שפירושו „הרבה עלי׳ דב־רים וכו׳״ (פרש״י שם) שזוהי ערמה — כי זה עצמו, שכ״ה הפי׳ שם, מובן רק ע״י שהקדים „והנחש הי׳ ערום״, כי בלא״ה י״ל שבאמת חשב הנחש שהקב״ה אמר להם שלא לאכול מכל עץ הגן."],["23","23","אף שמוכח מכתוב זה עצמו ש־לפועל הי׳ „ערום מכל וגו׳״ — מ״מ מה זה נוגע לידע (ובפרט כהקדמה) בהפ׳ דילן?"],["24","24","ע״ד פי׳ הרא״ם וגו״א. אבל אין לומר שהקושיא היא ממש כמו שכתבו „וכי אם לא הי׳ ערום מכולם, אע״פ שהי׳ ערום ממנה, לא הי׳ יכול לפתותה״ (נוסף על הנ״ל בהערה 21) — כי אין מסתבר כלל בפשש״מ שכמה חיות תהיינה ערומות מן הנחש, ואעפ״כ יהי׳ ערום מן האשה!"],["25","25","כבב״ר פי״ט, א."],["26","26","וכפרש״י אח״כ „הרבה עלי׳ דברים כדי שתשיבנו ויבוא לדבר באותו העץ״. *) וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370020\" data-slug=\"torah-or\" data-id=\"3901370020\">תו״א בראשית ה, ג</a>: „אם לא שנאמר שגבוה הוא מהאדם וכו״ז פלאי״. ולשון זה משמע שכ״ה גם בפשטות. אבל יש לחלק בין „ערום״ ל„גבוה״. וראה חזקוני עה״פ שהנחש אכל מעץ הדעת, אבל אין שום רמז לזה בפשוטו של מקרא."]]],[1300101025,"תכונה שבה ועל ידה הי׳ יכול לבטא ערמתו — והיינו שהי׳ לו כח ה־דיבור; וה״ז מרומז בתיבת „ערום״ — ערום בכל פרטי תואר זה, בכח ובפועל. ולזה מכוין רש״י בפירושו, לפרט הדברים שהביאוהו וסייעו בידו להחטיא את חוה: „ערמתו ו(עוד) גדולתו״, היינו „גדולה״ (מעלה ב־„ערום״ — שמגלה ומפעילה את ה־ערמה) שבה הי׳ ניכר והצטיין מכל בעלי־החיים — ומעצמו מובן שהכוונה לכח הדבור<sup data-n=\"27\">27</sup> שהי׳ לו<sup data-n=\"28\">28</sup>.\n[ואתי שפיר ג״כ מה שלא מצינו מפורש בל׳ הקללה שתסתלק הערמה ממנו — כי גם עונש זה נכלל בזה שאמר „כי עשית זאת, ארור אתה מכל וגו׳״ — בהיות כי הערמה היתה הגרם העיקרי לעשייתו זאת].\nוזהו שמסיים רש״י „ערום מכל ארור מכל״, שכוונתו ב„ערום מכל״ לב׳ הענינים שהביאוהו לחטוא: הערמה וכח הדבור, וכנגדם נתקלל ב„ארור מכל״, וכנ״ל, שגם בזה הכוונה לב׳ הדברים שגרמו ל„עשית זאת״.\nו. ההוראה מפרש״י הנ״ל:\nאמרז״ל<sup data-n=\"29\">29</sup> „מדה טובה מרובה מ־מדת פורענות״, שמזה מובן שאם ע״י החטא נענש ונהפך מ„ערום מכל״ ל־„ארור מכל״, הרי אכו״כ בצד הטוב, ש ע״י פעולה טובה אפשר ליהפך מן הקצה אל הקצה — מדרגא פחותה ביותר, „ארור מכל״, להתעלות להיות „ערום (דקדושה) מכל״.\nומרומזת הוראה זו דוקא בענין ה„נחש״, כי בכגון דא מצינו בו (ב־מקום אחר): כשנשכו הנחשים את בנ״י במדבר<sup data-n=\"30\">30</sup> התרופה לנשיכתם היתה עשיית נחש הנחשת ע״י משה רבינו<sup data-n=\"31\">31</sup>. ונתבאר<sup data-n=\"32\">32</sup> דגם זה הי׳ ה־ענין של אתהפכא מן הקצה אל הקצה, שה„נחש״ גופא, שענינו מיתה (דהרי גרם לחטא עה״ד, שגרם מיתה ל־עולם) נהפך — להיות על ידו פעולת החיים<sup data-n=\"33\">33</sup>.\nומכיון ש„הקב״ה מקדים רפואה ל־מכה״<sup data-n=\"34\">34</sup>, לכן עוד בהחטא גופא, בעת שגרם הנחש לירידה גדולה, אז כבר מרומז ענין הנ״ל שאפשר להתהפך מן הקצה אל הקצה, להתעלות ממ־קום החטא והמיתה, ולהתקשר לבחי׳",[["27","27","ולהעיר מהמבואר ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380358\" data-slug=\"likkutei-torah\" data-id=\"4001380358\">לקו״ת (במדבר יב, ג</a> ואילך. ובכ״מ בדא״ח) בנוגע למארז״ל (זח״ב רלה, א ובכ״מ) „אימתי נקרא גדול כשהיא בעיר אלקינו״ — „שבחי׳ גדולה והתפשטות זו נק׳ בשם דיבור״."],["28","28","והא דאינו כותב „ודיבורו״, כי: א) בהסגנון שכותב רש״י „לפי ערמתו כו׳ היתה מפלתו״ אין מתאים הלשון „ודיבורו״, כי בסגנון זה הכוונה (לא לענין הדיבור כשלעצמו, כ״א) לענין הדיבור כמו שהוא מעלה — וע״ז מתאים לומר שלפי מעלתו (זו) היתה מפלתו (משא״כ בהלשון „ערמתו וגדולתו״ מודגש שזוהי מעלה). ב) על ענין הדיבור אינו מתאים לומר „מכל הבהמה גו׳״, כי אינו בגדר דיבור לומר שהוא מדבר יותר מהן, משא״כ לומר שיש לו מעלה לגבן, מתאים לומר, אף שבנדון דידן — המעלה היא בדבר שאינו בגדרן כלל."],["29","29","סוטה יא, א. וש״נ. פרש״י יתרו ב, ו. תשא לד, ז."],["30","30","חקת כא, ו."],["31","31","שם, ח-ט."],["32","32","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131075\" data-slug=\"likkutei-sichot\" data-id=\"1300131075\">לקו״ש חי״ג ע׳ 75</a> ואילך. עיי״ש בארוכה."],["33","33","ולהעיר שבאוה״ת בראשית (מח, א) מציין „ע״ד מ״ש בלקו״ת פ׳ חקת סד״ה ויעש משה נחש נחשת . . ועי״ז גם אויביו ישלים אתו כו׳״."],["34","34","ראה מגילה יג, ב."]]],[1300101026,"עצמות אוא״ס שלמעלה מבחי׳ מקור החיים, שמשם הכח „להחיות את ה־מתים״<sup data-n=\"35\">35</sup> — והיינו ע״י שמסתכלים כלפי מעלה בתשובה שלימה וכו׳<sup data-n=\"36\">36</sup>.\n(משיחת ש״פ בראשית, תשל״ג)",[["35","35","ד״ה יהיינו מיומיים תש״א פ״א."],["36","36","ר״ה כט, א. פרש״י חקת (שם, ח). וראה לקו״ש שם ס״ג."]]],[1300101027,"<h3>נח</h3>\nא. עה״פ¹ ״צהר תעשה לתבה״, מפרש רש״י: ״צהר — י״א חלון וי״א אבן טובה המאירה להם״.\nבפשטות כוונת רש״י היא — ש־מפרש² ״צהר״ כמו ״צהריים״³, אור. ופי׳ הכתוב הוא, שהקב״ה ציווה לנח לעשות דבר שע״י יהי׳ אור בהתיבה, ומביא רש״י ב׳ פירושים מה הי׳: ״י״א חלון״ — שעל ידו יכנס אור בהתיבה, ולכן נקרא החלון כאן בשם ״צהר״; ״וי״א אבן טובה (ולמה נק־ראת כאן ״צהר״ ? מוסיף רש״י) המ־אירה להם״.\nוצלה״ב:\nא) בקרא כתיב ״צהר״, בלשון יחיד (ועד״ז פרש״י⁴ בל׳ יחיד: ״חלון״, ״אבן טובה״) — ואיך הספיק האור שנכנס ע״י חלון אחד או אבן טובה אחת — לכל התיבה, שהי׳ שלש מאות אמה ארכה, חמשים אמה רחבה ושלשים אמה קומתה⁵ ? !\nב) וביותר יקשה: כתוב ״קנים תעשה את התבה״⁶ ופרש״י: ״מדורים מדורים לכל בהמה וחי׳״ ו״תחתיים שניים ושלישים״. וא״כ, אפילו אם נדחוק אשר החלון שעשה נח הי׳ גדול ביותר, מכל מקום, איך יתכן שחלון אחד⁶ יאיר ״מדורים מדורים וכו׳״⁷ ?\nג) ידוע, שרש״י מפרש ב׳ פירו־שים בענין אחד באם כל אחד מהפי־רושים לבדו אין בו כדי ליישב הכתוב לפי פשוטו בכל הפרטים ; ומה שקשה לפי׳ האחד, אין להקשות לפי׳ השני ; והפי׳ הראשון הוא הקרוב יותר לפשו־טו של מקרא. ועפ״ז בנדו״ד : מה",[["1","1","פרשתנו ו, טז."],["2","2","וכ״פ בראב״ע, רד״ק ועוד."],["3","3","ראה פרש״י : פנחס כו, יג. מקץ מג, טז. ועי״ע ״זוהר״. וראה ת״א."],["4","4","ובפרט שרש״י משנה * מלשון הגמ׳ (סנה׳ קח, ב. ירושלמי פסחים פ״א ה״א (לפי הפ״מ שם שזה הי׳ ה״צהר״)) : אבנים טו־בות ומרגליות, ובב״ר פרשתנו (לא, יא) : מרגליות. בראב״ע כאן : וי״א כי רבים היו וה־כתוב אחז דרך קצרה. וראה גם בתו״ת כאן : דבאמת היו חלונות הרבה, והפי׳ חלון — מין חלון כמו ויהי לי שור וחמור (ר״פ וישלח). אבל [נוסף לזה, שא״כ הו״ל לרש״י לכתוב חלונות (בל׳ רבים), ולא לסמוך על מה שמפרש לקמן בפ׳ וישלח שם, הרי] מזה שרש״י משנה מלשון הש״ס וכו׳ וכ׳ ״אבן טובה״ בל׳ יחיד, מוכח שמפרש תיבת ״צהר״ בל׳ יחיד. *) ומה שרש״י כותב ״אבן טובה״ ולא ״מרגלית״ (ראה יל״ש כאן : אבן א׳ של מרגלית וכו׳) — כי ע״ד הרגיל מרגלית (שפירושה (גם) פנינים — אלא שלפעמים פירושה אבן טובה (ראה ערוך השלם מע־רכת מרגל)) אינה דבר המאיר, משא״כ אב־נים טובות יש מהן מינים שמאירים."],["5","5","שם, טו."],["6","6","שם יד. שם טז."],["7","7","בנוגע ל״אבן טובה״ י״ל (ע״ד ה־פשט *) שהיו מוליכים עמהם ה״אבן טובה״ לכל מדור וכו׳ (ראה לקמן ס״ג). אבל דוחק גדול לומר שזה הי׳ כל האור שהי׳ בכל התיבה. ועוד: הרי גם בניו עזרו אותו ליתן מזונות להבהמות וכו׳, ואיך הי׳ אור לכולם בב״א ? *) משא״כ בסנהדרין (שם) : קבע בת וכו׳."]]],[1300101028,"הם הקושיים בשני פירושים אלו שבש־בילם הוזקק רש״י להביא שניהם⁸ ? ובמה קרוב יותר הפי׳ הראשון לפשו־טו של מקרא מהפי׳ השני ?\nד) עפ״י הכלל האמור (דבכל אחד מפירושיו מיישב רש״י מה שקשה לפי־רוש השני) מובן, דכאשר יש קושיא לשני הפירושים, ויש פירוש שלישי המיישב קושיא זו, יביא רש״י גם את הפירוש השלישי [אף אם גם בפי׳ זה ישנו דבר הקשה — ועוד קשה יותר מהקושיים שבב׳ פירושים הראשונים, שלכן יבוא פי׳ זה ברש״י כפירוש שלישי]⁹ ?\nועפ״ז בנדו״ד : כיון שלב׳ הפירושים קשה כנ״ל, דאיך האירו חלון א׳ ואבן טובה א׳ את כל התיבה — מדוע לא פרש״י (כפירוש החזקוני ד)״צהר״ מ־לשון ״יצהר״ — שמן ; וכוונת הכתוב היא, שנח יביא שמן לתיבה, בכדי שיוכל להדליק בה נרות להאירה¹⁰ ?\nואף את״ל שדוחק לפרש ״צהר״ מל־שון ״יצהר״ ; וגם קשה לשון הכתוב ״צהר תעשה לתבה״ — אבל לאידך, הרי דוקא לפירוש זה תתיישב התמי׳ האמורה. ועכ״פ, הו״ל לרש״י להביאו כפירוש שלישי ?\nב. לקמן עה״פ¹¹ ״ויום ולילה לא ישבותו״ פרש״י : ״מכלל ששבתו כל ימות המבול שלא שמשו המזלות ולא ניכר בין יום ובין לילה״. ועפ״ז תמוה ביותר — כמו שהקשה הרא״ם¹², ״מה תועלת חלון התיבה אם לא הי׳ אור בכל יום מימי המבול ? ! ״\nוהנה, מפרשי רש״י¹³ תירצו, דכ־וונת ״לא שמשו המזלות״ היא לתנו־עת הגלגלים, היינו שכל ימות המבול נתבטל היקפם וסיבובם, אבל הי׳ קצת אור בעולם.\nאולם כבר נתבאר כמ״פ שרש״י כתב פירושו בסגנון ברור, באופן שגם בן חמש (למקרא) לא יטעה בכוונתו. ובנדו״ד : פירוש הפשוט של דבריו ״מכלל ששבתו . . . שלא שמשו המז־לות״ הוא, שלא עשו שימושם ותפקי־דם — ״להאיר על הארץ״¹⁴, ולא רק שנתבטלה תנועת הגלגלים.\nלכאורה יש מקום לתרץ קושיית הרא״ם, ולפרש שכוונת רש״י (ע״ד",[["8","8","בראם וגו״א ולבוש האורה כאן ש־למ״ד ״חלון״ קשה למה לא כתב חלון וכמ״ש (פרשתנו ח, ו) ״ויפתח נח את חלון התבה״ — אבל ע״ד הפשט אי״ז קושיא, דהציווי הי׳ רק בנוגע לאור, (ולא להכנסת אויר, חפצים וכיו״ב) ולכן נאמר ״צהר״ המורה על אור (וראה גו״א ודברי דוד כאן). אלא שלאחרי שכבר נעשה לצהר (ראה פרש״י שם) נשתמש בו גם לענין אחר — שילוח העורב — שהרי הי׳ בדרך ממילא — ״חלון״."],["9","9","לדוגמא: פרש״י מקץ מא, מג ד״ה אברך (נתבאר בארוכה לקר״ש ח״ה ע׳ 204 ואילך. וראה גם ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131041\" data-slug=\"likkutei-sichot\" data-id=\"1300131041\">לקו״ש שם ע׳ 41</a>, 259)."],["10","10","ולכאו׳ דוחק לומר (כבלבוש האורה כאן) דכיון ״שתרד התיבה ותעלה בעת שטי־פת המים״ יטה השמן ויכבה האור (ועד״ז — שעוה או שמן קרוש ״לפעמים יכבה פתאום״). וראה פי׳ הרד״ק שבהערה 22."],["11","11","פרשתנו ח, כב."],["12","12","שם. וראה גם בחזקוני וטור הארוך כאן. בטור הארוך תירץ ולמ״ד חלון ״הוצ־רך לחלון לכמה דברים וכן מצינו לבסוף שהוצרך לו בשליחות העורב כו׳״ — אבל לכאו׳ מזה שהציווי הי׳ ״צהר תעשה״ מוכח שבעיקר הי׳ בשביל אור (ראה לקמן ס״ג)."],["13","13","שפ״ח ומשכיל לדוד שם."],["14","14","בראשית א, טו."]]],[1300101029,"הפשט¹⁵ במ״ש ״(ששבתו) כל ימות המבול״, היא רק להמ׳ יום שהי׳ המ־בול וכמש״נ¹⁶ ״ויהי המבול ארבעים יום על הארץ״¹⁷ ;\nולאחרי מ׳ יום אלו, כבר שמשו המזלות והיתה תועלת בהחלון שנעשה ל״צהר״ — להאיר את התיבה¹⁸.\nאבל עדיין נשארה התמי׳ : להיש אומרים ד״צהר״ הוא ״חלון״ — מה האיר את התיבה במשך כל המ׳ ימים שלא שמשו המזלות¹⁹ ? !\nג. והביאור בכ״ז :\nבציווי הקב״ה לנח על עשיית התי־בה, לא נאמרו כל פרטי הענינים שהיו בעשייתה. לדוגמא : מפורש בקרא²⁰ ״ויסר נח את מכסה התבה״, ולא מצי־נו שהקב״ה יצווה את נח לעשות המכ־סה. כן להפי׳ צוהר אבן טובה — לא מצינו שנצטווה לעשות החלון שנז־כר אח״כ. וכן לא מצינו שהקב״ה יצווה את נח לעשות פתח לתיבה (רק ציווהו על מקום הפתח — ״ופתח התבה בצדה תשים״).\nוהטעם : בפשוטו של מקרא מובן, שכאשר ציווה הקב״ה לנח לעשות תי־בה, לא הי׳ צורך לצוותו על כל הפ־רטים המוכרחים להיות בבנינה, כי מובנים הם מעצמם ; ורק פרטים אלו שנח לא הי׳ יודע מעצמו, ציווהו הקב״ה עליהם.\nולכן לא הי׳ צורך לצוותו על מכסה התיבה ופתח התיבה²¹ וכו׳, שהרי פשוט שמהענינים העיקריים בבנין התיבה הם המכסה והפתח וכו׳.\nועפ״ז מובן גם בנוגע להאיר את התיבה, שבעצם לא הוזקק נח לציווי מפורש מהקב״ה ע״ז, כי פשוט שצריך לעשות דבר שיאיר את התיבה. ובפרט שבתיבה הי׳ ״כל החי׳ למינה וכל בהמה וגו׳״, שמזונותיהם היו מוטלים",[["15","15","משא״כ ע״ד הדרש — ראה ירושלמי פסחים (שם) : ״לא שמשו המזלות בשנת המבול״. וכן בב״ר (פרשתנו לה, יא. וש״נ) : ״לא שמשו כו׳ י״ב חודש״, ולהעיר מפי׳ הרד״ק פרשתנו ח, כב."],["16","16","פרשתנו ז, יז."],["17","17","או עד לאחר ק״נ יום שאז (ח, ב) : ויסכרו . . . ארובות השמים ויכלא הגשם מן השמים — היינו שכל התלוי בהשמים (שהמזלות בכללם) — חזרו לסדרם."],["18","18","ראה מדרש אגדה (באבער) כאן. ועפ״פ המבואר בפנים יתורצו שאר קוש־יות הרא״ם — שכולם מהפסוקים שלאחרי מ׳ ימי המבול, עיי״ש."],["19","19","בפני משה לירושלמי פסחים (שם) כ׳ דהמ״ד שהי׳ אבן טובה ס״ל כהמ״ד שלא שמשו המזלות. ומשמע, דהמ״ד דס״ל ״חלון״ ס״ל כהמ״ד שלא שבתו המזלות בימי המבול. אבל אא״ל שמה שפרש״י ״לא שמשו המזלות״ הוא רק לפי פירושו ״אבן טובה״ (כמו שמצינו כמ״פ שרש״י מפרש פסוק רק לפי א׳ מפירושיו במקום אחר), אבל להמ״ד ״חלון״ שמשו המזלות גם בימי המבול — כי [נוסף לזה, שהמ׳ יום שירדו הגש־מים לא פתח נח החלון מפני הגשמים, כמובן (ראה מדרש אגדה (באבער) כאן *), הרי] כלל הנ״ל מתאים רק במקום שרק לפי א׳ מפירושיו יש צורך לפרש הכתוב, ולפי־רוש הב׳ מלכתחילה אין צורך לפרש ה־כתוב, ולכן מפרש רש״י הכתוב רק לה־פירוש שהכתוב צריך פירוש ; משא״כ בנדו״ד שפשטות משמעות הכתוב (״עוד כל ימי הארץ וגו׳ ויום ולילה לא ישבותו״) מוכיחה שהמזלות שבתו בימי המבול. *) אלא ששם איתא שמשום זה היו שניהם (חלון ואבן טובה) בהתיבה (וכ״ה בחזקוני כאן), משא״כ בפרש״י שמפורש שהן ב׳ דיעות."],["20","20","פרשתנו ח, יג."],["21","21","משא״כ בנוגע מקום הפתח — ראה ראב״ם וגו״א כאן."]]],[1300101030,"על נח, ועוד שכאו״א הי׳ במדור בפ״ע, כנ״ל — ובודאי הכין נח מעצמו נרות ושמן וכדומה להאיר את התיבה, גם בלי ציווי הקב״ה ע״ז²².\nאלא שעפ״ז מתעוררת השאלה : מדוע ציווה הקב״ה את נח ״צהר תע־שה לתבה״ — הרי בלא״ה בודאי הי׳ נח מכין במה להאיר את התיבה ?\nובהכרח לומר, שיש בזה ציווי מיוחד — היינו, שהקב״ה ציווה אותו לעשות ״צהר״ (— ענין של ״אור״) נוסף להאור שהכין מדעתו — בכדי להוסיף אור בתיבה.\nוב״צהר״ נוסף זה מפרש רש״י ב׳ פירושים : ״י״א חלון״ — שע״י הח־לון²³ הי׳ אור נוסף בהתיבה (אחרי\nהמ׳ יום שלא שמשו המזלות) ; ואף שע״י חלון א׳ לא נתוסף הרבה אור בהתיבה — הרי שימש החלון גם שמושים אחרים²⁴ (כגון להכניס ול־הוציא, לאוויר וכיו״ב).\nאלא שפירוש זה אינו מרווח כל כך, כי מזה ששינה הכתוב מלשון הרגיל (— ״חלון״) וכתב ״צהר״, בהכרח לומר שתפקידו העיקרי בתיבה הי׳ בשביל (תוספת) אור²⁵. והרי : א) חלון אחד אינו יכול להאיר רק חלק קטן של התיבה (כנ״ל ס״א), ב) לא נכנס אור בהתיבה ע״י החלון עד לאחרי מ׳ ימי המבול (כנ״ל ס״ב)²⁶.\nולכן מביא רש״י עוד פירוש : ״וי״א אבן טובה המאירה להם״ — שלפירוש זה, הרי יכולים להוליך את ה״צהר״ (האבן טובה) לכל חלקי התיבה, להאי־רם בעת הצורך ; וגם הי׳ משמש כ־״צהר״ כל הזמן שהיו בהתיבה.\nאלא שפירוש זה (אבן טובה) אינו מתיישב בלשון הכתוב ״צהר תעשה לתיבה״, והול״ל ״צהר תכניס לתיבה״ וכיו״ב²⁷. וגם : מדוע יצווה הקב״ה לעשות דבר בלתי רגיל לגמרי — להכין אבן טובה — בשביל תוספות אור בהתיבה ?\nומכיון שפירוש זה אינו מתיישב",[["22","22","ראה בפי׳ הרד״ק כאן. ולקמן ז, כב."],["23","23","כי למ״ד ״חלון״ *, הרי — לולי ציווי הקב״ה — אולי לא הי׳ נח עושה חלון(ות) להאיר את התיבה, כיון שבלא״ה הוצרך להכין נרות וכיו״ב להאיר את ה־תיבה בלילה וכשהי׳ החלון סגור. ועשיית חלון מחלישה הגנות התיבה מהמים (ראה פרש״י ד״ה בצדה תשים). *) משא״כ להמ״ד ״אבן טובה״, הרי ממש״נ (פרשתנו ח, ו) ״ויפתח נח את חלון התבה״ מוכח שעשה נח חלון מדעת עצמו. ועפ״ז יש לתרץ קושיית הרא״ם על מה שפרש״י (שם) ״את חלון התבה אשר עשה — לצהר כו׳״ — דמזה שנקט הלשון ״צהר״, מוכח שכוונתו למ״ש בקרא ״צהר תעשה לתבה״, וכהמ״ד ״חלון״ — והרי לעיל ״פירש אותו כמסופק י״א חלון וי״א אבן טובה״ (וראה גם בגו״א שם), — כי להמ״ד ״אבן טובה״ הרי מובן מעצמו מה שהפסוק מוסיף תיבות ״(חלון התבה) אשר עשה — כיון שעשאו נח על דעת עצמו, ולכן לפירוש ״אבן טובה״ אין הכתוב צריך פירוש (ראה לעיל הערה 19) ; משא״כ להמ״ד ״חלון״ הרי תיבות ״אשר עשה״ מיותרות, ולכן הוצרך רש״י לפרש שנכתבו בכדי שלא לטעות שהכוונה על הפתח (ראה בגו״א שם)."],["24","24","ראה טור הארוך שבהערה 12. שפ״ח ודברי דוד כאן. גו״א פרשתנו ח, ו."],["25","25","וכמו שפרש״י עה״פ (פרשתנו שם) ״ויפתח נח את חלון התבה אשר עשה״ : ״לצהר״."],["26","26","ולפי המדרש אגדה שבהערה 19 לא שימש החלון כלום המ׳ יום שירד הגשם."],["27","27","כבלבוש האורה כאן."]]],[1300101031,"בלשון הכתוב, לכן מביאו רש״י רק כפירוש שני, והראשון הוא פירוש העיקרי.\nועוד י״ל בזה (ועיקר) ובהקדם : מדובר כמה פעמים שרש״י בפירושו מיישב כל דבר הקשה ע״פ פשוטו של מקרא — ולכאורה בנדו״ד קושיא גדולה בלי תירוץ בפרש״י : כל ה־פרטים בציווי התיבה פרש״י טעם כאו״א, ומקדים ״ולמה״ (היינו — ש־צ״ל טעם) — ומהו הטעם ד״צהר״ ? ואי משום שילוח העורב כו׳ — ה״ה יכול לשלחו דרך הפתח.\nולכן פרש״י ״חלון״ — כיון דמ־עצמו לא הי׳ נח עושה חלון, שהרי נאמר לו ״והנני משחיתם גו׳״ דמס־תבר דנאמרו לו פרטי העונש כולל שלא שמשו המזלות.\nאבל בנוגע לפועל ״הורידין ברחמים אם יחזרו יהיו גשמי ברכה״²⁸ לכן גם נצטווה לעשות חלון.\nמשא״כ להפי׳ ״אבן טובה״ — ש־צ״ע טעם הציווי.\nד. מ״מינה של תורה״ שבפרש״י זה :\nההפרש בין האור שנכנס ע״י חלון להאור שע״י אבן טובה הוא : ״אור החלון הוא אור הבא מבחוץ, ואור אבן טובה מאיר מבפנים היינו מעצמותו ומהותו״²⁹.\nוב׳ ענינים אלו, הם שני אופנים בעבודת ה׳ : תכלית העבודה דתומ״צ היא לעשות ״צהר״ לתיבה — להכניס\nולגלות אור אלקי בעולם ; וזה יכול להיות בב׳ אופנים :\nהדרך הראשונה היא לעשות ״חלון״. והיינו, כי באמת ישנו אור האלקות ב־עולם, וכידוע³⁰ שהבעלי עסקים יכולים לראות השגח״פ בעניני העולם שלהם, ועוד יותר מאלו הנמצאים כל ימיהם בד׳ אמות של תורה ותפלה. אלא שבכ־די להגיע לזה, צריכים להסיר ההעלם וההסתר שישנו על האור האלקי — להסיר את לבוש ״הטבע״, שהוא הסתר על אלקותו ית׳ שלמעלה מהטבע. וזוהי מדריגה הראשונה בעבודת האדם, לע־שות ״חלון״ בהמחיצה וההסתר ד״ט־בע״, שיאיר בעולם אור האלקי של־מעלה מהטבע.\nואחר שכבר נעשה ה״חלון״ במחיצה של ״הטבע״, שמאיר בעולם האור של־מעלה מהטבע, הר״ז נתינת כח להאדם, להתעלות ולהגיע למדריגה ואופן נעלה יותר בעבודת ה׳ : ״וי״א — אלו שכבר עשו החלון — אבן טובה המאירה להם״ — היינו לא רק שמסירים ההע־לם והסתר דלבושי הטבע, אלא שמהפ־כים הטבע עד שנעשה הוא עצמו ענין של אור וגילוי³¹ — ״אבן (עצמה — נעשית אבן) טובה³² המאירה להם״.\n(משיחת ש״פ נח, תשל״א)",[["28","28","פרש״י ז, יב."],["29","29","ד״ה צהר תעשה לתבה תש״ב."],["30","30","היום יום ז׳ תשרי (ע׳ צג)."],["31","31","וע״ד ב׳ האופנים בבירור ה״חשך״ : הסרת החשך שלא יסתיר על האור, או שהחשך עצמו נהפך לאור (ראה בארוכה ד״ה צהר תעשה לתבה תרצ״ה)."],["32","32","שוהר היוקר (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380398\" data-slug=\"likkutei-torah\" data-id=\"4001380398\">לקו״ת נשא כב, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380825\" data-slug=\"likkutei-torah\" data-id=\"4001380825\">ראה כז, ב</a>. ועוד). ולהעיר מהפי׳ ב״מער־שים טובים״ (תו״א מג״א בתחלתו)."]]],[1300101032,"<h3>נח ב</h3>\nא. בשייכות למ״ש בפרשתנו<sup data-n=\"1\">1</sup>: „מן הבהמה הטהורה ומן הבהמה אשר איננה טהורה\", אמרו חז״ל בגמרא<sup data-n=\"2\">2</sup>: „לעולם אל יוציא אדם דבר מגונה מפיו שהרי עיקם הכתוב שמונה אות־יות ולא הוציא דבר מגונה מפיו, שנא' מן הבהמה הטהורה ומן הבהמה אשר איננה טהורה\". ופי' רש״י, שזהו הטעם לאריכות לשון הכתוב: „אשר איננה טהורה\" — ג' תיבות הכוללות י״ג אותיות — במקום שהי' יכול לקצר ולומר: „הטמאה\" (תיבה בת ה' אותיות) — „ללמדך לחזר אחר לשון נקי'\".\nוכמו שישנה הוראה בפרשתנו בנוגע לזהירות, בלשון, עד״ז יש ללמוד מ־פרשה זו עוד הוראה — בשייכות לזהירות בראי'. שם ויפת נזהרו, ב־תכלית הזהירות, מלראות „ערות אבי־הם\" — „וילכו אחורנית וגו' ופניהם אחורנית וערות אביהם לא ראו\"<sup data-n=\"3\">3</sup>, ושכר זהירות זו מדגיש גודלה וערכה: „ברוך ה' אלקי שם ויהי כנען גו' יפת אלקים ליפת וישכון באהלי שם גו' \"<sup data-n=\"4\">4</sup>.\nב. אמנם בסיפור הנ״ל צ״ל:\nאחרי שהכתוב אומר שהלכו באופן של „ופניהם אחורנית\" — הרי מזה מובן שלא ראו ערות אביהם (שהרי פניהם אחורנית) — מה מוסיף בתי־בות: „וערות אביהם לא ראו\"<sup data-n=\"5\">5</sup> ? ועכצ״ל שהכתוב מחדש בזה ענין ומעלה מיוחדת בהנהגת שם ויפת, אשר מתיבות הקודמות („ופניהם אחו־רנית\") לא היינו יודעים זה.\nג. ויובן זה בהקדים תורתו של הבעש״ט<sup data-n=\"6\">6</sup>, שכאשר אדם רואה רע בזולתו, הרי זו הוכחה ש(דוגמת) אותו הרע נמצא בו בעצמו<sup data-n=\"7\">7</sup>. וכמו אדם המביט בראי — „אם פניו נקיים, אינו רואה במראה שום דופי\"<sup data-n=\"8\">8</sup>, אבל אם הוא רואה לכלוך וכתם בראי, אין זה אלא משום ש„פניו מטונפין\".\nולכאורה: מהו ההכרח שראיית הרע בזולתו הוא בבחינת „דמות\" ו„מראה\" של הרע שבהרואה — למה לא תתכן מציאות כזו שבאמת ישנו הרע הנראה רק בחבירו והוא עצמו מושלל מזה ?\nוהביאור בזה<sup data-n=\"9\">9</sup>: כל מאורע שבעולם הוא בהשגחה פרטית. וכן גם במאורע זה (שהוא רואה רע בזולתו) אין זה במקרה ח״ו, אלא דבר שהזמינו לו מלמעלה ; ומכיוון שלא ברא הקב״ה בעולמו דבר אחד לבטלה<sup data-n=\"10\">10</sup>, הרי א״א",[["1","1","ז, ח."],["2","2","פסחים ג, א. וראה ב״ר כאן."],["3","3","פרשתנו ט, כג."],["4","4","שם, כו־ז (וראה ב״ר פל״ו, ח שגם „ברוך ה' אלקי שם\" היא ברכה)."],["5","5","ולכאור' גם „ופניהם אחורנית\" מיו־תר, מכיוון שנא' לפנ״ז „וילכו אחורנית\" — אבל כבר תירץ רש״י שם (כג) קושיא זו. ע״ש."],["6","6","מאור עינים ר״פ חקת. וראה גם תולדות י״י ס״פ תרומה. ובכ״מ. וראה גם סה״ש קיץ הש״ת ע' 83."],["7","7","ראה עד״ז <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380442\" data-slug=\"likkutei-torah\" data-id=\"4001380442\">לקו״ת בהעלותך לג, סע״א</a>."],["8","8","שלכן „הצדיק הגמור שאין רע בקרבו אין רואה שום רע על שום אדם\" (מאור עינים שם)."],["9","9","ראה גם סה״ש שם."],["10","10","שבת עז, ב."]]],[1300101033,"לומר שמלמעלה יביאוהו לידי ראיית רע במישהו לשוא — אלא שבודאי יש בזה הוראה<sup data-n=\"11\">11</sup> והודעה והיא — שהרע נמצא ברואה עצמו ועליו לתקנו.\nוהטעם למה צ״ל ההוראה באופן מסובב כזה — להיוודע מהרע שלו ע״י אמצעות חברו — ולא באופן ישיר ? — הרי זה משום ש„על כל פשעים תכסה אהבה\"<sup data-n=\"12\">12</sup> (ואהבת עצמו מכ״ש), ו„כל הנגעים אדם רואה חוץ מנגעי עצמו\"<sup data-n=\"13\">13</sup>, ולכן הדרך להביא את האדם לידיעת חסרונות שלו, הוא ע״י שיזמינו לו לראותם בזולתו<sup data-n=\"14\">14</sup>, והזדמנות זו, בעת שהוא „רואה\" (בחבירו) פחיתות החסרונות והרע, מעוררת בו התבוננות במצבו הוא ; וכאשר יתבונן היטב במצבו „אליבא דנפשי'\", יבוא להכרה שהחסרונות שראה הם באמת חסרונות שלו — אשר „כל הנגעים (שה)אדם רואה (ב)חוץ (הרי זה תוצאה) מנגעי עצמו\".\nד. אמנם עדיין יש להקשות : תפ־קידו של איש הישראלי, הוא לא רק לפעול זיכוך ועלי' בעצמו, אלא גם לפעול בחבירו, וכמש״נ הוכח תוכיח את עמיתך ואפילו מאה פעמים<sup data-n=\"15\">15</sup> —\nוא״כ : מי יאמר שהכוונה בזה שמ־למעלה הראוהו את הרע של זולתו הוא בכדי שיראה ויוודע שאותו הרע נמצא בו ואשר עליו לבערו ; הרי יתכן לומר כפשוטו, שהכוונה באמת היא להראותו את ה„רע\" של חבירו — בכדי שהוא, הרואה, יוכיחו ויעזור לו לתקן ולהטיב דרכו ?\nיתירה מזו : כמדובר כמה פעמים<sup data-n=\"16\">16</sup>, בנ״י אינם בבחינת „אמצעי\" שעל ידם תושלם הכוונה העליונה בענין אחר — דהיינו שנאמר שתכלית הכוונה נמצאת בענין שמחוץ להם (כמו כל שאר עני־ני הבריאה, כולל עולמות עליונים<sup data-n=\"17\">17</sup>, שאין הם עצמם תכלית בריאתם, אלא „בשביל ישראל ובשביל התורה\"<sup data-n=\"18\">18</sup> ) — אלא שבני ישראל עצמם הם תכלית הכוונה. וכמו שהוא בנוגע כללות ישראל, כן הוא בנוגע לכל אחד מהם בפרט : לא יתכן לומר ש־יהודי אחד רק „ישמש אמצעי\" ל־יהודי חבירו ; כי תכלית הכוונה הוא גם בכל אחד ואחד במיוחד<sup data-n=\"19\">19</sup>.",[["11","11","וכתורת הבעש״ט, שכל מה שאדם רואה או שומע — הוראה היא בעבודתו („היום יום\" ע' נב)."],["12","12","משלי יו״ד, יב."],["13","13","נגעים פ״ב מ״ה. והכוונה כאן היא — כפירוש המאירי לאבות (פ״א מ״ז — הובא גם במדרש שמואל שם. וכ״ה בד״ה איש על דגלו ש״ת פ״ג. ואהבת תש״ס פס״ו) — בנוגע ל„נגעים\" רוחניים, ש„נגעי עצמו\" אינו רואה אותם ל„נגעים\" וחסרונות כלל."],["14","14","וע״ד המבואר במק״א (ראה לקו״ש ח״ד ע' 1207. וש״נ), שכשרוצים שאדם יפסוק הדין על עצמו, עושים זה בתחבולה — ע״י שפוסק הדין על זולתו."],["15","15","ב״מ לא, א."],["16","16","בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061247\" data-slug=\"likkutei-sichot\" data-id=\"1300061247\">לקו״ש ח״ה ע' 246</a>. ח״ו ע' 236."],["17","17","ועד, שגם בחי' האור „שהוא גילוי העצמות, ולא רק גילוי מן העצם\", הכוונה בגילוי זה היא — בשביל נש״י (ראה ד״ה העושה סוכתו תרצ״ט פ״ב)."],["18","18","נסמן לעיל ע' 12 הערה 33."],["19","19","ראה סנה' לז, א (במשנה): כל אחד ואחד חייב לומר בשבילי נברא העולם. ומה שאמרו (חולין צב, א) „עלין שבה אלו עמי הארץ . . . דאלמלא עליא לא מתקיימין אתכליא\" — הכוונה בזה היא [לא שהתכלית של עמי הארץ היא רק בשביל הת״ח ולא בהם עצמם (בדוגמת אוה״ע, להבדיל, שהם טפלים לישראל), כ״א] שע״י שהם מקיימים את הת״ח, הם מת־עלים ונכללים בבחי' הת״ח (וע״ד המבואר"]]],[1300101034,"ומובן מזה (גם בעבודה הפרטית של כאו״א), אשר אי אפשר גם לומר שזה שמראין מלמעלה את החסרונות של האחד הריהו רק לטובת השני (הרואה) — אם לא שתצמח מזה תו־עלת ל„בעל החסרון\" עצמו<sup data-n=\"20\">20</sup> ; דהיינו ע״י שהראשון יוכיחו וישתדל לתקנו ולבער את הרע שבו.\nומכיוון שכן, שבכל אופן מוכרחים לומר שהתכלית בזה שהרע שבהזולת נראה לו הוא בכדי שיתקנו — מהי־כא תיתי להכריח שזה שרואה את הרע אינו אלא כמביט „בראי\", ש־מראין לו את הרע שלו ב„דמותו\" של חבירו ?\nה. להבין זה צריך להקדים ולהס־ביר ענין בלתי מובן בהמשך מאמר הגמ' המובא לעיל (סעיף א') „לעולם אל יוציא אדם דבר מגונה מפיו . . . שנאמר . . . ומן הבהמה אשר איננה טהורה\" :\nבהמשך למאמר זה נאמר שם עוד כלל דומה : „לעולם יספר אדם בלשון נקי', שהרי בזב קראו מרכב ובאשה קראו מושב\" (שהטעם לשינוי לשון הכתוב באשה זבה ובאיש זב — באשה : „או על הכלי אשר היא יוש־בת עליו\"<sup data-n=\"21\">21</sup>, ולא „רוכבת\" עליו\nכמו באיש : „וכל המרכב אשר ירכב עליו\"<sup data-n=\"22\">22</sup> — „לפי שאין הגון להזכיר רכיבה ופיסוק רגלים באשה\"<sup data-n=\"23\">23</sup> ). ועל כלל זה מקשה שם בגמ' משלשה פסוקים שכתוב בהם לשון „מרכב\" באשה ; ולאחרי התירוץ של הג' באה שם הקושי' : „ובאורייתא מי לא כתיב טמא\".\nואין זה מובן כלל : הלשון „טמא\" כתובה בתורה יותר ממאה פעמים — וא״כ הסברא נותנת שמתחלה הי' צריך להקשות בגמ' מלשון „טמא\", החוזרת ונשנית ריבוי פעמים, ואח״כ מלשון „מרכב באשה\" שאינה מופיעה אלא פעמים אחדות — ולמה באו הקושיות בסדר הפוך ?\nגם צ״ל : מהי כוונת הגמ' ב„מי לא כתיב טמא\", בלשון של תמי' — כאילו שבההודעה שכתוב „טמא\" יש משום חידוש ופתרון ספק אפשרי — ויותר מתאים לומר : „והרי כתיב טמא באורייתא\" (וכיו״ב) ?\nו. הביאור בזה : כשהנידון הוא בלשון הבאה בתור פסק הלכה, אזי צריך ה„פסק\" להיאמר בלשון היותר ברורה — אפילו אם לשון זו היא „דבר מגונה\" — בכדי שההלכה תהי' פסוקה וברורה לגמרי. ועפ״ז יובן מה שברוב המקומות בתורה נאמרה לשון „טמא\" — אעפ״י שהדיבור „בלשון קצרה\" לא גדלה מעלתה (לפי המהר־ש״א) על הדיבור „בלשון נקי' \" — לפי שרק בסיפורי התורה יתכן שענין הטומאה (וכיו״ב) יכתב באופן של „עיקם הכתוב\" (בעיקום ועילום, ולא באופן ישר וגלוי)<sup data-n=\"24\">24</sup> ; ושם (בסיפורי",[["","","ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061010\" data-slug=\"likkutei-sichot\" data-id=\"1300061010\">לקו״ש ח״ו</a> שם בענין העליות ד„ילכו מחיל אל חיל\" שבישראל, שמדריגה התח־תונה היא לא רק הכנה ואמצעי למדריגה העליונה, כ״א, שע״י שהיא מביאה למדריגה העליונה, גם היא עצמה מתעלית בבחי' זו)."],["20","20","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021255\" data-slug=\"likkutei-sichot\" data-id=\"1300021255\">לקו״ש ח״ב (ע' 531</a>) יתירה מזו, שאפילו באדם אחד גופא — מה ש„מותר להתענות לתשובה\" או „כדי למרק נפשו\" לפי „שצער זו טובה היא לו\", זהו לפי שטובה זו היא גם להגוף. אבל באם היתה ה„טובה\" רק עבור הנפש — י״ל שאסור לצער את הגוף בשביל טובת הנפש."],["21","21","מצורע טו, כג."],["22","22","שם, ט."],["23","23","רש״י פסחים שם."],["24","24","ואף שגם הסיפורים שבתורה הור־אות הם — בכ״ז אינו מוכרח שיהי'"]]],[1300101035,"התורה) הרי „לשון ארוך ונקי' \" מצוי הוא לא־פחות מ„לשון קצר ומגונה\", היות כי „לשון קצר ומגונה ולשון ארוך ונקי' שווים הם\".\nמשא״כ באותם (רוב) המקומות ב־תורה, שענינם הוא פסק הלכה, בהכרח שהכתוב ישתמש בלשון „טמא\", (לא משום מעלתה „כלשון קצרה\", אלא) מפני שהלכה צריכה להיאמר באופן של פסק ברור. ועפ״ז יובן מה שס״ל להגמרא (בהסלקא דעתי') שגם „היכא דנפישין מילי\" מדבר הכתוב בלשון נקי' — אעפ״י שהלשון „טמא\" ישנה הרבה פעמים בתורה — לפי, שכאמור, ברוב המקומות תיבת „טמא\" באה בנוגע להלכה. ולכן אי״ז סתירה לה־כלל של „לעולם . . מפיו\" גם לפי הס״ד שהוא כולל גם „היכא דנפישין מילי\".\nובקושית הגמ' „ובאורייתא מי לא כתיב טמא\" המכוון להקשות : והכי איננו מוצאים בתורה את הלשון „טמא\" גם כשאפשר „לעקם\", בסיפורי' ? — הלא נמצאת בהם עכ״פ פעמים אח־דות ! ולכן אין גם לתמוה מה שקושי' זו בגמ' מלשון „טמא\" לא עדיפא להקדימה על הקושיא מלשון „מרכב\", הואיל ובסיפורי התורה ישנה תיבה זו רק במקומות מספר.\nז. כאמור, שאעפ״י שכשצריכים לפסוק הלכה הנוגעת (לאיזה דבר או אפילו) לאיזה איש, חייבים לאומרה באופן ולשון ברור — „טמא הוא\" וכיו״ב — מ״מ כשהמדובר בטומאתו הוא לא בתור פסק הלכה בזה — צריך למנוע מלהוציא מפיו „דבר\nמגונה\", כיון שזהו חלק הסיפורי שב־ההלכה.\nראי' לדבר : הציווי „כי יהי' בך איש אשר לא יהי' טהור וגו' ויצא אל מחוץ למחנה\"<sup data-n=\"25\">25</sup>, הגם שהכתוב בא להודיע דין האיש המדובר, אבל מכיון שהכתוב לא מיירי בדינו לקבוע שהוא טמא, אלא — שעליו לצאת „אל מחוץ למחנה\" (לפי שידוע מכבר שהוא טמא), לכן „עיקם הכתוב\" ובמקום „טמא\" הוא מאריך ואומר „אשר לא יהי' טהור\".\nוע״ד שהוא בשייכות לענין הדיבור (בלשון נקי') כמו״כ — בנוגע לראי' :\nכאשר שומע שאיש מישראל עשה דבר בלתי הגון ח״ו, החובה בזה „לראות\" את „ההלכה למעשה\" שב־הענין ; דהיינו (רק) מה שנוגע לזה שהוא (הרואה) צריך לעשות — לתקן : להוכיח אותו (כמובן, בדרכי נועם ובאופן הרצוי<sup data-n=\"26\">26</sup> ) ולהחזירו למוטב ; עכ״פ זה צ״ל עיקר הראי'. אמנם, אם בעת ששומע מהלא טוב של זולתו הרי הוא „רואה\" לא את ההוראה למעשה המכוונת לו, אלא שהוא „רו־אה\" רעתו של חבירו (עכ״פ — זה מודגש אצלו) — ז. א. שמרגיש (לא הנחיצות מצדו לתקנו, כ״א) איך שיש מציאות רע בזולתו — הז״ז ראי' מוכחת ש„פניו מטונפין\", שהלא טוב שרואה בזולתו הוא „ראי\" של הלא טוב שלו.\nז. א. מכיוון ש„כל מה שברא ה־קב״ה בעולמו לא ברא דבר אחד לבטלה\" (כנ״ל) — שבכל פרט שהוא",[["","","כתוב בפירוש „טמא\", ובמכ״ש מזה ש־כללות ועצם ה„הוראות\" אינן מפורשות בכתוב."],["25","25","תצא כג, יא. וראה פסחים שם."],["26","26","ראה בארוכה ד״ה אם רוח המושל תרצ״ה (קונט' ל'). מכתב כ״ק מו״ח אדמו״ר — נדפס ב„התמים\" ח״ח ע' מו ואילך."]]],[1300101036,"„רואה\" ישנה הוראה מיוחדת לו — הרי מובן שבנדו״ד הוראה כפולה היא לו :\nזה שמראים לו (מלמעלה) שיש (בחבירו) ענין הזקוק לתיקון, הרי זו הוראה שעליו להתעסק עמו בכדי לתקנו ; וזה שמראים לו ענין של „רע\" — זוהי הוראה שהרע נמצא בו והוא צריך לתקן את עצמו. שאם הוא בעצמו הי' במדריגת „צדיק\" (עכ״פ בפרט זה<sup data-n=\"27\">27</sup> ) אזי לא הי' רואה ומדגיש בזה את הרע, כנ״ל.\nח. ובזה יבואר מה שהכתוב מוסיף „וערות אביהם לא ראו\" אף שלכאורה זה מובן מהנאמר קודם „ופניהם אחו־רנית\" :\nהכוונה בזה להדגיש אשר לא זו בלבד שהם (שם ויפת) לא ראו „ערות אביהם\" במובן גשמי (לפי ש„פניהם אחורנית\"), אלא עוד יותר, שלא „ראו\" ולא „הרגישו\" ענין של „ערוה\" וחס־רון אצל אביהם ; הרגשתם התרכזה כולה בזה שהם צריכים לעשות — לכסות „את (ערות) אביהם\". אבל „ערות אביהם — בפני עצמה — לא ראו\".\nובזה גופא יובן למה נשתנו שם ויפת מאחיהם השלישי, חם : הם „לא ראו\", אבל בחם נאמר : „וירא חם\" — והוא מצד השינוי במהותם ומד־רגתם :\n„חם אבי כנען\", מכיון שהרע הי' בו בעצמו (אלא שבו הוא עדיין בד־\nקות)<sup data-n=\"28\">28</sup> — כי „חם\" ענינו חמימות<sup data-n=\"29\">29</sup> שמקו השמאל<sup data-n=\"30\">30</sup> — לכן<sup data-n=\"31\">31</sup> ראה בנח את הלא טוב של „וישת גו' וישכר גו' \"<sup data-n=\"32\">32</sup>, שגם זה הוא ענין של חמי־מות (ואע״ג שהחמימות של חם היא בציור דק יותר<sup data-n=\"28\">28</sup> מחמימות זו שראה והתבטאה ב„וישת וגו' \" — בכ״ז הרגיש בזה מפני שבדקות עכ״פ היתה זאת בו),\nמשא״כ שם ויפת, שהם מקו הימין וקו האמצעי<sup data-n=\"30\">30</sup> — אצלם הרע הזה מושלל הוא, ואינו אפילו בדקות, וד־קות דדקות. וכשבעצמם נקיים לגמרי מרע זה, אז אינם רואים אותו גם בזולת — והם רואים ויודעים רק את העבודה המוטלת עליהם בזה.\nט. וזוהי ההוראה לכ״א מאתנו :\nבעת ששומעים או רואים איזה דבר לא טוב על איש מישראל, הרי לבד זאת שאסור לדבר ולספר מזה לאחרים — ולא כמו שעשה חם : שלא הס־תפק בזה שהוא „ראה\" את הרע, אלא שעוד הודיע את זה לאחרים : „ויגד לשני אחיו בחוץ\"<sup data-n=\"33\">33</sup> — אלא עוד יותר",[["27","27","ומה שכתוב במאור עינים שם (נעתק לעיל הערה 8), שדוקא „הצדיק הגמור שאין רע בקרבו (היינו שאין בו רע כלל) אין רואה כו'\" — היינו שהצדיק הגמור „אין רואה שום רע כו'\"."],["28","28","המבואר בהשיחה, הוא ע״פ פירוש הרד״ק, שכוונת הכתוב ב„אשר עשה לו\" היא רק „שהלך והגיד לאחיו כו'\" (משא״כ לפי פרש״י פסוק כב — מסנה' ע, א)."],["29","29","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370121\" data-slug=\"torah-or\" data-id=\"3901370121\">אוה״ת וישב רנב, א</a>. וראה גם תו״א כו, א."],["30","30","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560257\" data-slug=\"or-hatorah-hb\" data-id=\"8316560257\">זח״א עג, רע״א</a>. וראה גם תו״א כו, ג. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560300\" data-slug=\"or-hatorah-hb\" data-id=\"8316560300\">אוה״ת שם</a>. ובאוה״ת בראשית (ח״ג) תקצה, א שם־טעם זה נמנו בכתוב בהסדר שם חם ויפת — כי „חשיב המדות כסדרן\". ע״ש."],["31","31","ראה רד״ק פסוק כג : „בזה הי' אבי כנען שלא כסה ערות אביו והי' רע אבי רע\". ועפ״מ מ״ש בפנים — ה־שייכות ב„אבי כנען\" היא גם ל„וירא חם\"."],["32","32","פרשתנו ט, כא."],["33","33","שם, כב."]]],[1300101037,"מזה, שאין להרהר אפילו במח' מה־רע של הזולת<sup data-n=\"34\">34</sup>. צריך להתבונן מה לעשות בזה, איך להוכיחו (וכנ״ל באופן הראוי) ולתקנו ; ובה בשעה גם לבקש עצה וכל מיני השתדלות שלא „יראה\" את הרע של חבירו ואפילו בעת ההתעסקות עמו.\nוכשמתנהגים והולכים בדרך זו של שם ויפת אז זוכים להבטחת הברכה : „ברוך ה' אלקי שם ויהי כנען וגו' \" וגם „יפת אלקים ליפת (אבל) וישכון באהלי שם וגו' \" —\nזוכים להיות כלים לתורה<sup data-n=\"35\">35</sup> —\nשהכלי לתורה הוא השלום<sup data-n=\"36\">36</sup> — עד שזוכים להשראת השכינה שהיא „בא־הלי שם\" (בבנין בית השלישי<sup data-n=\"37\">37</sup> ) ע״י אחדות ואהבת ישראל<sup data-n=\"38\">38</sup>, ובקרוב ממש.\n(משיחת ש״פ בראשית, תשכ״ו)",[["34","34","ראה אגה״ק סוסכ״ב, שמחשבת לה״ר חמורה היא גם מהדיבור בזה."],["35","35","ראה תיב״ע כאן : וישרון במדרשא דשם."],["36","36","ראה תנחומא (בובר) יתרו ט ויל־קו״ש משלי רמז תתקלד : אמר הקב״ה התורה כולה שלום ולמי אתננה לאומה שאוהבת שלום."],["37","37","וכפרש״י ב„מדרש חכמים\" (יומא ט, סע״ב ואילך. ב״ר פל״ו, ח) — בנוגע לבית ראשון, והרי בפשטות כ״א (ועוד יותר מזה) גם בנוגע לבית השלישי. וראה רמב״ם הל' מלכים ספ״א שבית הג' יבנה ע״י משיח (שהוא מבית דוד ושלמה — בוני ביהמ״ק הא')."],["38","38","להעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310037\" data-slug=\"tanya\" data-id=\"3401310037\">תניא פרק לב</a>."]]],[1300101038,"א. מדובר כ״פ שדרכו של רש״י בפי׳ עה״ת היא לבאר כל דבר הקשה — ע״ד הפשט — בפירוש הכתובים, ובאם יש קושיא בכתוב ואין רש״י מתרצה, ה״ז גופא הוכחה שהתירוץ מובן ופשוט עד כ״כ שאין רש״י צריך לפרשו (או שהתירוץ מובן ע״פ מש״כ רש״י לפנ״ז).\nוהנה בפרשתנו¹ מסופר שנח ידע לאחר המבול „כי קלו המים מעל הארץ״ ע״י ששלח את היונה מן התיבה, „ותבוא אליו גו׳ והנה עלה זית טרף בפי׳״.\nולכאורה ע״פ פשוטו של מקרא אי״ז מובן:\nמסופר בהכתובים הקודמים² על דבר המבול, ש„נבקעו כל מעינות תהום רבה וארובות השמים נפתחו, ויהי הגשם על הארץ ארבעים יום וארבעים לילה וגו׳ ויגברו המים על הארץ חמשים ומאת יום, (ועל ידי זה) ויגוע כל בשר הרומש על הארץ בעוף ובבהמה ובחי׳ גו׳ וימח את כל היקום אשר על פני האדמה גו׳ וימחו מן הארץ גו׳״, שלאחרי מבול כזה בודאי לא נשאר שום אילן או עשב בציורו — וא״כ מאין לקחה היונה את עלה הזית³ ?\nולא נמצא בפרש״י ביאור בזה.\nב. והנה במדרש⁴ מביא בזה ב׳ דיעות: א) שהביאה העלה מ(שבשושין או מהר המשחה שב)ארץ ישראל, כי בא״י לא ירד המבול, כמ״ש⁵ „ארץ לא מטוהרה היא ולא גושמה ביום זעם״. ב) שנפתחו לה שערי גן עדן והביאה את העלה משם.\nאבל אין לומר ששיטת רש״י (פשוטו של מקרא) היא כא׳ מב׳ דיעות אלו, כי: א) הו״ל לרש״י לפרשם, ב) פירושים אלו אינם ע״ד הפשט:\nהפי׳ שהביאתו מג״ע — הנה אף שגם ע״ד הפשט מובן שלא ירד המבול בג״ע, שהרי סיבת המבול היתה „כי רבה רעת האדם בארץ וכל יצר מחשבות לבו רק רע כל היום״⁶, „ותשחת הארץ לפני האלקים ותמלא הארץ חמס״⁷ — ובג״ע הרי לא שייך כל זאת, מ״מ:\nאיך אפ״ל שנכנסה⁸ היונה לג״ע",[["1","1","ח, יא."],["2","2","ז, יד־כב."],["3","3","מש״ה הרמב״ן: „מפשוטו של פסוק זה יראה שלא נעקרו האילנות ולא נמחו במבול כי לא הי׳ שם נחל שוטף כו׳״ — אי״מ: דהרי נראה במוחש שכשיורד גשם גדול (ובפרט מ׳ יום רצופים) ה״ז עוקר אילנות וכו׳, וכ״ש מבול שויגברו המים ק״נ יום; וביותר — שהאילנות היו מכוסים ונשרים וכבושים במים עמוקים במשך כו״כ חדשים! קושיית הבחי „כיון שנגזר אבדן ומחי׳ על האדם ועל כל מה שבארץ אין צריך לומר שנעקרו האילנות ונמחו לגמרי״, אינה קושיא ע״פ פשש״מ, כי לא מצינו שנגזר אבדן ומחי׳ על כל מה שבארץ, וכמפורש (בראשית ו, ז) „אמחה את האדם גו׳ מאדם עד בהמה עד רמש ועד עוף השמים״; (פרשתנו ו, יג) „קץ כל בשר בא לפני גו׳״ (וכ״ה שם, יז, שם ז, כא־כג), ורק בנוגע להארץ עצמה מצינו כן (פרש״י שם ו, יג). והקושיא היא רק מצד הסברא."],["4","4","ב״ר פל״ג, ו. ויק״ר פל״א, י. שהש״ר פ״א, טו (ד), פ״ד, א (ב). וראה רמב״ן כאן. רבינו בחיי כאן. ועוד."],["5","5","יחזקאל כב, כד."],["6","6","בראשית ו, ה."],["7","7","פרשתנו שם, יא."],["8","8","ובנוגע לג״ע — דוחק גדול — ע״ד הפשט — לומר שנשמט עלה אחד משם"]]],[1300101039,"(והביאה משם עלה זית), והרי מפורש בכתוב⁹ „וישכן מקדם לג״ע את הכרובים ואת להט החרב המתהפכת לשמור גו׳״ הכניסה לג״ע, ואא״פ ליכנס לשם.\nועוד ועיקר: כוונת נח היתה „לראות הקלו המים מעל פני האדמה״¹⁰, ומה ראה עי״ז שהביאה עלה זית מג״ע, הרי שם לא הי׳ המבול מעיקרא¹¹ ?\nמטעם זה אאפ״ל גם כפי׳ הב׳: מה ראי׳ שקלו המים מעל הארץ, עי״ז שהביאה עלה זית מא״י, שלא ירד בה המבול.\nואף שגם לדעה זו — הנה ע״פ טבע — אף¹² שבא״י לא ירד המבול, הרי המים שירדו בהארצות סביבה — בודאי זרמו ונכנסו גם לא״י.\nמ״מ מובן שבמקום שלא היתה ירידת המבול, וגם לא בקיעת מעינות תהום רבה, לא היו מים רבים כ״כ וגם לא תגבורת המים ובמילא לא חדרו המים כ״כ בתוך (עומק) האדמה וכו׳¹³, בודאי ששם קלו המים קודם לשאר המקומות וכו׳, ועפ״ז מעלה הזית שבפי היונה ידע נח כי קלו המים בארץ ישראל, אבל מנין ידע שקלו המים מעל כל הארץ.\nג. נוסף על זה: ע״פ פשש״מ צריך לומר אשר ירד¹⁴ המבול בארץ ישראל״¹⁵ — ובהקדים:",[["","","ונתגלגל לחוץ (כמו שפרש״י במדרש רבה לדעת אלו שהי׳ מא״י)."],["9","9","בראשית ג, כד. ובפשטות היתה השמירה לא רק מאדה״ר, כ״א מכל, וכפשטות — דלהט חרב המתהפכת מאיים ומפחיד את היונה. ועוד ועיקר: כיון שגם הבהמה והחי׳ אכלו מעה״ד (פרש״י בראשית ג, ו) ונקנסה עליהם מיתה, הרי גם עליהם חל הגירוש מג״ע."],["10","10","פרשתנו ח, ח."],["11","11","כמו שהקשה הרמב״ן. ומה שתירץ „ואולי היו שעריו סגורים שלא יכנסו שם המים, וכאשר קלו המים נפתחו״, שכוונתו, לכאורה, היא שלא מזה „עלה זית טרף בפי׳״ ידע נח שקלו המים, כ״א שזה הי׳ סימן שנפתחו השערים של ג״ע (דאל״כ מאיפוא לקחה העלה), ומכיון שבודאי היו השערים סגורים במשך כל זמן המבול, הבין נח שקלו המים — הנה לא משמע כן מלשון הכתוב „והנה עלה זית טרף בפי׳״ (ומזה) וידע נח כי קלו המים מעל הארץ״."],["12","12","כמפורש בפדרא״א פכ״ב. רמב״ן כאן. טור הארוך כאן. ועוד. ועד״ז מבואר בזבחים (קיג, ב) בנוגע לההבל של המבול (לדעת הגמ׳ שהמים היו רותחים — אבל ראה לקמן סעיף ו׳)."],["13","13","ע״ד מה שכתבו הרמב״ן ורבינו בחיי (בביאור איך נשאר עלה זית טרף אף בא״י — והרי גם שם נכנסו המים): „מפני שלא ירד בארץ ההיא הגשם השוטף ולא נפתחו עלי׳ ארובות השמים נשארו בה האילנות ובכל העולם נשברו ונעקרו במבול ומטרות עזו״. [אבל ראה אברבנאל כאן: „אין ספק שברוב המימות שנתגלגלו עלי׳ משאר ארצות היו נעקרים ונשברים האילנות״. (ואעפ״כ מתאים מ״ש האברבנאל עם המבואר בפנים, כי אף שלדעתו נעקרו האילנות וכו׳ ע״י שטף גלגול המים, מ״מ אי״ז שייך לזה שקלו שם המים לפני שאר המקומות, כי אעפ״כ לא חדרו כ״כ בעומק האדמה וכו׳, כבפנים)]."],["14","14","כדעת ר״ל בזבחים (קיג, א). וכדעת ר׳ יונתן בב״ר פל״ב, י. דב״ר פ״ג, ו, שהש״ר פ״ד, ד (ב). וראה מפרשים שם."],["15","15","ומוכרח לומר כן גם מהא דפרש״י (ח, ב) „לפי שנשתיירו מהם אותן שיש בהם צורך לעולם כגון חמי טבריא וכיוצא בהם״ — והרי טבריא היא בא״י (ומובן שאין לומר ש„חמי טבריא״ (כאן ?) הוא שם למעינות חמים באיזה מקום שיהיו — שהרי מסים וכיו״ב). ומ״ש במשכיל לדוד „דשפיר מתוקם אפי׳ למ״ד לא ירד (בא״י) כו׳ חמימות והבלא דמבול התם נמי הוה כו׳״, אי״מ: א) אף שנכנסו שם המים וההבל של שאר הארצות, הרי פשוט שזה לא שינה המעין שבטבריא שמאז ואילך יהי׳ תמיד — מים חמים. ולמה דוקא המעין שבטבריא נשתנה ולא שאר מעינות א״י. ב) ראה לקמן סעי׳ ו׳ ובהערה 42"]]],[1300101040,"במדרש¹⁶ מביא ב׳ דעות בפי׳ הכתוב¹⁷ „חמש עשרה אמה מלמעלה גברו המים ויכסו ההרים״: „ר׳ יהודה אומר חמש עשרה אמה בהר וחמש עשרה אמה בבקעה. ר׳ נחמי׳ אומר ט״ו אמה בהר, אבל בבקעה כל שהן („לפי עומק הבקעה הן רב הן מעט״¹⁸)״.\nרש״י בפירושו עה״פ מפרש: „חמש עשרה אמה מלמעלה — למעלה של כל גובה ההרים לאחר שהשוו המים לראשי ההרים״, כדעת ר׳ נחמי׳¹⁹. והטעם ע״ז:\nא) כשאין הכרח לומר שעשה הקב״ה נס — ה״ז היפך פשטות הכתובים לומר שהי׳ נס והעלימו הכתוב! ובנדו״ד, לדעת ר״י הי׳ כאן נס גדול (שלא ירדו המים מגבוה לנמוך (מהר לבקעה), ובמשך זמן רב — היפך הטבע לגמרי²⁰). ונוסף ע״ז — ה״ז נס שלא לצורך לכאורה.\nב) פשטות לשון הכתוב „חמש עשרה אמה מלמעלה״ משמע „למעלה דגובה כל ההרים״.\nג) מצד תוכן הענין: לדעת ר״נ מובן למה נחה התיבה על הרי אררט דוקא (אף שעי״ז נתוספה טירחא יתירה לנח — ירידה מן ההר וכו׳); מכיון שהיו מההרים הכי גבוהים, הרי כשהתחילו המים לחסור, נחסרו לראשונה במקום הכי גבוה, ושם הי׳ המקום הראשון שהי׳ אפשר להתיבה לנוח,\nולכן ותנח התיבה על הרי אררט. אבל אם בכל מקום הי׳ גובה המים בשוה — ט״ו אמה מלמעלה — ונחסרו המים ששים יום²¹, היינו בכ״מ בשוה — למה נחה התיבה דוקא בהרי אררט? לכן פירש״י כדעת ר׳ נחמי׳.\nלפ״ז, אם נאמר שבא״י לא ירד המבול — גם אם זרמו ובאו לשם המים מהארצות סביבה — בפשטות קלו שם המים לפני שאר הארצות, כנ״ל, וא״כ למה נחה התיבה בהרי אררט דוקא, ולא לפני זה — בא״י.\nועכצ״ל שע״ד הפשט גם בא״י ירד²² המבול²³.\nד. ויובן בהקדים עוד דברים בלתי מובנים בפי׳ הפשוט של כתוב זה:\nא) מבואר בכתוב שע״י שהביאה את העלה זית ידע נח שקלו המים מעל הארץ, שהכוונה בזה שידע לא רק שהמים — היו הלוך וחסור, כי זה התחיל זמן הרבה לפנ״ז (ובודאי ידע נח עד״ז — שהרי נחה התיבה וכו׳), וכמפורש בכתוב שיבשו המים מעל הארץ — קודם שילוח היונה,\nכ״א גם — קלות המים עד כ״כ שכבר יש מקום שכעבור זמן קצר יהי׳ מנוח, לנוח על הארץ²⁴, ולכאורה",[["","","שלפרש״י לא היו מי המבול רותחים, וחמי טבריא היו מים חמים בעצם. עיי״ש."],["16","16","ב״ר פל״ב, יא."],["17","17","פרשתנו ז, כ."],["18","18","מ״כ שם."],["19","19","וכ״ה ביומא עו, א."],["20","20","להעיר שבקרי״ס הי׳ צ״ל לכיו״ב רוח קדים עזה כל הלילה (בשלח יד, כא. וראה שער היחוה״א פ״ב) ועד״ז בירדן בימי יהושע (יהושע ה, כג)."],["21","21","נח ח, ב־ה. ובפרש״י פסוק ד שם."],["22","22","וגם: ע״פ הנ״ל ש(גם) ע״ד הפשט במקום שאין הכרח לומר שהי׳ נס אין אומרים כן, עוד ראי׳ שירד המבול בא״י, כי לזה הרי צ״ל נס מיוחד."],["23","23","ויומתק עפ״ז הטעם שבפירושו עה״פ ביחזקאל פרש״י „לא אתעבידו בה עובדין טבין כו׳״, ולא — שלא ירד שם המבול."],["24","24","כרש״י ששלת את היונה כו׳ „שאם תמצא מנוח לא תשוב אליו״ (ח, ח). וכמובן גם מזה „שחרבו המים מעל הארץ״ — „שקרמו פני׳ של מעלה״ (ח, יג, ובפרש״י) לאחר ז׳ ימים."]]],[1300101041,"מהי ההוכחה על זה ע״י עלה של זית, והרי אפשר שעלה זה לוקח מאילן שעל הר גבוה (ובפרט שהתיבה היתה בהר גבוה) ומראש האילן, ובגובה זה כבר לא היו מים זמן רב — לפני הזמן דוידע נח גו׳.\nב) למה הביאה עלה של זית דוקא, ולא של אילן אחר ? ובפרט שמדייק הכתוב לומר (לא „עלה״ סתם, אלא) „עלה זית״²⁵ — מה נפק״מ איזה²⁶ עלה הביאה²⁷ ?\nוהביאור בזה:\nבכ״מ בדברי חז״ל²⁸ מבואר שהזית הוא אילן חזק ביותר. וגם ע״ד הפשט כן הוא, כי בדבר שבמציאות אין לחלק בין הלכה להפשט²⁹. וכשהתלמיד (בן חמש למקרא) יראה זית — תיכף יבחין שחזק הוא. ולכן מקום לומר ע״ד הפשט, דאף שהי׳ מבול חזק וכו׳, מ״מ מכל אילני זית³⁰ שבעולם, נשארו עכ״פ אחדים מהם³¹.\nאמנם, לאידך גיסא, אין מסתבר כלל — שהעלים של האילן אף שגם הם חזקים³², נשארו במציאות וציור דעלה זית לאחר כל משך זמן המבול ושהי׳ באופן דויגברו המים, והעלים היו מכוסים (ושרויים) במים כו״כ חדשים רצופים!\nומוכרח לומר שהעלה זית שהביאה היונה הי׳ עלה³³ חדש³³* שצמח — לאחר המבול וכעבור זמן מספיק —",[["25","25","בלבוש האורה כתב (וראה פי׳ ריב״א, רע״ב, ועוד) — ומתורץ עפ״ז ב׳ הקושיות — „כי מפני שהזית אינו מן אילנות הגבוהים רק מן (ה)נמוכים בו ידע נח שקלו המים מן הארץ שאם היתה מביאה לו עלה מאילן אחר עדיין לא הי׳ יודע אם קלו המים דשמא הוא מאילן גבוה שגבהו יותר מחמש עשרה אמה ועומד על הר גבוה ולא כסהו המים מעולם כו׳״ — אבל א״מ: הרי הספק הי׳ אם יש מקום מנוח על הארץ — והעלה אפשר שנטרף מראש אילן שבהרי אררט, כבפנים."],["26","26","כמו שהקשה ברמב״ן, רבינו בחיי ועוד. אמנם הם פירשו שמטעם זה אמרז״ל „אמרה יונה כו׳״, אבל אין כן דעת רש״י, בהערה שלאח״ז."],["27","27","ואף שפרש״י ש„אמרה יהיו מזונותי מרורין כזית וכו׳״: א) הביא זה כפי׳ שני. ב) מקדים שזהו מדרש אגדה (לא פשש״מ). ג) באם כוונת רש״י „זית״ שבכתוב הו״ל להעתיק גם תיבה זו מהכתוב — שמזה מובן שכוונתו לפרש דיוק הכתוב „בפי׳״ (שהועתק בפרש״י), ולא „ותבוא אליו גו׳ ותביא עלה זית טרף וידע גו׳״."],["28","28","תוספתא ב״מ פ״ב, ח. ובמקומות שנסמנו בצפע״נ עה״ת."],["29","29","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300121021\" data-slug=\"likkutei-sichot\" data-id=\"1300121021\">לקו״ש חי״ב ע׳ 21</a> הערה 6."],["30","30","ואולי י״ל בדוחק שזוהי גם כוונת הרמב״ן במ״ש „שלא נעקרו האילנות״ — קצת אילנות של זית — אבל לא משמע כן מלשונו."],["31","31","ועפ״ז מובן מ״ש רש״י עה״פ (ט, כ) „הכניס עמו זמורות ויחורי תאנים״, ואינו מזכיר זתים (אף שג״ז בכלל „כרם״ — ולהעיר מב״מ ס״ח, ב. ואכ״מ) — כי ידע שבודאי ישארו כמה אילני זית (וראה מפרשים שם)."],["32","32","עיין בצפע״נ שם."],["33","33","אבל אין לומר בפשש״מ כמ״ש האברבנאל (וכותב ע״ז: הנראה לי מדרך הפשט) „שמעת שנראו ראשי ההרים נמצאו שמה ענפי זית הרבה שהיו צפים ע״פ המים וכשיבשו ראשי ההרים בהיות שם הארץ לחה ורעננה מאותם הענפים שנכנעו בבטן האדמה בארבעים או בחמישים יום שורשו וצמחו ויצץ ציץ ומשם לקחה היונה העלה זית שהביאה בפי׳״ — כי אין מסתבר שאילן חדש יגדל מענף שהשריש כו׳ ויצמיח עלים במשך זמן קצר כזה. וגם: עפ״ז למה הביאה (ומה נוגע לידע שהביאה) עלה של זית דוקא. והרי זה הי׳ אפ״ל בכל העלים. 33*) ראה ריב״א כאן ולקמן הערה 36."]]],[1300101042,"מהזמן שהאילן זית לא הי׳ מכוסה עוד במים והתחיל להצמיח עד שצמח העלה שהביאה היונה.\nומובן שידע נח עי״ז שקלו המים מעל הארץ.\nומובן ג״כ דיוק הכתוב „עלה זית״ — כי זה³⁴ מתרץ מנין לקחה היונה את העלה: מאחר שאילן הזית חזק הוא ביותר, לכן נשאר קיים, בהקדם התחיל להצמיח וכו׳.\nומתורץ עפ״ז ג״כ הא דיש להקשות: איך ידע נח ע״י עלה זית שקלו המים, והרי אפשר שמצאתו ע״פ המים³⁵ — ועפ״פ הנ״ל שהי׳ עלה שצמח אחר המבול, הרי פשוט שהיכר גדול יש בין עלה ששרוי וכבוש במים קרוב לשנה, לעלה שצמח מחדש.\nה. ולהמתיק הנ״ל (שגם בן חמש כשיראה עלה זית — יבחין שחזק הוא)\nהרי דרך רש״י בפירושו עה״ת לבאר כל דבר בפירושו וכו׳ וגם בנדו״ד הו״ל לפרש שאילן זית חזק הוא וכו׳ ככל הנ״ל ?\nוי״ל שלפרש״י מפורש הוא בכתוב:\n„(והנה עלה זית) טרף בפי׳״ (פי׳ רש״י) „טרף — חטף״.\nאין רש״י מפרש תיבת „טרף״ באופן אחר — לפי שפי׳ זה מתאים יותר ע״ד הפשט³⁶ —\nהיינו שהכתוב מדגיש שחטפה העלה (מן האילן³⁷), דלכאורה הול״ל „והנה עלה זית בפי׳״ ?",[["34","34","עפ״ז (שאין מוכרח לומר שהביאה העלה מא״י) עוד הוכחה שירד המבול בא״י, כי אל״כ „האיך ידע נח בהבאת העלה שקלו המים הי׳ לו לספק שמא מארץ ישראל הביאתו״ (חזקוני כאן)."],["35","35","ראה רבותינו בעה״ת, פי׳ ריב״א, רע״ב, חזקוני ועוד."],["36","36","וכמ״ש הרא״ם: „לא מלשון הריגה״ (כבמד״ר שכהערה 4). בס׳ הזכרון (להר״א בקראט הלוי): „משום דלא שייך בעשבים ובאילנות לשון טרפה אלא בבע״ח״. ומ״ש בתרגום אונקלוס ע״פ „ובשר בשדה טרפה״ (משפטים כב, ל) — „ובשר תליש מן חיוא״ (וראה טור הארוך כאן בפירושו הב׳) — הרי רש״י לא פי׳ כן שם. ומובן למה אאל״ם בפשוטו שהוא מלשון מזון (כ״א כהדגשת רש״י שזהו „מדרש אגדה״), כי (בפשטות) מובן מעצמו שהעלה הוא מזון וא״צ להוסיף „טרף״ (משא״כ לפי׳ המ״א, שהכפלת הענין אומרת דרשני: אמרה כו׳). ברבותינו בעה״ת כתבו שפירושו סמדר, והוא מלשון הכתוב (יחזקאל יז, ט) „כל טרפי צמחה יבש״ (וראה גם מלבי״ם כאן ושם שטרף הם העלים הלחים), ומזה ידע נח שנטלתה מאילן — אבל א״א לרש״י לפרש כן, כי רש״י פי׳ ביחזקאל שם: „טרפי — עלי״ (סתם), וא״כ ה״ז כפל לשון [וראה רא״ע כאן: „י״א שהיא מלה מוכפלת בטעם כו׳״, וראה בטור הארוך בפי׳ הד׳: „וי״מ כמו כל טרפי צמחה שהם העלים והם כפל מלה״]. בריב״א עה״פ פי׳ (בפי׳ הב׳) ש„טרף״ פי׳ „חדש״ בערבי, ולכך ידע נח שלקחתו מאילן — אבל מובן שאי״ז ע״פ פשש״מ. וכ״ה בנוגע להפי׳ בצפע״נ ש„טרף״ פי׳ „רבוע״ (עיי״ש). וצ״ע אם מ״ש התרגום אונקלוס כאן „תבירי״ מתאים עם פרש״י „חטוף״ (וראה טור הארוך כאן בפי׳ הג׳). וראה תורה שלימה כאן."],["37","37","הריב״א (בפי׳ הא׳), הרע״ב, החזקוני ועוד כתבו שהפי׳ הוא שהעלה עצמו הי׳ קרוע וחטוף. וכוונת הכתוב בזה לתרץ הקושיא שבפנים — איך ידע נח שקלו המים והרי אפשר שלקחתו מע״פ המים — שמכיון שהי׳ קרוע ידע נח שלקחתו מאילן, כי אם הי׳ ע״פ המים הי׳ שלם, אבל אי״ז מובן: וכי אי אפשר שיהי׳ ע״פ המים עלה קרוע, ומהו ההכרח שזהו מאילן. ולאידך גיסא: בלאה״כ אפשר להכירו, כי"]]],[1300101043,"והביאור: א) העלה נלקח ממקום גידולו (לא שהי׳ צף ע״פ המים וכיו״ב), ב) לקיחת עלה זית מהאילן שלו נקראת „חטף״, כי היא ע״י חטיפה דוקא — בחוזק — כי אילן חזק הוא.\nוא״ו. ע״פ הנ״ל יומתק עוד ענין בפרש״י:\nעה״פ³⁸ „וישכו המים״ פרש״י „כמו כשוך חמת המלך³⁹ ל׳ הנחת חימה״, ופירשו המפרשים⁴⁰ שמקורו של רש״י הוא מהמבואר בזבחים⁴¹ „ברותחין קלקלו וברותחין נדונו דכתיב הכא וישוכו המים וכתיב התם וחמת המלך שככה״. אבל אם כוונת רש״י כהנ״ל, אי״מ השינויים: א) בגמ׳ מפרש שהמים היו רותחין, משא״כ רש״י משמיט דבר שעפ״ז הוא העיקר, שנדונו ברותחין. והרי אדרבא — אם הש״ס צריך לפרש כוונתו בפי׳ תיבת „וישוכו״, כ״ש שרש״י הו״ל לפרש. ב) רש״י מוסיף „ל׳ הנחת חימה״.\nומזה מובן שכוונת רש״י אינה שהמים היו רותחין, כ״א ש„וישוכו וגו׳״ הפי׳ „לשון הנחת (ושקיטת) חימה״ (ולא רתיחה), היינו הנחת ה„ויגברו (המים)״⁴², ולשיטת רש״י בפשש״מ לא היו המים רותחין⁴³.\nוי״ל טעמו דרש״י בזה: א) אין הכרח בפשש״מ להוסיף נס שהיו מים רותחים. ב) על פי פשוטו של מקרא: איך נתקיימה התיבה⁴⁴ במים רותחין⁴⁵.\nז. מ„יינה של תורה״ שבענין הנ״ל:",[["","","אינו דומה עלה שנכבש במים קרוב לשנה לעלה חדש, וכדלעיל בפנים."],["38","38","פרשתנו ח, א."],["39","39","אסתר ב, א."],["40","40","וראה מפרשים עה״פ ו, יד."],["41","41","קיג, ב."],["42","42","בגו״א (ח, א) כתב שכוונת רש״י ש„וישוכו״ קאי על הקב״ה, אבל בפשטות קאי על המים כמפורש בכתוב „וישוכו המים״, וכמו שפי׳ הוא עצמו ו, יד."],["43","43","ואולי י״ל מכיון שאין רש״י מפרש דעתו בזה בפירוש, ישנו מקום לומר גם להיפך — כב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051051\" data-slug=\"likkutei-sichot\" data-id=\"1300051051\">לקו״ש ח״ה ע׳ 51</a> הערה 32 [וכדרכו של רש״י בפירושו עה״ת להביא בכו״כ מקומות ב׳ פירושים ושיטות ויותר, וגם סותרים זל״ז וכו׳]. ולהעיר מפרש״י (ו, יד) שכותב רק „חוזק המים״ ולא „רותחים״. ועד״ז (ז, יב)."],["44","44","וכמו שהקשה בזבחים (שם) „תיבה היכא סגיא״, וכן מוכח הוא ממה שפרש״י עה״פ (לך יד, יג) „ויבא הפליט״ — „ומדרש ב״ר זה עוג שפלט מדור המבול כו׳״, ואם המים היו רותחין איך פלט, וכמו שהקשה בגמ׳ (שם) „ועוד עוג מלך הבשן היכא קאי״. ומה שתירץ בגמ׳ „אלא נס נעשה להם שנצטננו בצידי התיבה״ — אין רמז ע״ז בכתוב. אבל בתיב״ע (לך שם) מפרש שישב עוג על התיבה וכיסוי על ראשו."],["45","45","לכאורה יש להכריח כן גם ממה שפרש״י (ז, כב) „ולא דגים שבים״, אבל ראה רמב״ן (שם, כג), ועוד. ומ״ש רש״י (ח, ב) „שנשתיירו מהם אותן שיש בהם צורך לעולם כגון חמי טבריא וכיוצא בהם״ — י״ל שאין הכוונה שתחמימותן באה מחמת המבול, כ״א כפשש״מ — שהחידוש במעינות הי׳ רק זה ש„נבקעו״ (וגם כשהיו המים מתחת לארץ היו חמים מעיקרא), ומכיון שנפתחו המעינות בעת המבול, נשארו פתוחים מפני הצורך בהם לעולם *. ואדרבא: מפרש״י זה ראי׳ להמבואר בפנים (שלא היו רותחים), כי אם כל המים היו רותחים הרי אין החידוש רק בזה ש„אותן שיש בהם צורך לעולם״ נשתיירו, כ״א שכיון שישנו צורך לעולם במעינות רותחים, לכן נשארו (כמה מהמעינות שנפתחו בעת המבול) רותחים. וצ״ע מפרש״י (ו, יד): „ע״ש גפרית שנגזרו עליהם להמחות בו״ (וראה פרש״י וירא יט, כד). *) אבל צע״ק מנ״ל בפשש״מ שחמי טבריא לא היו פתוחים לפני המבול."]]],[1300101044,"נתבאר בתו״א⁴⁶ בטעם למה נקרא המבול בנביא⁴⁷ „מי נח״ [אף שענינו של נח הי׳ הצלה מן המבול והפכו] — לפי „שהוא בחי׳ מים בכדי לטהר את הטמאים שהוא כדוגמת המקוה מ׳ סאה שהיא מטהרת את הטמא, כמו״כ הי׳ המבול בא בכדי לטהר את הארץ כו׳ ולזאת נקראים מי נח שנעשה מזה נייחא דרוחא כו׳״. וגם ענינו של נח הי׳ להקים את העולם מחדש באופן טוב וטהור וכו׳, שזהו בדוגמת המבול — טהרת העולם.\nוע״פ הכלל שכל ירידה היא צורך עלי׳ יתרה, מובן שלא רק שנטהר העולם מטומאתו הקודמת ע״י המבול, וחזר לדרגתו הקודמת, כ״א שנתוספה טהרה יתירה ע״י המבול⁴⁸. וגם זה — מצינו דוגמתו בטהרה במקוה, ש־\nלפעמים אין זה רק טהרה מהטומאה, כ״א יש בזה גם ענין של תוס׳ קדושה וטהרה⁴⁹.\nעפ״ז מובן יתרון המעלה בזה שאומרים ש(ע״פ פשש״מ) ירד המבול גם בארץ ישראל, כי ע״י שירד שם המבול נמשכה תוס׳ קדושה וטהרה גם לא״י⁵⁰ (בערך דרגתה הקודמת).\n(משיחת ש״פ נח תשל״ד)",[["46","46","פרשתנו ה, ג ואילך. וב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560315\" data-slug=\"or-hatorah-hb\" data-id=\"8316560315\">אוה״ת שם (כרך ג׳ ע׳ תרכד</a> ואילך)."],["47","47","ישעי׳ נד, ט."],["48","48","עיי״ש בתו״א ואוה״ת."],["49","49","ראה של״ה שער האותיות (קד, ב) בשם הזהר. ובכ״מ. וראה שיחת ליל שש״פ תש״ג. ולהעיר משו״ע אדה״ז סי׳ תר״ו סעי׳ יב. ולהעיר מטבילות כה״ג ביוהכ״פ."],["50","50","אבל מובן שענין הטהרה מטומאה לא הי׳ נצרך שם, כי פשוט שגם למ״ד שלא ירד המבול בא״י לא נשארה א״י בסומאה, כ״א שמעיקרא לא נטמאה, וכיו״ב. — וראה פרש״י תולדות (כו, ב): אין חו״ל כדאי לך. ודוחק גדול לומר שזה נעשה ע״י ברית בין הבתרים."]]],[1300101045,"<h3>לך לך*</h3>\nא. מן הכתוב בפרשתנו¹ „ואב־ רכה מברכיך” למד ר״ע במס׳ חולין², שכאשר הכהנים מברכים את ישראל, מברך הקב״ה את הכהנים. והכי איתא התם: „כה תברכו את בנ״י³, ר׳ יש־ מעאל אומר למדנו ברכה לישראל מפי כהנים, לכהנים עצמן לא למדנו, כשהוא אומר⁴ ואני אברכם הוי אומר כהנים מברכין לישראל והקב״ה מברך לכ־ הנים⁵. ר״ע אומר למדנו ברכה ליש־ ראל מפי כהנים, מפי גבורה לא למדנו, כשהוא אומר ואני אברכם הוי אומר כהנים מברכין לישראל והקב״ה מס־ כים על ידם. אלא ר״ע ברכה לכהנים מנ״ל? אמר ר״נ בר יצחק מואברכה מברכיך” ואמר שם „ישמעאל כהנא מסייע כהני” (פרש״י: תמיד הוא עוזרן ומקיל להם). ומסיים: „ומאי מסייע כהני דמוקי לה לברכת כהנים במקום ברכה דישראל”, היינו כפ־ רש״י: „אצל ברכת ישראל, דהכי עדיפא דמשמע שמתברכין הן עם ה־ שאר”.\nוצריך להבין:\nא) מהו יסוד וטעם פלוגתת ר״י ור״ע, מה שלר״ע נצרך פסוק מיוחד שהקב״ה מסכים להברכות שמברכים הכהנים את בנ״י, ולר״י א״צ לזה פ׳ מיוחד⁶ (— עד שעיקר פלוגתתם מאיזה פסוק למדים הברכה לכהנים עצמם, תלוי׳ בזה)?\nב) כוונת רש״י (בדעת ר״י) ש„מת־ ברכין הן (הכהנים) עם השאר (בנ״י)” בפשטות היא — שמקבלים ברכתם יחד עם בנ״י, ולכאורה: החילוק בין דעת ר״ע ור״י הוא רק מאיזה פסוק נלמד שהכהנים מתברכים (אם מפסוק הנאמר בתורה אצל ברכתם לישראל, או ממק״א), אבל לדעת שניהם זה שהכהנים מתברכים מהקב״ה — ה״ז מסובב מזה שהם מברכים את ישראל, וא״כ מהי הכוונה במ״ש „דמשמע ש־ מתברכין הן עם השאר”, היינו ש־ מתברכים ביחד עם בנ״י⁷?\nב. והנה החילוק אם הברכה לכה־ נים אמורה בפסוק „ואברכה מברכיך” או בפסוק „ואני אברכם” מבואר בח־ סידות⁸, בהקדם ההבדל שבין ברכה",[["","","*) וסיום מס׳ ר״ה."],["1","1","יב, ב."],["2","2","מס, א."],["3","3","נשא ו, כג."],["4","4","שם, כז."],["5","5","וראה זח״ג קמז, ב. וראה לקוטי לוי יצחק שם."],["6","6","ואף שכתבו התוס׳ (חולין שם — ד״ה והקב״ה): „ולר״י לא איצטריך קרא להכי דפשיטא דמסכים כיון שצוה להם לברך” — הרי זה גופא צריך ביאור: למה לר״ע אין זה פשיטא כיון שציוה לברך?! וכמו שהקשה בפי׳ הרי״ף על עין יעקב בחולין שם."],["7","7","ובפרט שענין זה נוגע גם להלכה, כמ״ש הצ״צ (בפס״ד ע׳ שמה, ד) בביאור מ״ש אדה״ז (שו״ע סי׳ קכח ס״א) „שגם הם (הכהנים) בכלל הברכה שנאמר ואני אברכם כלומר לכהנים” — ד„בשלמא לר״י כהנים הם בכלל ברכה זו ממש דב״כ, וכדפרש״י פא״ט שמתברכים עם השאר, וע״כ הם מן המנין, אבל לר״ע דנפקא לי׳ מואברכה מברכיך אבל לא מב״כ, א״כ י״ל דאינם מן המנין”."],["8","8","ד״ה אריב״ל תרכ״ט."]]],[1300101046,"(שמברכים את פ׳) לתפלה (שמתפל־ לים עבורו)⁹:\n„ברכה” היא מל׳ „בריכה” — ש־ היא בור עמוק בו קיבוץ מים או יין, ומשם ממשיכים המים או היין — דהיינו שהוא מקור המים והיין כו׳; וכן „ברכה” מל׳ „המבריך”¹⁰ שפי־ רושו המשכה — דהיינו שענין הברכה הוא להמשיך את הדבר ממקורו, שכ״ז ה״ה בסדר ההשתלשלות. ז. א. שה־ ברכה מועלת רק כאשר הדבר ישנו כבר במקורו, ומאיזו סיבה נתעכבה ההמשכה, מועלת הברכה להמשיכו למ־ טה.\nראי׳ לזה מיעקב בברכתו לבני יוסף אשר¹¹ שת ימינו על ראש אפ־ רים ואת שמאלו על ראש מנשה, ואמר לו יוסף „כי זה הבכור שים ימינך על ראשו, וימאן אביו ויאמר . . אחיו הקטן יגדל ממנו וזרעו יהי׳ מלא הגוים”. ולכאורה אי״מ: כיון שיעקב ברך אותם, הרי לכאורה יכול לברך את מנשה ברכה זו עצמה שזרעו יגדל מאפרים (כי מנשה הבכור)?\nאך הענין הוא, כי הברכה אינה מחדשת דבר מעיקרו, כ״א (להבריך) להמשיך דבר הברכה ממקורו בלבד, לכן לא הי׳ יכול יעקב לפעול בבר־ כתו שיהי׳ מנשה גדול מאפרים, מכיון שלא כך הוא בהמקור¹².\nמשא״כ תפלה ענינה הוא בקשה מהקב״ה, ש„יהי רצון” (וכיו״ב), שיהי׳ רצון חדש — כולל גם דבר חדש שלא הי׳ בהמקור, ולכן מועלת ה־ תפלה שגם אם היתה גזירה על דבר לא טוב ח״ו, יהפוך הקב״ה אותה לטוב. כי ע״י תפלה מגיעים לבחי׳ שלמעלה מסדר השתלשלות.\nאמנם הגבלה זו (שברכה מועלת רק אם ישנו הדבר בשרשו ומקורו) שייכת רק בברכתו של בו״ד, משא״כ בברכתו של הקב״ה — שאינו קשור כלל ח״ו במדידות והגבלות — יש בברכתו גם המעלה שבתפלה, ואף היא בכחה להביא ענין חדש — שלא הי׳ בשרשו ומקורו של המתברך.\nוכמו שהוא בברכת הקב״ה, כ״ה גם בברכת כהנים: שהרי ברכת כהנים היא מצוה, היינו שהכהנים המברכים עושים זאת בשליחותו של הקב״ה, ושלוחו של אדם [העליון¹³] כמותו, וברכתם ה״ה ברכתו של המשלח, בר־ כתו של הקב״ה¹⁴.\nוכדמוכח ממה שארז״ל¹⁵ גבי ברכת כהנים „ישא ה׳ פניו אליך” — „וכי לא אשא פנים לישראל וכו׳ והם מדק־ דקים ע״ע וכו׳”, שמובן מזה אשר ברכת כהנים אינה כשאר הברכות",[["9","9","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380792\" data-slug=\"likkutei-torah\" data-id=\"4001380792\">לקו״ת ראה יט, א</a>. אוה״ת ויחי (בראשית כרך ו) תתשכה, ב. אוה״ת שמיני ע׳ כו. כט. אוה״ת נשא ע׳ ער, א ואילך. ד״ה כה תברכו תרכ״ו, תרנ״ד. פדה בשלום תרע״ה ועוד. וראה לקו״ש ח״ה ע׳ 422 (426) ואילך."],["10","10","כלאים רפ״ז. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370171\" data-slug=\"torah-or\" data-id=\"3901370171\">תו״א מקץ לז, ג</a>."],["11","11","ויחי מח, יד ואילך."],["12","12","ואין להקשות למה לא התפלל עבורו — שהרי נדו״ד הוא זמן (וענין) דברכה (ולא דתפלה) כמפורש בקרא כמה פעמים."],["13","13","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380080\" data-slug=\"likkutei-torah\" data-id=\"4001380080\">לקו״ת ויקרא א, ג</a>."],["14","14","ובד״ה אריב״ל הנ״ל מדייק בהל׳ „אמור להם” ומציין ל<a class=\"ft-cite\" href=\"#/read/torah-or/3901370300\" data-slug=\"torah-or\" data-id=\"3901370300\">תו״א</a> ד״ה בחודש השלישי, ושם (סז, א): „לאמר כו׳ להיות ההלכה היוצאת מפיהם דבר ה׳ ממש שנאמרה למשה מסיני”."],["15","15","ברכות כ, ב."]]],[1300101047,"הממשיכות רק מה שישנו כבר (בה־ מקור) בסדר השתל׳, כ״א המשכה למע׳ מסדר השתל׳. שלכן צורך ב־ „משוא פנים” (בברכת כהנים), [בל׳ הגבלה היפך מדת הדין (משוא פנים בדין)], כי „משוא פנים” מורה שאי״ז השפעה הנפעלת על ידי עבודת האדם מצ״ע. ומובן מזה שב״כ היא המשכה למעלה מסדר השתלשלות, שזהו ענין „משוא פנים”.\nוהיינו שבענין זה שוה ב״כ לתפלה¹⁶, שהיא המשכה למעלה מסדר השתל׳.\nג. ועפ״ז מובנת המעלה אם הברכה לכהנים אמורה בפסוק „ואני אברכם” ולא בפסוק „ואברכה מברכיך”:\n„תיבת אני היינו אוא״ס עצמות ומהות”¹⁷ — וזה מורה שברכה זו היא ברכת הקב״ה עצמו, ברכה של־ מעלה מהשתלשלות; משא״כ „ואברכה מברכיך” (בלי תיבת „אני”) היא ברכה שבבחי׳ השתל׳. וזהו הפי׳ ב־ „מוקי לה לברכת כהנים במקום ברכה דישראל”, היינו כשלמדים הברכה ל־ כהנים מ„ואני אברכם”, הרי ברכה זו היא באותה דרגא כמו הברכה ליש־ ראל (ב״כ); משא״כ אם למדים הברכה לכהנים מ„ואברכה מברכיך”, אזי ברכה זו היא בדרגא נמוכה יותר, ברכה שבבחי׳ השתלשלות.\nאך צ״ל: הרי גם „ואברכה מברכיך” היא ברכתו של הקב״ה עצמו¹⁸, ואיך אפ״ל שלדעת ר״ע הלומד ברכה ל־ כהנים מ„ואברכה מברכיך” היא רק ברכה שבבחי׳ השתל׳? ואף שאין כתוב תיבת „אני” בפירוש — ה״ז גופא אי״מ: מה לי אם כתוב „אני” בפירוש, אם לאו — הרי בין כך הכוונה שהקב״ה עצמו מברך!\nומוכרח לומר שיש לו הוכחה נוספת לכך (והוכחה זו היא מכרחת לחלק בין ב׳ הפסוקים), וכדלהלן.\nד. להבין זה צלה״ק תחלה מה דאיתא בגמרא בסיום מס׳ ר״ה¹⁹ על המשנה²⁰: „רבן גמליאל אומר שליח צבור מוציא את הרבים ידי חובתן” (בתפלת מוסף דר״ה): „אמר ר׳ שמעון חסידא פוטר הי׳ רבן גמליאל אפילו עם שבשדות, ולא מבעיא הני דקיימי הכא, (ומקשה) אדרבה הני אניסי הני לא אניסי, (ומביא ראי׳) דתני אבא בר׳ דרב בנימין בר חייא עם שאחורי כהנים אינם בכלל ברכה (ופרש״י: „ואע״פ שעם שבשדות בכלל ברכה, הני דמצו למיתי קמי כהנים ויפנו כהנים אליהם ויברכום והם לא באו אינן בכלל ברכה”), אלא כי אתא רבין אמר ר׳ יעקב בר אידי אמר ר׳ שמעון חסידא לא פטר רבן גמליאל אלא עם שבשדות, מ״ט משום דאניסי במלאכה אבל בעיר לא”.\nוע״פ הנ״ל מובן שראיית הגמרא מב״כ לתפלה (של ש״ץ) אינה רק בזה שמצינו צד השווה בב׳ ענינים שונים, כ״א שבעצם שוים הם —",[["16","16","ועוד השתוות ישנה בין ב״כ לתפלה: ב״כ ה״ה שייך לעבודה (ראה סוטה לח, א־ב). וגם תפלה הרי „תפלות כנגד תמידין תקנום” (ברכות כו, ב)."],["17","17","ד״ה אריב״ל שם (בסופו)."],["18","18","שזוהי המעלה ב„ואברכה מברכיך” על „מברכיך ברוך” (תולדות כז, כט), כי זה שייך גם ע״י אחרים (ע״ד מרז״ל בב״ר פל״ט, יב), משא״כ „ואברכה מברכיך” הפי׳ (ראה ב״ר שם) שהקב״ה עצמו יברך אותו. ראה לקו״ש ח״ה שם."],["19","19","לה, א."],["20","20","לג, ב."]]],[1300101048,"ב׳ הענינים דתפלה וב״כ — בתוכנם, רצון חדש ומשא פנים בדין, שתיהן ממשיכות מלמעלה מהשתלשלות. ולכן מביא ראי׳ מב״כ לתפלה.\nואדרבה: ע״פ הנ״ל מובן, שבד״כ אין להביא ראי׳ מברכה לתפלה, כי אינן דומות כלל: הברכה ענינה הוא המשכה מן המקור שבסדר השתל׳, ובזה עיקר, כמובן, מעלת המתברך והנהגתו, ובפרט כאשר הטעם להעדר ההמשכה הוא מצד חסרון שישנו למ־ טה, א״כ מובן שבכדי להמשיך ע״י הברכה צריך להסיר את המניעה או העיכוב שמצד המתברך;\nמשא״כ תפלה שענינה לפעול רצון חדש — המשכה מלמע׳ מסדר השתל׳, ה״ז תלוי במעלת המתפלל ואין נפק״מ כ״כ המצב בו נמצא האדם שמתפללים עבורו, כיון שההמשכה היא מלמעלה מסדר השתל׳, ולכן גם אפשר להיות שאף אם לא תהי׳ שום הכנה דה־ מקבל, גם אז תפעול התפלה.\nועפ״ז אין ראי׳ מכרחת מברכה (סתם) לתפלה, כי יש לחלק: בברכה מובן למה עם שאחורי הכהנים אינם בכלל ברכה, היות והם מראים שאינם חפצים בהברכה, לכן אין הברכה מו־ עלת מאומה, כמ״ש²¹ „ולא חפץ ב־ ברכה (ובדרך ממילא) ותרחק ממנו”, שהרי בברכה נוגע מצב המתברך; משא״כ בתפלה, הרי אין נוגע כ״כ מצבו, כנ״ל, לכן אף אם המקבל אינו חפץ בזה, מ״מ אפשר שתפלת הש״ץ תפעול פעולתה.\nאך מאחר שב״כ שוה לתפלה, שהן שתיהן המשכה מלמעלה מהשתלשלות, הרי מתאימה הראי׳ ביותר:\nלהיות שב״כ ותפלה שוות הן בענין זה שהן המשכה מלמע׳ מסדר השתל׳, ובזה הרי אין נפק״מ כ״כ מהו רצון ודרגת המתברך, כנ״ל, ואעפ״כ רואים אנו שבכדי להמשיך מלמעלה מסדר השתל׳ צריך להכנה (אם כי לא בתור ממשיך, אלא להיות כלי לקבלה) — דבתפלה הו״ע התפלה עצמה, ובב״כ היא הברכה של הכהנים — בהכנות שלהם כנט״י והדומה, וכמו״כ היא הכנת הישראל שמדקדק ע״ע וכו׳ ומעמיד עצמו פנים כנגד פנים וכו׳.\nע״ז היא הוכחת הגמרא, דכשם שההכנה דב״כ בכדי לקבל ההמשכה דלמעלה מסדר השתלשלות, אינה מס־ פיקה הכנת הכהן עצמו, היינו גוף הברכה שמברך באהבה, הכנת נט״י שקודם הברכה והדומה, אלא שצריכה להיות הכנה גם מצד מקבל הברכה, שיעמוד פנים כנגד פנים (אם אינו אנוס²²), כמו״כ הוא בתפלה, שגם ענינה הוא המשכה מלמעלה מסדר השתל׳, וההכנה היא עבודת התפלה וכו׳, צ״ל בזה עבודה גם מצד האדם שמתפללים עבורו (באם אינו אנוס) בכדי להמשיך מלמעלה מסדר הש־ תלשלות, ולכן מסקנת הגמרא היא, שהש״ץ מוציא דוקא את העם שבש־ דות אבל לא אותן שבעיר.\nה. אמנם יש לומר שראיית הגמרא",[["21","21","תהלים קט, יז."],["22","22","משא״כ כשהוא אנוס. ולהעיר מ־צפע״ג על הרמב״ם הל׳ יסוה״ת פ״ה סוף ה״ד. ולהעיר ממצות המלך, שהמלך מוציא את כאו״א (ראה אגה״ק רסכ״ט). ואין הענין שאין שייך להם ולכן פטורים, כ״א שחייבים בזה (כדמוכח מזה שתרי״ג אברים וגידים כנגד תרי״ג מצות (כמ״ש באגה״ק שם — וראה זח״א קע, ב. מכות כג, ב. תנחומא תצא ב. תז״ח פ״ד. פ״א (עא, ב)) אלא שהמלך מוציא אותם."]]],[1300101049,"היא חזקה יותר, והיא במכש״כ, מצד המעלה נוספת שיש בב״כ על ענין התפלה, ובהקדים:\nזה שהש״ץ מוציא את העם שבש־ דות הוא דוקא כאשר ישנם ט׳ שומ־ עין לו, ובאם לאו — נחשב כיחיד (ואינו מוציא את האינו בקי ואת העם שבשדות²³). משא״כ בב״כ, הנה גם בעיר או ביהכ״נ שכולם כהנים, הדין הוא שכולם נושאים כפים, ולמי מברכים — לעם שבשדות²⁴.\nהיינו שישנו חילוק בין ב״כ לתפ־ לה: בתפלה דוקא ע״י ט׳ שומעין לו נעשה מציאות הש״ץ ויכול להו־ ציאם כו׳, משא״כ בב״כ אין הכהן צריך לנתינת כח מט׳ שומעין לו.\nוהטעם לזה יובן בהקדים המעלה בפרט אחד שבברכה על התפלה²⁵: תפלה היא בלשון — כענינה — בקשה, וכשמבקשים, אין ודאות ש־ תתמלא הבקשה, מפני שההשפעה אי־ נה תלוי׳ בהמבקש; משא״כ ברכה היא בל׳ ציווי (או בל׳ הבטחה), היינו שמצוה כביכול שישפיעו ענין פלוני לפלוני.\nוטעם החילוק הוא: בתפלה, המת־ פלל נמצא למטה, ומבקש שמלמעלה ישפיעו ענין פלוני, וזו בקשה בלבד; משא״כ ברכה, המברך נמצא במדרי׳ שלמעלה מהמקור שממנו באה הבר־ כה, ולכן בכחו לצוות את הברכה.\n[וזה שנת״ל שתפלה היא למעלה מברכה — זהו בנוגע להמקור שמשם נמשכת ההשפעה, דהשפעת הברכה היא ממקור שבסדר השתל׳, והשפעת התפלה היא ממקור שלמע׳ מסדר השתל׳; אבל בנוגע להאדם המברך והאדם המתפלל, הנה המתפלל נמצא למטה ממקור ההשפעה, והמברך נמצא למעלה ממקור ההשפעה].\nעפ״ז מובן שישנה מעלה בברכת כהנים על התפלה²⁶, כי בברכת כהנים ב׳ מעלות: המקור שמשם נמשכת ההשפעה הוא למעלה מסדר השתל׳, ועם זה אמרה תורה שזהו ברכה ולא בקשה, היינו שהכהן המברך הוא למע׳ ממדרי׳ זו, ה״ה נמצא במקום נעלה ביותר, ולכן בכחו לצוות את ההש־ פעה גם ממדרי׳ שלמעלה מהשתל׳.\nנמצא שאף שבענין המדרי׳ שמשם נמשכת ההשפעה, שוות ב״כ ותפלה, אבל בדרגת האדם המתפלל והכהן המברך, שונים המה, שהמתפלל נמצא למטה ומבקש שישפיעו כו׳, וכהן ה־ מברך הוא למעלה במדרי׳ גם ממקור ההשפעה, שהיא — מקור ההשפעה — למעלה מסדר השתל׳.\nועפ״ז יובן מדוע צריך הש״ץ ל־ נתינת כח מהשומעין, ואילו הכהן המברך א״צ לזה: הש״ץ המתפלל נמצא למטה, ולכן זקוק לנתינת כח וכו׳ שיוכל להתפלל ולהוציא יד״ח כו׳; אבל הכהן המברך נמצא למע׳ ביותר מסדר השתל׳, ולכן אין זקוק לנתינת כח מיוחד כו׳.\nוע״פ כהנ״ל תומתק ביותר הוכחת הגמרא מב״כ לתפלה — במכש״ש: ומה ברכת כהנים, שהכהן המברך",[["23","23","ראה שו״ע אדה״ז סקכ״ד ס״ו."],["24","24","סוטה לח, ב. שו״ע אדה״ז סקכ״ח סל״ח."],["25","25","ראה אוה״ת (שנסמן בהערה 9), בד״ה כה תברכו תרנ״ד."],["26","26","אף שיש מעלה בתפלה גם בערך ברכת כהנים (עיין המשך תרס״ו (ע׳ שלו))."]]],[1300101050,"אינו צריך לנתינת כח כו׳ ואין פעולה מהמתברכים (שהרי נמצאים בשדות), ומ״מ עם שאחורי הכהנים אינם בכלל הברכה, לפי שצ״ל הכנת המתברכים בכדי לקבל ההשפעה — כש״כ ב־ תפלה, שהש״ץ צריך לנתינת כח כו׳ הרי מכש״כ שצריכה להיות בזה הכנה מצד הצבור. ולכן אלו דלא אניסי אין יוצאים בתפלת הש״ץ.\nו. עפ״ז י״ל דבזה גופא פליגי ר״ע ור״י — היינו אם דרגת הכהן — בעת שמברך את ישראל — היא למעלה מהשתלשלות או לא, ובזה תלוי׳ פלוגתתם אם צ״ל קרא מיוחד שהקב״ה מסכים על הברכות, וכדלהלן:\nנת״ל (ס״ב) שהטעם לזה שב״כ בכחה להביא ענין חדש הגבוה משרשו ומקורו של המתברך, הוא, לפי שה־ כהנים עושים זאת בשליחותו של הקב״ה, ומכיון שהוא אינו מוגבל ח״ו בשום מדידות והגבלות, יש בברכתו, וגם בהברכות המתברכות בשליחותו, הכח להגיע למעלה מהשתל׳.\nאמנם זה גופא אפ״ל בב׳ אופנים: א) מכיון שהברכה בפועל נאמרת מפי בו״ד, שאין בכחו מצ״ע להמשיך מ־ למע׳ מהשתל׳, צ״ל כח מיוחד, שגם ברכה זו תמשיך מלמע׳ מהשתל׳, ז. א. שאף שמברך בשליחותו של הקב״ה, מ״מ הרי כמה דרגות אפ״ל בשליחות²⁷ — וגם בב״כ י״ל שאין כחו של הקב״ה מתייחד ומתעצם עם ברכת הבו״ד, ויש פרטים²⁸ שמוגבלת בהם כמו ברכת בו״ד. וצ״ל כח מיוחד שגם ברכה זו תהי׳ ברכתו של הקב״ה.\nב) מכיון שעושה זאת בשליחותו של הקב״ה הרי „מעשה השליח מת־ ייחס להמשלח”, יש בהברכה עצמה הכח להמשיך מלמעלה מהשתל׳²⁹. ז. א. שכחו של הקב״ה מתעצם עם (ברכת) הכהן, ובמילא דרגת הכהן עצמו בעת הברכה היא למעלה מ־ השתל׳ כנ״ל.\nוי״ל שלדעת ר״ע, ב״כ מצ״ע הוא ברכת בו״ד (כאופן הא׳), ולכן צ״ל קרא מיוחד שהקב״ה מסכים על ידם³⁰ — היינו שישנו כח מיוחד מהקב״ה שהברכות תהיינה ברכות הקב״ה, מ־ למע׳ מהשתל׳, שזהו הפי׳ ד„הקב״ה מסכים על ידם”. משא״כ ר״י (כהנא — מסייע (ומגדיל כח) כהני) לדעתו שיש בברכת הכהנים מצ״ע כח זה ואי״צ לזה קרא³¹ מיוחד³².",[["27","27","ראה לקח טוב (להר״י ענגל) בתחלתו. וראה גם שו״ע אדה״ז סרס״ג סכ״ה בקו״א: כעושה בעצמו ממש וכו׳ הרי זה כאילו אוחז ידו של חבירו כו׳ שנעשית כידו אריכתא. ועיין המשך רס״ו בביאור ענין העבודה דמדרי׳ עבד (ע׳ שכו־ז)."],["28","28","אבל לא כולם, ולכן אומרים ישא הוי׳ — משא פנים, אבל גם בזה עצמו הגבלה — שצ״ל „מדקדקים ע״ע”."],["29","29","וראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830020\" data-slug=\"or-hatorah-hb\" data-id=\"8158830020\">אוה״ת נשא</a> (שבהערה 9) „הכהנים זרע אהרן שרשם מנצח דאבא כו׳ ע״כ מצווים ואומרים כו׳”. ובד״ה כה תברכו תרנ״ד (שבהערה שם): „דלהיות שהכהנים שרשם מבחי׳ רב חסד דעתיק כו׳”."],["30","30","וכמ״ש בפי׳ הרי״ף (על הע״י שם): „דאעפ״י שצוה אותם לברך ומסכים עמהם, מ״מ אינם אלא מפי בו״ד, ואינו דומה למתברכים מפי הגבורה ולכך איצטריך ל־ר״ע”. וע״פ מ״ש בפנים בדעת ר״י מתורץ גם מה שהקשה שם: „אבל לר״י קשה מנ״ל דישראל מתברכין מפי הגבורה”."],["31","31","וי״ל ג״כ שזוהי כוונת התוס׳ במ״ש דלר״י „פשיטא דמסכים, כיון שציוה להם לברך”, משא״כ לר״ע אי״ז פשיטא, כבפנים."],["32","32","ואעפ״כ אזלא סוגיית הגמרא בסיום מס׳ ר״ה גם לדעת ר״ע, כי בלאה״כ מובנת"]]],[1300101051,"בסגנון אחר קצת: ענין ברכות כה־ נים כמו שהוא במקורו (למעלה מסדר ההשתלשלות) — ניתן כולו ל„בעלות” של כהנים³³ ואין צריכים הסכמה נו־ ספת.\nעפ״ז מובן שלדעת ר״ע הברכה לכהנים היא ברכה שבבחי׳ השתל׳: מכיון שלדעתו ב״כ בעצם (כפי שנא־ מרת מפי הכהנים) אינה למעלה מסדר השתל׳, הרי אאפ״ל שהמסובב (הברכה לכהנים הבאה ע״י ברכתם שמברכים את ישראל) תהי׳ בדרגא גבוה יותר מהסיבה (הברכה שהם מברכים את ישראל). ולכן מוכרח לומר שהברכה לכהנים היא מבחי׳ השתל׳. משא״כ לדעת ר״י שברכת כהנים בעצם היא מבחי׳ שלמעלה מסדר השתלשלות — מסייע (ומגדיל הברכה שמתברכים) כהני ולדעתו גם הברכה לכהנים היא מבחי׳ זו.\nומטעם זה גופא מובן למה אין מפורש בכתוב „ואברכה מברכיך” תיבת „אני”, כי הברכה הנלמדת מפסוק זה היא מבחי׳ סדר ההשתל׳³⁴.\n(משיחת כ׳ מנ״א, תשי״ב)",[["","","הראי׳ מברכת כהנים לתפלה, כנ״ל ס״ד."],["33","33","עיין סוף הדרן לפסחים (נדפס בסוף הגש״פ עם לקוטי טעמים מנהגים וביאורים, קה״ת תשל״ט — ע׳ תקיג) שיטות רש״י ורע״ק בזה."],["34","34","להעיר מהחילוק דהמשכה ע״י מעבר או ע״י התלבשות (קו״א ד״ה להבין מ״ש בפע״ח (קנה, א). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380681\" data-slug=\"likkutei-torah\" data-id=\"4001380681\">לקו״ת מסעי פט, ב</a>. ובכ״מ)."]]],[1300101052,"<h3>לך לך ב</h3>\nא. בפרשתנו ¹ מסופר ע״ד ציווי הקב״ה לא״א לימול את עצמו וב״ב, ובקיומו ציווי זה נעשה „ראש למו־לים״ ² — ראש וראשון לכל הנכנסים בכריתות־הברית־קודש שבין הקב״ה וכאו״א מישראל.\nועד שבנוסח הברכה לברי״מ אנו אומרים: „להכניסו בבריתו של א״א״ ³ — והיינו שברית המילה המתקיימת עתה היא משתייכת ומתייחסת לזו של אברהם אבינו — דלהיותו „(אברהם) אבינו״ הרי הוא מוריש ומנחיל ל־כאו״א מבניו ⁴ היורשים את הכח להי־כנס בברית עם הקב״ה ⁵. ובגדרי ה־ירושה הלא ידוע:\nא) שהירושה אינה תלוי׳ כלל ב־מצבו והכנתו של הבן לרשת, כי גם תינוק בן יומו יורש הכל.\nב) שאין בירושה משום שינוי רשות המוריש ⁶, כ״א שהיורש נכנס במקומו של המוריש ממש ⁷.\nמזה מובן אשר בריתו של כ״א מישראל היא „בריתו של א״א״, שהרי כחו והכשרתו להיכנס בברית זו באו לו בירושה מא״א, ומכיון שהיורש — מבלי הבט על מצבו — נכנס במקומו של המוריש כנ״ל, א״כ הרי ברית שלו היא בריתו של א״א.\nב. אבל צריך להבין:\nהרמב״ם ⁸ כתב בביאור מצוה זו: „אין אנו מלין מפני שא״א ע״ה מל עצמו ואנשי ביתו אלא מפני שהקב״ה ציוה אותנו ע״י משה רבינו שנמול״, הרי מובן, דאף שהכח על קיום מצות מילה ניתן בירושה מא״א, מ״מ המצוה עצמה, כפי שהיא מוטלת עלינו, אינה המשך בירושה מ„בריתו של א״א״, רק שמיוסדה ומתחילה ⁹ בציווי הקב״ה ע״י משה — וא״כ למה נקראת מצוה זו „בריתו של א״א״?\nובפרט לפי מאמר המדרש ¹⁰: „כל המצות שעשו לפניך האבות ריחות היו אבל אנו שמן תורק שמך״, הרי שבקיום המצות שלנו יש עדיפות ומעלה יתירה על קיומן ע״י א״א, בדוגמת מעלת גוף השמן על ריחו,",[["1","1","יז, ט ואילך."],["2","2","פתיחתא דאסת״ר י."],["3","3","שבת קלז, ב. טושו״ע רסה, א."],["4","4","להעיר ממחז״ל „מעשה אבות סימן לבנים״ (אוה״ת ר״פ לך. וראה רמב״ן בראשית יב, ו: „כל מעשה שאירע לאבות סימן לבנים״ וראה שם יב, יו״ד. וראה ב״ר פ״מ, ו), בארוכה בלקו״ש ח״ג ע׳ 758 ואילך."],["5","5","שהרי ענין זה ישנו בטבע כאו״א מבנ״י וכדמשמע גם מהא דהנודר ממולים אסור (גם) בערלי ישראל (נדרים לא, ב). וזה מורה שזהו בגילוי בעולם כי „בנדרים הלך אחר לשון בנ״א״ (נדרים ל, ב וש״נ)."],["6","6","ב״ק קיא, ב. ב״ב מד, א וברשב״ם שם ד״ה הניחא."],["7","7","שו״ת צ״צ דרוינסק ח״א סי׳ קיח. וראה צ״צ ח״א נ. י. סי׳ קיח: דהוא עצם האב."],["8","8","פיה״מ חולין ספ״ז."],["9","9","ואפי׳ את״ל שיש בזה גם המשך ציווי הקב״ה לאברהם — אין סברא להזכיר את הטפל ולהשמיט את העיקר!"],["10","10","שהש״ר פ״א, ג."]]],[1300101053,"וא״כ איך יתכן אשר מצות מילה שאנו מקיימים הרי היא בריתו של א״א?\nגם צריך להבין: לשון הברכה „בבריתו של א״א״ מדגישה ענין א״א. ולכאורה עדיף יותר להדגיש שהברית היא עם הקב״ה, דהיינו: ל„הכניסו בברית עם הקב״ה״.\nג. ויובן זה בהקדים דברי אדה״ז בשלחנו ¹¹ אשר „תחלת כניסת נפש זו הקדושה היא כו׳ במצות מילה״.\nולכאורה אינו מובן: גם קודם לידת התינוק, בהיותו עוד במעי אמו, „מלמ־דין אותו כל התורה כולה״ ¹², הרי שגם טרם הוולדו נמצאת בו נפש הקדושה ¹³ שהיא היא הלומדת את „כל התורה כולה״ — ואיך יתאים זה עם המובא לעיל שתחילת כניסת נפש הקדושה היא בעת הברי״מ, שהוא יום השמיני ללידתו?\nוהביאור בזה: „כניסת נפש הקדו־שה״ פירושה — חיבור פנימי של הנשמה עם הגוף, ועד להתאחדות והתעצמות למציאות אחת, שאז ניכרת ונראית פעולתה של הנשמה בגוף, משא״כ כשהעובר במעי אמו, עם ש־כבר ישנה בו הנפש דקדושה, בכ״ז לא זו בלבד שנשמתו זו טרם „נכ־נסה״ ונתאחדה בגופו כנ״ל, אלא גם פעולתה של נפשו החיונית אינה ני־כרת ונרגשת עדיין בגופו — שהרי הוא אוכל ושותה וניזון ממה שאמו אוכלת וכו׳ ¹⁴.\nוגם לאחרי שנולד, שהנפש כבר באה אז לידי חיבור עם הגוף, הרי מה שניכר ונגלה בגופו הוא לא פעולתה וחיבורה של הנפה״א (שהיא עדיין בו בבחי׳ העלם ומקיף), כ״א של נפשו החיונית. כניסתה הפנימית של נפש הקדושה בגוף והתחברותה הגלוי׳ הריהי נפעלת וניכרת דווקא ע״י הברי״מ, מפני שנעשה אז „בריתי בבשרכם לברית עולם״ ¹⁵ — שהברית עם הקב״ה טבועה וחתומה בבשר הגוף הגשמי, ועד „לברית (הנראית וניכרת גם לאומות ה)עולם״.\nד. וזוהי מעלתה של מצות מילה על שאר המצות:\nכל המצות ענינם לחבר את האדם המקיימן עם הקב״ה המצווה — מצוה ל׳ צוותא ¹⁶ וחיבור — אבל אין חיבור זה ניכר בגוף המקיים המצוה ¹⁷. עד״מ היד המחלקת צדקה, אף שבודאי פעלה מצוה זו שינוי גם במציאותה הגשמית של היד — אבל אין זה שינוי הנראה וניכר בבשר הגשמי של היד. משא״כ במצות מילה, ויתרה מזו — כל ענין המצוה הוא שהשינוי ע״י בריתו עם הקב״ה יהא ניכר בבשר הגוף — לעיני בשר, וגם לאוה״ע, כנ״ל.\nובזה גדלה מעלתה של כריתת־הברית דמילה על כריתת־הברית ד־חורב (וכיוצא בה): הברית שכרת הקב״ה עם בנ״י בסיני ובערבות מואב הי׳ גם עם אלו שלא היו נוכחים שם בגופם, כ״א בנשמתם, וכמ״ש ¹⁷*:",[["11","11","או״ח מהדו״ת סוס״ד."],["12","12","נדה ל, ב."],["13","13","ואדרבא — אז היא במצב נעלה יותר, שהרי עדיין אין נפה״ב המבלבלה — כמבואר בסנה׳ (צא, ב)."],["14","14","נדה שם."],["15","15","פרשתנו יז, יג."],["16","16","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380272\" data-slug=\"likkutei-torah\" data-id=\"4001380272\">לקו״ת בחוקותי מה, ג</a>. ד״ה רבי אומר ש״ת ספ״א ואילך. ביוהשמע״צ השי״ת בתחלתו. התמים ח״א ע׳ כה ואילך. ובכ״מ."],["17","17","להעיר מתניא קו״א רד״ה להבין מש״כ בפע״ח. *17) דברים כט, יד."]]],[1300101054,"„כי את אשר ישנו פה גו׳ ואת אשר איננו פה עמנו היום״, ומבואר ב־פדר״א ¹⁸ שכריתות־ברית זו היתה גם עם הדורות שעברו וגם עם הדורות העתידין לבוא, היינו שכריתות־הברית היתה עם הנשמות שכולם היו שם באותו מעמד, וכל׳ הידוע בנוגע ל־כאו״א מבנ״י כולל הגרים: מושבע ועומד מהר סיני ¹⁹.\nיתירה מזו: אלו שהיו נוכחים שם בגופם, הרי גם הם באו ב„ברית״ רק בזה ששמעו את דברי הברית מפי משה; דעם היות שהשמיעה נתפסת באוזן, אחד מאיבריו הגשמיים של האדם, מ״מ אין האוזן אלא בחי׳ אמצעי שע״י „שומעת״ הנשמה (בכוח השמיעה הרוחני שלה), ומקבלת את הדבר הנשמע. ומובן מזה, שכריתות־הברית אשר בערבות מואב (והדומות לה) היתה בעיקר עם נשמותיהן של ישראל, משא״כ כריתות־הברית דמי־לה, אשר ענינה להיות „בריתי ב־בשרכם לברית עולם״, ש(גם) בשר הגוף הגשמי — ועד ל„סוד סיומא דגופא״ ²⁰ — יתקשר בברית עולם עם הקב״ה, כנ״ל, שעי״ז נעשה „דירה לו ית׳ בתחתונים״ ²¹ — בתחתון שאין למטה ממנו ²².\nוזהו כל ענינה של מצות מילה: בהיות התינוק בן שמונת ימים, בעת שמושלל עדיין מכל ענין של דעת והבנה והשגה, מצד גילוי הנשמה וכ־חותיו הרוחניים הרי אינו שייך ליכנס בברית עם הקב״ה, ובכל זאת הטילה",[["18","18","פמ״א. שמו״ר ספכ״ח. תנחומא נצבים ג. זח״א צא, א. זח״ב פג, ב. ת״ז תמ״ט (פו, א)."],["19","19","שבועות כב, ב."],["20","20","הקדמת תקו״ז (יז, א)."],["21","21","תנחומא נשא פס״ז."],["22","22","<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל״ו</a>. התורה עליו ²³ להיות נימול בגיל זה — לפי שכל ענין הברי״מ הוא שבשר הגוף הגשמי שלו יתקשר בברית עם הקב״ה כנ״ל, וזה יתכן גם (ועוד יותר) בתינוק בן ח׳ ימים. ה. ועפ״ז יתבאר גם נוסח הברכה: „להכניסו בבריתו של א״א״: ב„פרי הארץ״ ²⁴ מהרמ״מ מהארא־דאק מבוארת ההפלאה של נסיון ה־עקידה באברהם אבינו, דעם היות שהרבה מבנ״י (גם אנשים פשוטים) במשך הדורות עמדו בנסיון המס״נ (ואפילו בדומה לזו של „עקידה״) גם מבלי ששמעו על זה ציווי מפורש מהקב״ה בעצמו — ומ״מ גדלה מעלתו של א״א ע״ה עד להפליא בנסיון ה־עקידה — והטעם הוא, לפי שא״א הי׳ הראשון שעמד בנסיון זה ובכל כגון דא הרי להיות ה„ראשון״ הוא דבר קשה ביותר ²⁵. אבל לאחרי שה„ראי־שון״ כבר „פתח את הצינור״ ²⁶ וסלל את הדרך — אז נעשה זה בנקל יותר לבאים אחריו ²⁷, כי הם הולכים ב־דרכיו ואורחותיו ²⁸. ---"],["23","23","ראה בביאור לספהמ״צ לרס״ג לה־ר״י״פ פערלא מצוה לא־לב: עיקר חובת המצוה עלי׳ דקטן גופא הוא דרמיא, וע״ש שהוכיח כן מהאו״ז. ואפי׳ את״ל שעיקר החיוב הוא על האב, מ״מ הרי המצוה מתקיימת בהבן קטן."],["24","24","ס׳ וירא, ועיין אגה״ק סכ״א. וי״ל."],["25","25","ראה מכילתא ורש״י יתרו יט, ה: כל התחלות קשות."],["26","26","וכידוע בענין פתח ר׳ פלוני כו׳. ראה דרך חיים ע׳ 65."],["27","27","ולכן הי׳ הה״מ „נוהג כשנפלה לו איזה השגה הי׳ אומרה בפה אף שלא יבינו השומעים . . בכדי להמשיך ההשגה . . בזה העולם ואזי . . יוכל אחר . . להשיגה״ (מאה שערים ע׳ כח)."],["28","28","עפ״ז יש להוסיף ביאור באגה״ק סכ״ז בדיוקו „מדרכיו״ „באורחותיו״."]]],[1300101055,"אמנם כל זה הוא בענין התלוי בהבנתו והרגשתו של האדם ובעבודתו, שבכדי שיוכל להתגבר בכחות שלו על הקשיים והמניעות בענין זה — כש־יודע וכשמרגיש שכבר קדמהו בזה ה„ראשון״ (ובפרט כשהוא אביו) ופתח את הצינור „עבורו ועבור כל בנ״י״ ה״ז מסייע לו בעבודתו הוא. אבל כשהנידון הוא בענין שאינו קשור בידיעתו ופעולתו, כ״א בפעולה הנע־שית בגופו בלי הכשרה והכנה מצדו — ובפרט בתינוק שאין בו שום שליטה והשפעה של כחותיו הרוחניים — הרי לא יתן ולא יועיל לו מאומה מה שהדבר כבר נעשה לפניו; וא״כ הרי במובן זה אין הפרש בינו ולבין ה„ראשון״ — בפעולה זו הרי הוא „ראשון״, כי אין לו סיוע מהבא לפניו.\nובאמת שכן הוא גם בגדול (וגר) המקיים מצות מילה — אף שכבר יש לו דעת והרגש וכו׳ — דלהיות שכל עיקרה של מצות מילה הוא להכניס את הבשר הגשמי ממש (ע״י פעולה גשמית) בברית עם הקב״ה, וכפי ש־נתבאר לעיל בארוכה, הרי מובן שב־פעולת הברית עצמה אינו פועל אותו העזר והסיוע הבא דרך הכחות הרוח־ניים ופועל בהם וע״י (היינו שנתינת הכח הבא מהראשון (ואפילו זו הבאה בתור סגולה כירושה) שייכת רק ב־ההכנה וההכשרה הרוחנית ליכנס ב־ברית המילה, אבל לא בהפעלת והט־בעת הברית בגשם הגוף). ולפי״ז הרי כל אחד ואחד המקיים מצות ברי״מ, בין קטן ובין גדול הריהו בבחי׳ ראשון במובן זה.\nובזה יובן מה שאנו אומרים „להכ־ניסו בבריתו של א״א״: כי ענינו ומעלתו של א״א הוא בזה שהי׳ ה־\nראשון, כנ״ל, ומכיון שכל אחד מבנ״י המקיים מצוה זו הריהו ג״כ בבחי׳ „ראשון״, א״כ הוא נכנס „בבריתו של א״א״ ממש ²⁹.\nו. לפי הנ״ל יתבאר ענין נוסף ה־דורש ביאור: מדוע קשור ענין ה־ברי״מ בדבר הגורם „צערא דינו־קא״ ³⁰? ובפרט — שהשמחה הוא עיקר בעבודת ה׳ — וכמ״ש ³¹ „עבדו את ה׳ בשמחה״ ³², וא״כ למה נצטווינו מהקב״ה לעשות מצוה גדולה וחמורה זו ³³ דוקא באופן של צער — היפך ענין השמחה?\nואף שזה שפעולת המילה גורמת צער הוא לפי שכן הוא טבע הגוף בכל פעולות כיו״ב — אמנם מכיון שכל ענינו העולם הם מדויקים ומ־כוונים כפי שענינים אלו הם למעלה בשרשם (כיון „שנשתלשלו מהם״ ³⁴) ומכ״ש בענין של מצוה — הרי מובן",[["29","29","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051101\" data-slug=\"likkutei-sichot\" data-id=\"1300051101\">ע״פ</a> מ״ש בפנים יומתק המשך לשון הרמב״ם בפיה״מ שם: „שנמול כמו שמל אברהם אבינו ע״ה״ — (דלכאורה, מה מקום להדגיש שנמול כא״א והרי אנו מלין רק מפני הציווי למשה רבינו כתחלת ל׳ הרמב״ם שם) — כי הברי״מ שלנו היא ג״כ בבחי׳ ראשון „כמו שמל א״א ע״ה״. וראה לקו״ש ח״ה ע׳ 89 הערה 25."],["30","30","כתובות ח, א. ועד שי״א (אבודרהם ברכות שער ג. הגהמ״י מילה פ״ג ה״ג, בשם י״מ, ועי׳ תוס׳ סוכה מו, א ד״ה העושה) שמטעם זה אין מברכין שהחיינו במצות מילה."],["31","31","תהלים קב, ב וראה רמב״ם סוף הלכות לולב."],["32","32","ובכללות — אדרבא מצות מילה „קבלו עליהם בשמחה״ ובשמחה גשמית — „שעושין משתה״ (שבת קל, א. וב־פרש״י)."],["33","33","ראה רמב״ם סוף הל׳ מילה."],["34","34","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא רפ״ג</a>. וראה בהנסמן לעיל ע׳ 8 הערה 14."]]],[1300101056,"שענין הצער בברי״מ הוא בכוונה וב־תכלית מיוחדת.\nובפרט לפי סברת אחרונים ³⁵ ש־מצות מילה צריכה להיות דוקא ע״י צער. (ולכן אין להרדים את הנימול, כולו ³⁶ או חלקו, שלא ירגיש את הכאב) — הרי בודאי שהצער הוא ענין עיקרי במצות מילה.\nוהביאור בזה:\nענינה של מצות מילה הוא להמשיך אלקות גם בבשר הגשמי שבגוף, שבזה נעשה לו יתברך „דירה בתחתונים״, ז. א. שגם בתחתון ביותר, וכמו שהוא בתחתוניותו — עושים דירה לו ית׳, ולכן צ״ל דוקא בבשר כמו שהוא בטבעו הוא; מוגדר בכל תכונותיו — אשר גם בבשר כזה שהוא מרגיש צער בדבר (מצוה) שצ״ל בו ההיפך מזה (השמחה), גם בדרגא כה נמוכה פועלים שתתקשר בברית עולם עם הקב״ה ³⁷.\nז. וההוראה מזה:\nאדה״ז כותב בשולחנו ³⁸: „אין ל־אדם רשות על גופו כלל כו׳ לצערו בשום צער״, ומובן מזה בפשטות שאין האדם רשאי לחפש אחרי התעסקות בענין אשר יגרום לו צער. ובכ״ז כשהנידון הוא בענין של שליחות לעשות לו ית׳ דירה בתחתונים, אז, הרי אדרבה, אינו רשאי להימנע מזה מחמת הצער הקשור בזה — ו„בהדי כבשי דרחמנא למה לך״ ³⁹, ואולי דוקא באופן זה הוא ממלא את תפ־קידו ושליחותו.\nומזה מובן דמי שהוטל עליו תפקיד של „שליחות״ כזו, אינו יכול להעמיד על שיקול דעתו האם לקבל את ה־שליחות או לא, כי אדם קרוב אצל עצמו ⁴⁰ ואפשר שיטה ויסלף שכלו ובלבד להשתמט מהשליחות מפני ה־צער, ואם כי אפ״ל שעליו להודיע למשלח אשר (של השליח) לדעתו יהי׳ לו צער וכיו״ב, אבל ההחלטה עצמה צ״ל של המשלח (אשר בודאי אין לו פניות ח״ו).\nואדרבא, כשיתמסר לתפקידו בכל כחותיו הוא, נוסף על כחו של המשלח, בודאי יצליח וימלא את השליחות ה־מוטלת עליו כדבעי — ובלי צער ויסורים ⁴¹, כ״א בשמחה וטוב לבב — ויעשה לו יתברך דירה בתחתונים.\n(משיחת ש״פ פנחס, י״ט * תמוז, תשל״ב)",[["35","35","שו״ת אמרי יושר ח״ב סק״ב. וראה שו״ת מערכי לב חיו״ד סי׳ נג שחולק."],["36","36","ראה ספר כורת הברית, נחל ברית סי׳ רסא ס״ד, שאז יש שאלה נוספת מטעם דמצות צריכות כוונה ודעת. אלא שבנוגע לגר כתב בשו״ת דבר אברהם (ח״ב סי׳ כה) שהמילה אינה מצוה כלל, כ״א הכשר. ובשו״ת לב ארי׳ סי״א (להרא״ל גרוסנס שי׳ — לונדון תשי״ח) ר״ל שעפ״ז מותר להרדימו לכל הדיעות."],["37","37","להעיר (בנוגע לאברהם) מב״ר (פמ״ז, ט): הרגיש ונצטער כדי שיכפול לו הקב״ה שכרו. ועפ״מ מ״ש בפנים, יומתק מה שבמדרש שם מקשה כ״כ בחריפות על המ״ד שלא נצטער — כי כנ״ל הצער הוא ענין עיקרי במצות מילה, וא״כ מובן שב־א״א שהי׳ „ראש למולים״ בודאי לא הי׳ חסר אצלו ענין עיקרי זה. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051092\" data-slug=\"likkutei-sichot\" data-id=\"1300051092\">לקו״ש ח״ה ע׳ 80</a> ואילך ובהערה 40 שם."],["38","38","הל׳ נזקי גוף ונפש ס״ד."],["39","39","ברכות י, א."],["40","40","סנה׳ ט, ב. וש״נ."],["41","41","עיין אגה״ק סכ״ב. *) ביום זה (י״ט תמוז, תר״מ) הוכנס כ״ק אדמו״ר (הריי״צ) בבריתו של א״א."]]],[1300101057,"<h3>וירא</h3>\nא. ארז״ל¹ שספר בראשית נקרא בשם „ספר הישר״, לפי ש„זה ספר אברהם יצחק ויעקב שנקראו ישרים״. אמנם, אף שהספר (בראשית) בכללותו נקרא על שם כל שלשת האבות, דהיינו שכל כולו של ספר „הישר״ משתייך (בפנימיותו) לג׳ ה„ישרים״ כולם², הרי בפרטיות יש בו פרשיות שהמדובר העיקרי (הגלוי) בהן הוא באחד משלשת האבות ביחוד.\nוהנה, הפרשיות שכל תוכנן מתייחס לאברהם במיוחד — הן פ׳ לך־לך ופ׳ וירא³.\nומזה שנחלקו לב׳ פרשיות, עם היות ששתיהן ענינם אחד: אברהם אבינו, הרי מוכרח שבהן מתבטאות שתי „פרשיות״ וסוגים בענינו ומע־ לתו של א״א⁴; ומכיון שמעלתו של א״א היא עבודתו להוי׳, הרי ב׳ ה־ פרשיות הן שתי מדריגות בעבודתו הנעלית של א״א. ומזה, שההפרש שבין שתי המדריגות (שתי הפרשיות) של אברהם אבינו יש להבין משני השמות של פרשיות אלו⁵, דהרי שמה של הפרשה מרמז ומוכיח על תוכנה, כמבואר כמה פעמים⁶.\nוהנה החילוק העיקרי (בתוכן מע־ לתו של אברהם) בין פ׳ לך לך ופ׳ וירא: בפ׳ לך לך המדובר הוא במד־ ריגת א״א כמו שהי׳ קודם היכנסו בברית־המילה (ורק בסופה מסופר איך שנצטווה מאת ה׳ למול א״ע ואת ב״ב, ושכן עשה⁷); ובפ׳ וירא מדובר בא״א לאח״ז שכבר קיים מצות מילה —",[["1","1","<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670362\" data-slug=\"torat-chaim\" data-id=\"2300670362\">ע״ז כה, א</a>. וראה תו״ח לך (פה, ד)."],["2","2","כדמוכח מהלשון „זה ספר אברהם יצחק ויעקב״ — שהספר משתייך לכל הג׳ אבות."],["3","3","ואף שגם בפ׳ חיי שרה מדובר אודות אברהם — הרי שם גם עניני יצחק הם מהענינים העיקריים שבסדרה (וכ״ש שכן הוא בהנוגע פ׳ נח — אף שבסופה מדובר אודות אברהם)."],["4","4","ע״ד המובן במרז״ל (תענית כז, ב. מגילה כב, א) „כל פסוקא דלא פסקי׳ משה אנן לא פסקינן לי׳״, שמכיון שלא נפסקו בתורה הרי זה מורה שכל עניני פסוק אחד שייכים ביחד, ועד״ז להיפך שאותם הפסוקים שנפסקו בתורה ה״ז לפי שהם ב׳ ענינים נפרדים — עד״ז בפיסוק הפרשיות (ראה זח״ב רו, ב), שמאחר שנפסקו לב׳ פרשיות ה״ז מורה שהם ב׳ ענינים נפרדים (ולכן גם קריאתם וה־ לימוד למעשה מתוכנם — כפתגם אדה״ז הידוע* — בזמנים נפרדים). ובנדו״ד ש־ עיקר פרשיות אלו הוא אודות אברהם, ה״ז מורה שהם ב׳ ענינים שונים באברהם עצמו."],["5","5","ובפרט ששמות ב׳ פרשיות אלו הם אודות אברהם: „לך לך״ הוא הציווי לאברהם לילך כו׳; „וירא״ הוא גילוי הקב״ה לאברהם."],["6","6","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051058\" data-slug=\"likkutei-sichot\" data-id=\"1300051058\">לקו״ש ח״ה ע׳ 58</a>."],["7","7","וגם זה — עד יום ג׳ למילתו (ר״פ וירא) שעדיין לא נתרפא ממילתו, שאי״ז עדיין תכלית ענין המילה — דהרי ענינה של מצות מילה הוא ברית עולם בבשר הגוף הגשמי (כמבואר לעיל ע׳ 45 ואילך. וראה להלן ס״ג), וכל זמן שלא נתרפא (ושיודעים שיצא מהסכנה — והרי בשלישי למילה מחללין עליו את השבת (שבת קלד, ב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051089\" data-slug=\"likkutei-sichot\" data-id=\"1300051089\">לקו״ש ח״ה ע׳ 77</a> ואילך בארוכה)) — אין בירור כ״כ שהברית עולם הוא בר קיימא בגשמיות. *) היום יום ע׳ קא. ובארוכה — סה״ש תש״ב ע׳ 29 ואילך."]]],[1300101058,"והפרש זה נרמז גם בשמותיהן, „לך לך״, „וירא״.\nב. אי׳ בזהר⁸, דעד שלא נימול אברהם היתה דרגת נבואתו בבחי׳ „הי׳ דבר ה׳ אל אברם במחזה״⁹; משא״כ בזמן שלאחרי הימולו, כתיב „וירא אליו ה׳״¹⁰, שהיא דרגא נע־ לית יותר¹¹. והטעם ע״ז מבואר שם: לפי שמלאכי השרת אינם נזקקים בלשון תרגום¹², ולכן עד שנימול הי׳ הגילוי אליו בבחי׳ „מחזה״, שהוא לשון תרגום, כדי שלא יהי׳ פתחון פה למלאכי השרת שהקב״ה מתגלה לאדם שאינו מהול; אבל לאחר שמל, שאין להם עוד פתחון פה, נתגלה אליו בבחי׳ „וירא״, בלה״ק, המורה על מדריגה עליונה יותר.\nויש להקשות: ממה נפשך — אם א״א מצ״ע הי׳ ראוי גם קודם לכן לגילוי הנעלה — למה יגרע חלקו של אברהם אבינו (המגיע לו) משום חשש של קטרוג המלאכים? והרי הרבה דרכים למקום שבהן ועי״ז אפ־ שר למנוע את פתחון הפה של המל־ אכים גם אם הי׳ הגילוי באופן המגיע לא״א, אופן הנעלה;\nואם מצד מהותו ומעלתו של א״א לא הי׳ ראוי עדיין לגילוי נבואה באופן נעלה, מה צורך בטעם שלא יהי׳ פתחון פה למלאכי השרת, מכיון שבלא״ה לא הי׳ ראוי אז לגילוי זה?\nג. ויובן זה בהקדים המבואר ב־ תו״א¹³ שההפרש בין לשון הקודש ללשון תרגום (ארמית — ושאר ה־ לשונות) הוא בדוגמת ההפרש שבין אבנים ללבנים: אבן היא בריאה בידי שמים ולבינה נעשית בידי אדם, ועד״ז הוא החילוק בין הלשונות הנ״ל, גם בין אותיותיהן שמהן הן „בנויות״¹⁴: אותיות התורה נקראות „אבנים״, כי התורה היא מן השמים; אבל האו־ תיות של לשונות האומות נק׳ „לב־ נים״, (שהן מוסכמות ע״י בנ״א לבד) [ותכלית הכוונה במציאותן של לשו־ נות (אותיות) האומות, שגם הם ית־ בררו ויתעלו לקדושה ע״י שישתמשו בהן לעבודת הוי׳].\nוע״פ הנ״ל בזהר י״ל שההפרש בין מעלת אברהם אבינו קודם המילה ולאח״ז, הוא בדוגמת החילוק הנ״ל שבין אבן ללבינה:\nמבואר בכ״מ¹⁵ שאף ש„קיים א״א כל התורה כולה עד שלא ניתנה״¹⁶ מ״מ הגיע אז בעבודתו במעלות הקודש רק עד שרש הנבראים; לפי שכל עבודתו ופעולתו הי׳ בכח עצמו, בלי ציווי (שזהו גם נתינת כח) מלמעלה (ואין בכחו של נברא להגיע למעלה ממקורו, שרש הנבראים).\nאמנם כל זה הי׳ עד שקיים מצות מילה (שאופן קיומו של כל התורה הוא „עד שלא ניתנה״, עד שלא נצ־ טווה בציווי מיוחד¹⁷) משא״כ כש־",[["8","8","ח״א פח, סע״ב. וראה שם צח, רע״א."],["9","9","לך טו, א."],["10","10","ואף שגם קודם לזה כתוב (לך יב, ז. שם יז, א) „וירא ה׳ אל אברם״ — כבר תירץ את זה בזהר שם."],["11","11","וראה ב״ר ר״פ וירא. מפרשים ר״פ וירא."],["12","12","ראה שבת יב, ב."],["13","13","משפטים עז, ג."],["14","14","ראה ספר יצירה בתחלתו."],["15","15","ראה שהש״ר פ״א ע״פ לריח שמניך גו׳: כל המצות שעשו לפניך ריחות היו וכו׳, וראה לקו״ש ח״ג ע׳ 757 ואילך."],["16","16","קדושין פב, א. יומא כח, ב."],["17","17","משא״כ הציווי דו״מ וכ״ג — דלא"]]],[1300101059,"נצטווה במצות מילה מהקב״ה, שבציווי זה הרי ניתן לו כח מיוחד מלמעלה להתעלות לדרגת ביטול והתאחדות עם הבורא, מצַוֶה המצוה, באופן נעלה יותר — לכן בכחו אז להגיע גם למעלה משרש הנבראים¹⁸.\nיתירה מזו: לא זו בלבד שע״י מצות מילה נתעלה בעבודתו לדרגא שהיא נעלית באין ערוך לגבי מד־ ריגתו הקודמת, אלא עוד זאת, שע״י מצוה זו נתבטלה מציאותו לגמרי ונת־ אחד עם הבורא התאחדות גמורה כזו שאין כמוה ודוגמתה במצוה אחרת. כי הלא זוהי תכונתה המיוחדת של מצות מילה: „והיתה בריתי בבשר־ כם״¹⁹, היינו שגם בבשר הגשמי נר־ גש ביטולו לה׳, והתאחדותו בו, מה שלא מצינו במצוה אחרת²⁰.\nנמצא שדרגת עבודתו של אברהם קודם שקיים מצות מילה, שהגיע בה רק עד שרש הנבראים, היתה בדוגמת ענין „לבינה״: בכל גודל מעלת עבו־ דתו, אף שעשה חיל ונתעלה בביטולו לה׳ למעלה מעלה, מ״מ לא יצא עדיין מגדר „מעשה ידי אדם״, מ־ תחום הנבראים ושרשם. משא״כ לאחר שנימול, נתעלה בעבודתו לדרגא ש־ היא בדוגמת „אבן״²¹ — מעשה ידי שמים, כי ע״י קיום מצוה זו יצא מגדרו הנ״ל, עד שנתבטל ונתאחד לגמרי עם הבורא — אז עבודתו היא כעין מעשה ידי שמים, ובכוחה ל„ה־ גיע״ למעלה משרש הנבראים.\nובזה יתבאר מה שמובא לעיל, ש־ קודם שנימול הי׳ מדריגתו של א״א רק בבחי׳ „במחזה״ (בלשון) תרגום, כי היא בדוגמת „לבינה״, ש־ בידי אדם כנ״ל; אבל ע״י מצות מילה הגיע לבחי׳ „וירא״, שהוא בל־ ה״ק, בדוגמת האבן שהיא בידי שמים.\nד. ועניין זה, מה שקודם הימולו הגיע אברהם לבחי׳ „במחזה״ ואח״כ לבחי׳ „וירא״, אינו רק מפני שב׳ אופני הגילוי וההפרש ביניהם מת־ אימים לב׳ דרגותיו בעבודה מפאת דוגמתם ל„לבינה״ ו„אבן״, אלא שגם תוכנן הפנימי של ב׳ דרגות אלו",[["","","ניתנה ע״י האפשריות להגיע למעלה משרש הנבראים."],["18","18","להעיר מל״ת להאריז״ל (ר״פ לך) וביאורו באוה״ת פח״ש ד״ה וה׳ ברך — האם המשיך א״א היחוד עליון שעיקרו הי׳ במ״ת."],["19","19","לך יז, יג."],["20","20","וראה שו״ע יו״ד ריש הל׳ מילה (סי׳ ר״ס): „וגדולה מצוה זו משאר מצות עשה״. ואף שהטעם ע״ז הוא „לפי שיש בה צד כרת״ (ש״ך שם) — הרי גם זה שייך להענין הנתבאר בפנים — כי הטעם ע״ז שדוקא במצות מילה ישנו חיוב כרת* י״ל: מכיון שענין מצות מילה הוא ברית הגוף עם הקב״ה, הרי מובן שהעדר קיומה פוגע בברית זו, ובמילא חסר בחיות הגוף. וראה לקו״ש ח״ג ע׳ 834 הערה 23 עוד ביאור בטעם חיוב כרת במילה."],["21","21","ועפ״ז יומתק מה שכשהשביע את אליעזר בהוי׳ א״ל שים נא ידך תחת ירכי — בכדי שתהי׳ השבועה בנקיטת חפץ (ח״ש כד, ב. רש״י שם) כי (רק) המילה הייתה „אבן״, בידי שמים. ועד״ז ס״ת ותפלין (שברש״י שם) לאח״ז. *) ראה בזה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316470230\" data-slug=\"or-hatorah-hb\" data-id=\"8316470230\">אוה״ת שמות (כרך ז׳ ע׳ ב</a>׳תרצז) ביאור למ״ש „בהשמטות זח״א כו׳ מ״מ פסח ומילה כו׳ אית בהו כרת״. ועוד להעיר: להמבואר בכ״מ שבמילה כמה ענינים: שאינו ערל, פעולת המילה, שהוא מהול — ראה ג״כ ד״ה בעצם גו׳ (אוה״ת כרך ד׳ לך, ע׳ 1464)."]]],[1300101060,"בנבואה עולה בקנה אחד עם ב׳ ה־ מדריגות בעבודת אברהם.\nדהנה אמרז״ל²¹* כל הנביאים נת־ נבאו בכה, מוסיף עליהם משה ש־ נתנבא בזה. והחילוק ביניהם מבואר: „זה״ מורה על ראיית המהות, וכ־ מרז״ל²² „מראה באצבעו שנאמר כו׳ זה״, והו״ע שראה באספקלריא המאי־ רה²³; משא״כ בחי׳ „כה״ הוא בחי׳ אספקלריא שאינה מאירה, ואי״ז ראיית המהות.\nועד״ז יובן ההפרש בין גילוי הבא „במחזה״, ובין הגילוי ד„וירא״: וירא ענינה ראי׳ — היינו באופן שרואה את הוי׳ הנראה אליו, ראיית המהות. משא״כ „במחזה״, אף שגם חזיון ענ־ ינו ראי׳, אבל אי״ז ראיית המהות כ״א תרגומו, כמו שהאלקות נראה ע״י התלבשות בלבוש המעלים על מהותו (וכנ״ל ש„מחזה״ הוא בלשון תרגום, היינו שלשון הקודש (אלקות) תורגמה (מובנת ע״י שנתלבשה) בלשונות אח־ רות)²³*.\nלכן קודם שנימול, כשלא הגיע אב־ רהם אבינו עדיין לברית עולם בבשר־ כם — עם אלקות — במילא לא זכה ג״כ לראיית המהות והעצם דאלקות, והיינו שראה רק בחי׳ „מחזה״; משא״כ לאחרי זה, שאז נתבטל מציאותו לגמ־ רי ונתאחד ביחוד שלם²⁴ — נתעלה אז למדריגה נעלית שהוי׳ נראה אליו בבחי׳ „וירא״²⁵, ראיית העצם ד־ אלקות²⁶.\nה. מעלה גבוהה זו של ראיית ה־ מהות, שאלי׳ מגיעים ע״י ברית מילה, אפשרית רק בבנ״י, כי להם דוקא ניתן הכח להתעלות לדרגא זו ע״י העבודה דתורה ומצות בכלל, ומצות מילה בפרט. אשר לכן להם דוקא ניתנה התורה, למרות טענת המלאכים „תנה הודך על השמים״²⁷ — כי דוקא משום ש„יצר הרע יש בכם״ וירידתם ל„מצרים״, למצרים וגבולים, שכ״ז מתברר ומזדכך ומתעלה ע״י עבודתם בתורה ומצות, לכן ביכלתם לעלות ולהגיע למדריגה הנ״ל.\nמשא״כ המלאכים, אף שיש להם ביטול גמור לה׳, ועבודתם היא ב־ דרגא נעלית וכו׳, מ״מ אין בכוחם לעלות למעלה משרש הנבראים²⁸.",[["25","25","ויומתק ע״פ המבואר לעיל ע׳ 46 שבמצות מילה מתבטא ביותר מה ש־ „נתאוה הקב״ה להיות לו דירה בתחתונים״ — והרי ענין התאוה והתענוג שייך לעצם הנפש (ראה המשך תרס״ו ע׳ כה ואילך)."],["26","26","ולהעיר מפרש״י (לך שם) שע״י המילה ניתן לאברהם (השליטה על) ה׳ אברים, ובתוכם על ב׳ עיניו — מתאים עם הנ״ל שע״י המילה נתעלה בדרגת הראי׳ באלקות."],["27","27","ראה שבת פח, ב."],["28","28","וכידוע (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380960\" data-slug=\"likkutei-torah\" data-id=\"4001380960\">לקו״ת ר״ה ס, ב</a>. סידור קנב, א. ובכ״מ) הפירוש באמרז״ל (סנה׳ לח, ב. יומא כא, ב) „הושיט (הקב״ה) אצבעו קטנה ביניהן ושרפן״, שע״י שנת־ גלה להם מבחי׳ המלכות — אף שהיא ספי׳ היותר אחרונה „אצבעו קטנה״ — אבל היא יותר מחוק הקצוב להם — „ושרפן״, נתבטלו ממציאותם. ועפ״ז מובנת השייכות של „הושיט . . ושרפן״ לטענתם „מה אנוש כי תזכרנו״ 21*) ספרי ר״פ מטות (הובא בפירש״י שם)."],["22","22","סוף תענית. וראה פירש״י (בשלח טו, ב)."],["23","23","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370348\" data-slug=\"torah-or\" data-id=\"3901370348\">ראה יבמות מט, ב</a>. ויק״ר פ״א, יד. 23*) וראה תו״א משפטים עח, ג."],["24","24","נתקיים הציווי והי׳ תמים (לך יז, א). וראה נדרים לא, ב: לא נקרא שלם עד שמל שנא׳ התהלך לפני והי׳ תמים."]]],[1300101061,"ועפ״ז יש לבאר הטעם שהגילוי באופן ד„וירא״ לאברהם לא הי׳ יכול לבוא לפני קיומו מצות מילה מצד טענת המלאכים:\nאין הכוונה בזה שחשש קטרוג של המלאכים היתה סיבה צדדית שעיכבה הגילוי הזה, אלא שקטרוג המלאכים עצמו הוא המכריע שאין אברהם (עדיין) ראוי לזה: מאחר שקודם הימולו, על אף כל עבודתו ועילויו בקודש והת־ בטלותו לאלקות וכו׳, לא יצא מגדר נברא — א״כ דרגתו היא בדוגמת דרגת המלאכים, שאינו יכול להגיע למעלה משרש הנבראים²⁹, וכמוהם א״א לו לקבל גילוי אלקות זה שהוא בבחי׳ „וירא״.\nו. עפ״י כל הנ״ל יובן מה שב׳ הפרשיות חלוקות, ומה שאחת נק׳ בשם „לך לך״, והשנית בשם „וירא״, ואיך שבזה מרומז ב׳ הדרגות של א״א הנ״ל:\n„לך לך״ ענינו שהוא הולך ויוצא מגדרו הקדום, ובכל הפרטים ואופנים, כמפורש בכתוב „מארצך וממולדתך ומבית אביך״, שכוללים כל הפרטים בענין היציאה מההגבלות ועליותיו למעלה בדרגת ביטולו לה׳³⁰, אמנם כל המדריגות כולן הן עדיין בחי׳ „הליכה״ מסודרת מלמטה למעלה (וכמפורט בכתוב ש„מארצך וממולדתך וגו׳״ היא לך־לך לשרשך³¹ כו׳ הליכה ועלי׳ שאינה למעלה מכל גדרו הוא) — שלא הגיע אז לפני הימולו, למעלה משרש הנבראים.\nמשא״כ „וירא״, שהוא מורה, כנ״ל, על ראיית המהות דאלקות, הבאה ע״י התאחדותו עם הבורא ביחוד שלם, ולמעלתו זו הגיע ע״י שקיים מצות מילה.\nז. „מעשה אבות סימן לבנים״³² — הרי מובן שישנה הוראה בכל הנ״ל לכל או״א [ובפרט כשהמדובר אודות ענין מילה שע״ז כותב ה־ רמב״ם³³ שכאו״א „נמול כמו שמל אאע״ה״]:\nכמו אברהם, שבכל הליכותיו ועליו־ תיו עדיין לא הגיע לשלימות העבודה,",[["","","— כי זה גופא תשובה על טענתם: במל־ אכים, כשנתגלה להם יותר מחוק הקצוב, אף שהגילוי הוא רק „אצבעו קטנה״ נת־ בטלו ממציאותם (ראה ד״ה והוא עומד תרס״ג ע׳ 9 (וראה גם סידור שם) שפירוש „ושרפן״ הוא שנתבטל מציאותם לגמרי, והוא כעין הפסד המציאות); משא״כ בנש״י, לא רק שאינם מתבטלים מגילוי בחי׳ „אצבעו קטנה״, בחי׳ המל׳ שרש הנבראים, אלא שביכולתם להמשיך ולקבל גם בחי׳ שלמעלה משרש הנבראים. והביטול שנעשה בהם מצד גילוי בחי׳ זו היא באופן שהם עצמם (גם כשהם במציאותם) הם כלים להביטול (עיין ד״ה והוא עומד שם ע׳ 9 ואילך)."],["29","29","ולשון הקטרוג שאינו מהול — כי ע״י המילה נעשה התהלך לפני — הדבק בעבודתי ועומד על עמדו כשרוה״ק נצבת עליו (רש״י לך יז, א־ג). וראה רמב״ם הל׳ יסוה״ת פ״ז ה״ו במעלות נבואת מרע״ה שהי׳ לא ע״י מלאך כו׳ פנים אל פנים כו׳ עומד על עומדו שלם. ועד״ז בפיה״מ שלו הקדמה לפ׳ חלק יסוד ז׳. מו״נ ח״ב פל״ה, לט. ועייג״כ זח״א קע, סע״ב."],["30","30","ראה ד״ה אמרת תרצ״ה פ״ד. מי העיר תש״ג בסופו. ועי׳ ג״כ ד״ה לך דשנות תרנ״ה, תרס״ו, תרס״ז, תש״ב ותש״ה."],["31","31","וכמשנ״ת בענין „קומי לך וגו׳ לכי לך״ (שהש״ר ב, יג) בלקו״ת שה״ש ד״ה יונתי בחגוי הסלע (סז, ג ואילך). <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490025\" data-slug=\"or-hatorah-hb\" data-id=\"8316490025\">אוה״ת</a> ד״ה לך לך (ע׳ תרפב)."],["32","32","נסמן לעיל ע׳ 44 הערה 4."],["33","33","פיה״מ חולין ספ״ז. וראה לעיל בשיחה ב׳ לפ׳ לך."]]],[1300101062,"עד שקיים מצות מילה ואז ניתן לו מלמעלה הגילוי באופן ד„וירא״, עד״ז צריך כאו״א לידע³⁴ שאין להסתפק בעבודתו גם אם היא באופן היותר נעלה, כ״א צריך לעלות תמיד מעלה מעלה עד שיגיע לביטול אמיתי ושלם: כי גם כשמגיע לדרגת ראי׳ באלקות, הרי אפ״ל שזה רק בחי׳ „במחזה״, ואין זה תכלית השלימות עדיין, ולכן צריך להוסיף תמיד בעבודתו.\nולאידך גיסא — ישנה ההבטחה שכשיעבוד עד מקום שידו מגעת, יתנו לו מלמעלה גם הגילויים הנעלים, עד לתכלית השלימות — „וירא״ ראי׳ באלקות, אספקלריא ה־ מאירה³⁵.\n(משיחת ש״פ וירא, תש״ל)",[["34","34","וכמו שאברהם ידע שעדיין לא הגיע לשלימות העבודה, ולכן אמר הצ״צ (היום יום ע׳ קג. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011023\" data-slug=\"likkutei-sichot\" data-id=\"1300011023\">לקו״ש ח״א ע׳ 23</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051098\" data-slug=\"likkutei-sichot\" data-id=\"1300051098\">ח״ה ע׳ 86</a> ואילך) לכ״ק אדמו״ר (מהורש״ב) נ״ע (ולהעיר שיום ההולדת שלו חל בפ׳ וירא): „כשיהודי בן צ״ט שנה מחליט שצריך למול א״ע ראוי הוא שיתגלה לו ה׳״."],["35","35","דאף דרק מרע״ה ראה באספקלר״מ — דוגמת חילוק דאספקלר״מ ושאינה מאירה בנבואה ישנו גם בעבודה והפעולה באדם שעי״ז: תורה או תפלה, יחו״ע או יחו״ת וכו׳ (ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381242\" data-slug=\"likkutei-torah\" data-id=\"4001381242\">לקו״ת שה״ש כח, ב</a>. וש״נ. אוה״ת במדבר קלא. שם ר״פ מטות. ובכ״מ)."]]],[1300101063,"א. עה\"פ¹ „ויגש אברהם ויאמר האף תספה גו'\" מפרש רש\"י: „ויגש אברהם — מצינו הגשה למלחמה ויגש יואב וגו'², הגשה לפיוס ויגש אליו יהודה³, הגשה לתפלה ויגש אליהו הנביא⁴, ולכל אלה נכנס אברהם לדבר קשות ולפיוס ולתפלה\".\nוהנה לכאורה כוונת רש\"י: מכיון שמצינו בכתובים שלאח\"ז ש- אברהם אבינו דיבר קשות („האף תספה צדיק עם רשע\") ודברי פיוס („חלילה לך מעשות כדבר הזה\"⁵, וכפרש\"י: „חולין הוא לך\"⁶), והתפלל („הנה נא הואלתי לדבר גו' ואנכי עפר ואפר אולי יחסרון גו'\"⁷), לכן מפרש דכ\"ז\nנכלל במה שאמר קרא „ויגש\" כי מצינו הגשה כו'.\nוצלה\"ב:\nא) תיבה הרגילה בתנ\"ך ופשוטה „ויגש\" — למה בכלל זקוקה לפירוש? וברוב המקומות לא נמצא פרש\"י לתי- בה זו.\nב) למה מעתיק רש\"י (גם) תיבת „אברהם\"?\nג) מהו ההוספה והחידוש בסיום פירושו של רש\"י „ולכל אלה נכנס אברהם\" — הרי דבר זה מובן מפש- טות משמעות הכתובים, כנ\"ל?\nד) רש\"י מקדים הוכחה דלכל אלה נכנס כו' מזה ש„מצינו הגשה למל- חמה כו' לפיוס כו' לתפלה כו'\", והלא מפורש כן בהכתובים עצמם דלהלן על אתר, כנ\"ל. והו\"ל להתחיל מיד: „לג' דברים נכנס אברהם לדבר קשות ולפיוס ולתפלה\"?\n— ועד\"ז שפירש רש\"י לקמן בפ' וישלח⁸ בנוגע ליעקב אבינו: „התקין עצמו לשלשה דברים לדורון לתפלה ולמלחמה\".\nואף את\"ל שמצד איזה טעם הוצרך",[["1","1","פרשתנו יח, כג."],["2","2","ש\"ב י, יג. מה שרש\"י מוסיף „וגו'\", הוא לתרץ השינוי שבפירושו, שמתחיל „מצינו הגשה למלחמה\" ולא כמו שהוא בפרשתנו — וכמו שמסיים: „לדבר קשות\", ולכן מו- סיף רש\"י „וגו'\" לרמז על סיום הכתוב שם „(והעם אשר עמו) למלחמה\" — אלא שכאן הי' רק „דבר קשות\" דוגמת ענין המלחמה."],["3","3","ר\"פ ויגש."],["4","4","מ\"א יח, לו. מה שרש\"י מוסיף תיבת „הנביא\" הוא לציין שכוונתו לפסוק זה ולא למ\"ש לפנ\"ז (שם, כא) „ויגש אליהו\"."],["5","5","פסוק כה."],["6","6","ברא\"ם, גו\"א, ופי' מהרזו\"ו לב\"ר (מס, ח) פירשו (כל אחד) באו\"א, עיי\"ש — אבל פשטות הענין של דברי פיוס הם דיבורים המדגישים מעלת וגדלות של זה שמפיסים, ולזה מתאים הפסוק המובא ב- פנים."],["7","7","פסוק כז. ראה במקומות שבהערה הקודמת באו\"א — אבל בפשטות מתחילה תפלת אברהם מ„הנה נא הואלתי וגו'\", כבפנים (אבל לא מ„אולי יש חמשים וגו'\" — כבפי' מהרזו\"ו שם, שהרי בפשטות אי\"ז ענין של תפלה, וכמפורש שם תמי' „האף תספה וגו'\" (אלא שמסיים (גם) בדברי פיוס „חלילה לך — חולין הוא לך\" לעשות „כדבר הזה\"); ועוד: לפ\"ז לא הביא רש\"י ב' הענינים (מלחמה פיוס ותפלה) כפי הסדר שאמרם אברהם אבינו, והו\"ל להקדים תפלה לפיוס)."],["8","8","לב, ט."]]],[1300101064,"רש\"י להוכיח ד„ויגש\" שייך בג' דב- רים אלו — הו\"ל להביא ראי' זו כהוספה לבסוף?\nה) ומאידך, סתם רש\"י ולא פירש במקום שהי' לו לכאו' לפרש ולבאר⁹, והיינו להביא את הכתובים שלאח\"ז בנדו\"ד: חלילה לך גו' הנה נא גו' כי משם מוכח שאברהם נכנס „לכל אלה\"?\n— ועד\"ז שמצינו בפירושו בפ' וישלח הנ\"ל, שהוא מפרש: „לדורון — ותעבור המנחה על פניו, לתפלה — אלקי אבי אברהם, למלחמה — והי' המחנה הנשאר לפליטה\".\nו) קושיית השפ\"ח: איך כתב רש\"י כאן ד„ויגש אליו יהודה\" הי' לפיוס, הלא לקמן בר\"פ ויגש כתב רש\"י: „ואל יחר אפך — מכאן אתה למד שדיבר אליו קשות\"¹⁰?\nז) ולאידך גיסא: מכיון שרש\"י מפ- רש כאן שהגשת יהודה היתה לפיוס, מדוע לא פירש כן במקומו בר\"פ וי- גש¹¹ — ובפרט דמצינו דנחית לפרש שם (כנ\"ל) ש„דיבר אליו קשות\"?\nח) מדוע משנה רש\"י מלשון הכתוב „ויגש אברהם\" וכותב „ולכל אלה נכ- נס¹² אברהם\" — והול\"ל „ולכל אלה ניגש אברהם\"?\nב. והביאור בכ\"ז:\nלפני „ויגש אברהם\" נאמר: „ואבר- הם עודנו עומד לפני הוי'\". הרי מפורש שלא זז אברהם ממקומו „לפני הוי'\" — ולפ\"ז אין לפרש „ויגש אברהם\" שלאח\"ז — הגשה כפשוטה¹³, העתקה ממקום למקום¹⁴; אלא ע\"כ צ\"ל ש- מובנה „הגשה\" ותנועה רוחנית — שיצא ממצב ומעמד נפשי מסוים ו„נכ- נס\" למצב חדש¹⁵.\nוזוהי הדגשת רש\"י „ולכל אלה נכנס אברהם\", היינו שעוד קודם שאמר את דבריו לפני הקב\"ה, כבר „נכנס אב-",[["9","9","ובפרט שאין ברור כ\"כ בכתוב כל הג' ענינים — ראה לעיל הערות 6, 7."],["10","10","בש\"ח ומשכיל לדוד כאן גורסים ברש\"י (כבב\"ר שם) „ויגשו בני יהודה (אל יהושע)\" — מיהושע יד, ו. — אבל בדפוס ראשון, שני וכל הדפר- סים שראיתי וברש\"י כת\"י הוא כבפנים. וכ\"ה באגדת בראשית הובא בפי' מהרזו\"ו שם. במשכיל לדוד הקשה „דאילו קרא דויגש אליו יהודה . . איכא נמי התם תפלה ומלחמה ג\"כ שדיבר אליו קשות ומ\"ש דוקטי' לגבי פיוס\", — אבל גם לפי גירסתו („ויגשו בני יהור- דה\") לא יתורץ מדוע לא הביא רש\"י דמצינו הגשה למלחמה ופיוס ותפלה מהכתוב (ה- קודם) „ויגש אליו יהודה\"*? ובפרט ש- *) ואולי י\"ל בכוונת המשכיל לדוד (אלא שלא משמע כן מלשונו) — דכיון ש„איכא נמי התם תפלה ומלחמה\", הרי אין יודעים לאיזה ענין הי' ה„ויגש אליו יהודה\", ולכן אין להוכיח משם כלום. יהודה לא עשה מלחמה ממש (כב„ויגש יואב וגו'\" — ראה לעיל הערה 2), אלא „דיבר קשות\" דוגמת ענין מלחמה — בדיוק כבפרשתנו. ולהביאור בהשיחה — ראה לקמן סוס\"ד."],["11","11","ובפרט שדרש זה (שהגשה היא למלחמה פיוס ותפלה) הובא בב\"ר (צג, ו) גם על הפסוק „ויגש אליו יהודה\"."],["12","12","כ\"ה ברוב הדפוסים. אבל בדפוס ראשון ושני וברש\"י כת\"י הגירסא: „נגש אברהם\"."],["13","13","ראה גם בדבק טוב כאן."],["14","14","גם לא במובנו הרוחני — הגשה לפני ה', שהרי כבר עמד אברהם לפני ה' — משא\"כ בבראשית ד, טז. וראה לקמן הערה 22."],["15","15","ראה אברבנאל כאן. ביאור הרי\"פ לב\"ר (פמ\"ס שם) בשם היפ\"ת. ולהעיר מפי' הרד\"ק כאן."]]],[1300101065,"רהם\" במצב חדש להיות מוכן ומזומן „לדבר קשות ולפיוס ולתפלה\". ולכן שינה מל' הגשה שבכתוב — בכדי לפרש טיבה של הגשה זו.\nומכיון שעיקר כוונתו להדגיש ש- „לכל אלה נכנס אברהם\", היינו, לא לבאר שדיבר — בפועל — קשות ופיוס ותפלה (דמאי קמ\"ל ? !), אלא לחדש שמלכתחלה „נכנס\" בכוונה ומ- טרה של דיבור באופנים אלה — הרי מובן שאין ראי' מהכתובים דלקמן, שכן אין בהם הוכחה ש„נכנס\" בדעה לדבר בכל אופנים אלה (קשות פיוס ותפלה), כ\"א רק מספרים (וזה מובן בפשטות וא\"צ רש\"י לפרשו¹⁶) שככה דיבר בפועל¹⁷.\nג. אמנם, מכיון שכן, שאין ראי' מהכתובים שלפנינו ש„לכל אלה נכ- נס\", א\"כ מהו המקור והראי' לפירושו זה? הלא אפשר דלא „נכנס\" לדבר אלא על אופן אחד — „לדבר קשות\", ומילתא דמסתברא היא¹⁸, כי הרי בסגנון זה התחיל אברהם את דבריו „האף תספה צדיק עם רשע\" (אלא שאח\"כ בהמשך הדיבור הוסיף דברי פיוס ותפלה)¹⁹?\nולכן מעתיק רש\"י את התיבות „וי-\nגש אברהם\" ומפרש: „מצינו הגשה וכו'\" — היינו מכיון שהתורה מוסיפה תיבות אלו (שאין פי' גישה ממקום למקום, ה\"ז) להדגיש ש„נכנס\" מל- כתחלה לדבר באופן מסוים, שלולא תיבות אלו לא היינו יודעים זה, וב- תיבת „ויגש\" (מדאפקי' בלשון זו דו- קא) מובן לאיזה אופן „נכנס לדבר\".\nולזה מתחיל רש\"י פירושו „מצינו הגשה למלחמה וכו' לפיוס וכו' ול- תפלה\", היינו שבכתובים אלה אנו מוצאים שהתורה משתמשת בל' „וי- גש\" לתאר את גישתו והכנת האדם לדבר (או לעשות) הן דברי קשות הן דברי פיוס והן דברי תפלה — ולכן — בנדו\"ד שלדבר קשות („האף תספה) היינו יודעין גם לולא הוספת „ויגש אברהם\" דבזה הרי מתחיל, עכצ\"ל דמרבה שנכנס גם להמשך דיבוריו (דאברהם) בפועל²⁰.\nד. ועפ\"ז יבואר ההפרש בין הפ- סוק דכאן והכתוב „ויגש אליו יהור- דה\":\n„ויגש אליו יהודה\", הרי פירושה של תיבת „ויגש\" הוא במובנה ה- פשוט²¹ — נעתק ממקום עמדו בצור- תא עם אחיו, וניגש והתקרב אל יוסף בכדי לדבר עמו באופן פרטי: „ידבר נא עבדך דבר באזני אדוני\"⁹;\nומה שרש\"י מביא כאן ראי' מזה שהגשת יהודה היתה לפיוס, אין כוו- נתו שדמו אהדדי בתוכנה של תיבת „ויגש\", היינו שגם הגשתו של יהודה ענינה תנועה נפשית (כמו „ויגש אב-",[["16","16","ומה שבפ' וישלח הוצרך רש\"י להביא הפסוקים שיעקב „התקין עצמו לג' דברים לדורון לתפלה ולמלחמה\" (כנ\"ל ס\"א), אף שלכאו' מפורש כן בהכתובים — נתבאר ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151281\" data-slug=\"likkutei-sichot\" data-id=\"1300151281\">לקו\"ש חט\"ו ע' 268</a> ואילך."],["17","17","ועד\"ז המבואר לקמן בפנים (סוס\"ד בנוגע „ויגש אליו יהודה\", שהתחיל בדברי פיוס, ואח\"כ בהמשך דיבורו עבר לדבר קשות."],["18","18","ראה לקמן הערה 24."],["19","19","ובפרט שבב\"ר (שם) פליגי אם לכל אלה נכנס אברהם או רק לא' מהם."],["20","20","משא\"כ שאר ענינים — אף ש- מצינו בהם לשון הגשה — ראה יל\"ש ויגש רמז קא."],["21","21","ראה גם משכיל לדוד כאן."]]],[1300101066,"רהם\"), אלא שהמטרה אחת היא — שניגש והתקרב אל יוסף בכדי לפיסו. ובכ\"ז מצי שפיר להוכיח ש„מצינו הגשה לפיוס\" מ„ויגש אליו יהודה\", מאחר שאנו מוצאים לשון „ויגש\" במטרה לפיוס, כי מאי נפק\"מ אם ההגשה היא באופן גשמי או באופן אחר²².\nולא הוצרך רש\"י לפרש ב„ויגש אליו יהודה\" שהגשתו היתה לפיוס, שהרי דבר זה, שגישתו של יהודה אל יוסף היתה בכוונה לפיסו, מובן הוא בפשטות מראשית דבריו של יהודה — „בי אדוני\"⁹.\nומה שפי' רש\"י שם בד\"ה בפ\"ע: „ואל יחר אפך — מכאן אתה למד שדבר אליו קשות\", אבל לא שמ- לכתחלה ניגש בכוונה זו, ולא פי': ויגש אליו יהודה, שנכנס לפיוס ולד- בר קשות — הוא כי להכנס בבת אחת לפיוס ולקשות חידוש הוא וצ\"ל הוכחה ע\"ז וכבפרשתנו דהוסיפה תורה „ויגש אברהם\".\nה. מהענינים ד„יינה של תורה\" בפירש\"י זה:\nידוע, שמדתו של אברהם היא — אברהם אוהבי²³, ועפ\"ז תמוה: איך יתכן שאברהם ידבר קשות, ובפרט — להקב\"ה?!\nויתירה מזו: מכל הג' דברים (מל- חמה פיוס ותפלה) התחיל אברהם ב- „לדבר קשות\"; שמזה מובן, דאף ש- „לכל אלה נכנס אברהם\", בכ\"ז עיקר הגשתו הי' „לדבר קשות\"²⁴ — ול- כאו' מצד האהבה שלו צריך הי' להתחיל בפיוס ותפלה?\nאולם הביאור בזה:\nזה שאברהם מדתו מדת האהבה והחסד לא בא לתאר (רק) את תכונת מדתו הטבעית, שהי' נוטה לחסד מ- צד הטבע שלו, כ\"א (בעיקר) את זה שעבד את הקב\"ה במדת החסד „לקיים רצון ה'\"²⁵; ובכ\"ז כשבא לידו ענין של הצלת נפשות ושכבר נגזרה גזרה, ועוד יותר, שהקב\"ה כבר שלח ה- מלאכים להפוך את סדום כו', וכמ- ש\"ני²⁶ „המכסה אני מאברהם אשר אני עושה\" ובפרש\"י ריש פרשתנו „אחד להפוך את סדום\" ואין דרך אלא לתבוע מהקב\"ה ו„לדבר קשות\" בכדי' לבטל גזרה זו²⁷ — לא עשה",[["22","22","בביאור הרי\"פ שבהערה 15 ש- „דקאמרינן בויגש יואב היינו שנתעוררו כלב אמיץ להמלחמה דאי שקרבו עצמם לארם הרי היו כבר בינהם וכן ויגשו אל יהושע וכן ויגש אליהו\", — אבל מהמשך הכתוב „ויגש יואב והעם אשר עמו למלחמה בארם (ולכן) וינסו מפניו\" מוכח שהפירוש של „ויגש\" שם הוא כפשוטו — שקרבו עצמם לארם ולכן „וינסו מפניו\". ועד\"ז יש לפרש הכתוב „ויגש אליהו\" שניגש ונקרב אליהו „אל ה' להתפלל\" (מצו\"ד שם) — ראה לעיל הערה 14, ולא (רק) הגשה בנפש „שנתעורר בלב' להתפלל. ובכ\"ז מובן מה שרש\"י מוכיח ש„מצינו הגשה למלחמה כו' ולתפלה\" מכתובים אלה, כמבואר בפנים."],["23","23","ישעי' מא, ח. סוטה לא, א. פרש\"י כאן יח, יז."],["24","24","כ\"ה גם ע\"ד הפשט, וכדלקמן ב- פנים דמכיון שכבר הי' אחרי הגזרה והת- חלת העשי' לכן הוצרך אברהם להתחיל „לדבר קשות\". והשאלה בפנים היא ב„יינה של תורה\" שבפרש\"י, דעדיין צריך ביאור, איך מתאימה הנהגה זו עם מדת החסד של אברהם?"],["25","25","ד\"ה למען דעת תר\"ץ ס\"ה."],["26","26","פרשתנו יח, יז."],["27","27","ראה ד\"ה אשר ברא תרפ\"ט: „הע-"]]],[1300101067,"אברהם אבינו שום „חשבונות\", ונכנס תיכף בכל תוקף במדה הדרושה באו- תה שעה אף שהיא היפך טבעו²⁸ („לדבר קשות\" אפי' כלפי הקב\"ה) אולי יציל אנשי סדום ועמורה.\nוהובא כ\"ז בתורה — הוראה לכאו\"א מבני אברהם:\nכשבא לאדם ענין הנוגע להצלת נפש מישראל בגשמיות, או ברוחניות — לקרב לבם של ישראל לאביהם שבשמים — אסור לו לחשוב „חשבו- נות\" וכו', אלא צריך להתעסק בזה בכל כחו וגם באופן שהוא היפך טבעו\n— אף „לדבר קשות\", ולהשתדל בכל האמצעים האפשריים — למלחמה לפ- יוס ולתפלה²⁹.\nואם יטען הטוען, הרי המעשה הוא העיקר³⁰, ודי במה שמצילים הנפש בפועל, ומה איכפת אם ההתעסקות אינה בחיות ובתוקף רב?\nלזה מדייק רש\"י: „ולכל אלה נכ- נס אברהם\", שצריכים להכניס את עצמו בהתעסקות זו בכל מהותו ועצ- מותו, ואזי מובטח לו שיצליח בע- בודתו.\n(משיחת ש\"פ וירא, תש\"ל)",[["","","מיד עצמו בסכנה להתפלל על אנשי סדום ועמורה\" — עיי\"ש בארוכה."],["28","28","ראה בד\"ה למען דעת שם ובקונ- טרס ומעין (מ\"א פ\"ב) דעשיית חסדו דא\"א היתה רק כדי לפרסם אלקותו ית' בעולם, ולכן כשלא רצו האורחים לברך מעצמם, הכריחם בתוקף וגבורה."],["29","29","ראה גו\"א כאן שהג' דברים (מל- חמה פיוס ותפלה) הם כנגד הג' מדות חסד דין רחמים."],["30","30","אבות פ\"א מי\"ז."]]],[1300101068,"<h3>חיי שרה</h3>\nא. עה״פ¹ ויתן לי את מערת ה־מכפלה גו׳ בכסף מלא יתננה לי פירש״י: ״בכסף מלא אשלם² כל שווי׳״ וכן³ דוד אמר לארונה בכסף מלא״⁴.\nוצריך להבין:\nא) מה מדגיש רש״י בפי׳ ״בכסף מלא כל שווי׳״, דלכאורה הרי זהו מובנו הפשוט בכתוב?\nב) מהי הראי׳ מ״כסף מלא״ שב־ד״ה, מאחר שהיא אותה הלשון ממש הנאמרה בכתוב שלפנינו⁵.\nב. והנה לכאורה הי׳ אפשר לבאר כוונת רש״י להביא ראי׳ ו״חבר״⁶: דקשה לי׳ הלשון ״מלא״ בשייכות ל״כסף״ — דלכאורה אין הל׳ ״מלא״ מתאמת אלא בדבר שיצוייר בו היפור־כה — רק, וכמו בכלי: ותמלא כדה⁷ הבור רק⁸; אבל בכסף מתאים ה־ביטוי ״חסר — שלם״⁹, או רב — מעט וכדומה, ולא הלשון מלא¹⁰ — ולזה אומר רש״י שמצא לו חבר ״וכן דוד אמר לארונה בכסף מלא״, והיינו להוכיח שדרך המקרא לומר גם ב־״כסף״ ל׳ ״מלא״ תמורת ל׳ ״שלם״ (המתאימה יותר) וכיו״ב.\nאבל לפ״ז אינו מובן: א) הול״ל ״וכן בדוד״ וכמו ״וכן ביונה״¹¹ וב־כ״מ. ב) מכיון שכל כוונתו של רש״י, לפי ביאור זה, להודיע שיש חבר ללשון ״כסף מלא״ ואין כוונת רש״י להודיע פירוש ״כסף מלא״, כי מובן הוא — א״כ הול״ל רק להביא¹² את הראי׳ ״וכן דוד אמר לארונה בכסף מלא״ ולהשמיט הפירוש ״אשלם כל שווי׳״?\nג. עוד יש להקשות בפירוש רש״י שלפנינו:\nג) מכיון שרש״י מעתיק ומפרש התיבות ״בכסף מלא״, הול״ל ״כל שווי׳״, ומהי ההוספה ״אשלם (כל שווי׳)״?\nד) מהי האריכות בראייתו ״וכן דוד אמר לארונה״ — הול״ל (כמו בכ״מ) ״וכן בדוד בכסף מלא״.\nד. והביאור בכ״ז:\nבהשקפה ראשונה ״בכסף מלא״, מש־",[["1","1","פרשתנו כג, ט."],["2","2","בדפוס ראשון (שנת רל״ה) של רש״י: שלם כל שוי׳. אבל ברוב הדפוסים הוא אשלם כבפנים. וכן הובא ברא״ם ובגו״א."],["3","3","בדפוס ראשון ליתא הראי׳ מד״ה."],["4","4","דה״א א כא, כב־כה."],["5","5","ואין לומר שהכוונה ב״וכן דוד אמר לארונה בכסף מלא״ היא [לא להביא ראי׳ לפירושו כאן אלא] לומר שגם שם הפי׳ כל שווי׳, שהרי אין דרכו של רש״י לפרש מקודם דבר הנאמר אח״כ שה״בן חמש למקרא״ לא למדו עדיין."],["6","6","ראה רא״ם ובאר מים חיים עה״פ."],["7","7","פרשתנו כד, טז."],["8","8","וישב לז, כד."],["9","9","וכן משמע מהגירסא שבדפוס ראשון שלם. אבל גם לפי״ז אינו מובן למה צריך לפרש (גם) ״כל שווי׳״."],["10","10","אבל ראה מנחות פח, א: מלאים שלא יחסר. ראב״ע עה״פ."],["11","11","רש״י וירא כב, ב."],["12","12","וע״ד פרש״י ויצא (כח, יא): ״ויפ־גע. וכמו ופגע ביריחו גו׳״ שמכיון שפי׳ הפשוט של ויפגע מובן, ורק שקשה איך מתאים ל׳ ״ויפגע (על) במקום״ אין רש״י מפרש, ורק מביא דוגמא ו״חבר״, ״כמו ופגע כו׳״ (ראה לבוש האורה וש״ח שם)."]]],[1300101069,"מע ש״מלא״ קאי על הכסף, היינו שאברהם מודיע בזה שמטבעות הכסף יהיו מלאים (מבלי חסרון) במשקלם¹³ (או ע״ד פי׳ הירושלמי¹⁴ בכסף מלא — ״קינטרין״, וכפרש״י¹⁵ שעפרון לקח מאברהם שקלים גדולים).\nופי׳ זה בא רש״י לשלול בדבריו: ״אשלם כל שווי׳״, שתיבת ״מלא״ אינה תיאור בשייכות לכסף עצמו (כמותו, משקלו), אלא בנוגע לשדה ומחירה ה״מלא״ — אברהם אמר: ״בכסף מלא״ היינו ״אשלם כל שווי׳״ של השדה¹⁶ (שהכסף הוא בסכום כזה שימלא את מחירה — ישלם ״כל שווי׳״ — של השדה)¹⁷.\nומכריחו לפרש כן:\nמהמשך הכתובים מובן, שבבקש־תו זו של אברהם ״לבני חת״ — ״ויתן לי את מערת המכפלה גו׳ בכסף מלא יתננה לי״ — הוא בא לשלול את מה שאמרו לו בני חת לפני זה: ״נשיא אלקים אתה בתוכינו במבחר קברינו קבור גו׳ לא יכלה ממך גו׳״¹⁸ היינו שיקח מהם את מערת המכפלה מבלי שישלם מחירה, כ״א חינם; וע״ז באה תשובתו של אברהם שאינו מסכים לזה, אלא ״בכסף מלא״ ישלם ״כל שווי׳״.\nאבל את״ל שפי׳ ״כסף מלא״ — ״שקלים גדולים״ וכיו״ב, הרי מענתו של אברהם (בצורתן של השקלים) אינה מעין טענתם של בני חת (באופן של נתינת השדה), כי רק לאח״ז שאברהם הי׳ עונה בנוגע לאופן הנתינה (שתהי׳ לא במתנה) הי׳ מתאים דיבורו בענין הכסף עצמו.\nוזהו טעמו של רש״י שלא הסתפק בתיבות ״כל שווי׳״ אלא הוסיף תיבת ״אשלם״¹⁹ — היפך מתנת חינם — כי בזה מבואר ההכרח לפירושו.\nה. אבל מ״מ עדיין אפשר לדחוק ולפרש ש״מלא״ קאי על ה״כסף״. ואף שלפ״ז אין דבורו של אברהם מכוון לדבריהם של בני חת — שהרי אין בדבריו שלילה מפורשת למתנת חינם",[["13","13","כפי׳ הרד״ק עה״פ."],["14","14","קידושין פ״א ה״ג."],["15","15","כג, טז."],["16","16","ועפ״ז יובן גם לפי הגירסא שב־דפוס ראשון (ראה לעיל הערה 2) מה שהוצרך רש״י להוסיף ״כל שווי׳״, כי באם הי׳ כותב רק ״שלם״ הי׳ אפשר לפרש ש״מלא״ קאי על הכסף — שיהיו מטבעות שלמות וכדומה. ולכן מוסיף שאין הכוונה על הכסף, אלא ״כל שווי׳״ (של השדה)."],["17","17","ולכן מפרש רש״י אח״כ עה״פ וישקול אברהם לעפרן ״חסר וי״ו, לפי שאמר הרבה ואפי׳ מעט לא עשה שנטל ממנו שקלים גדולים קנטרין שנא׳ עובר לסוחר״, כי אברהם אמר רק שישלם כל שווי׳ כו׳ ולא שקלים גדולים כו׳. (וכן הוא בב״מ (פז, א) רשעים אומרים הרבה כו׳ ויליף דעפרון שקל קנטרין מעובר לסוחר. וגם בבכורות (ג, א) שהובא אותה המימרא דר׳ חנינא ״כל כסף האמור בתורה כו׳ חוץ משקלי עפרון כו׳״ המובא בירושלמי (קידושין שם) הנה הלימוד דהוי קנטרין הוא מעובר לסוחר ולא מ״בכסף מלא״ כבירושלמי)."],["18","18","שבזה שני ענינים: א) ״במבחר קברינו קבור גו׳״ — שיקבור את שרה בכל מקום שירצה. ב) ״איש ממנו גו׳ לא יכלה גו׳״ — שיטלנו בחנם (ראה פי׳ הרשב״ם: ואין אתה צריך לקנות). וע״ז אמר אברהם (א) ויתן לי את מערת ה־מכפלה (דוקא), (ב) בכסף מלא יתננה לי. ועפ״ז יומתק מה שאחרי ״בכסף מלא״ אמר עוה״פ ״יתננה לי״, דלכאו׳ אמר כבר ויתן לי את מערת המכפלה גו׳."],["19","19","לפי הגי׳ שבדפוס ראשון (הובא לעיל הערה 2) י״ל שההוכחה הנ״ל (המובאת בפנים) פשוטה ומובנת מעצמה לבן חמש למקרא, ורש״י אינו צריך לרמוזה."]]],[1300101070,"שהציעו בני חת — מ״מ מקום לדחוק ולומר שבזה שאמר ״בכסף מלא״ שיתן מטבעות שלימות (או) שקלים גדולים, נכלל בדרך ממילא סירובו לקחת את השדה בחינם, כ״א שישלם עבורה.\nולכן, בכדי לשלול לגמרי הקס״ד הנ״ל, מוסיף רש״י ואומר: ״וכן דוד אמר לארונה בכסף מלא״; אין כוונתו של רש״י להביא עוד מקום שנאמר בו הל׳ ״בכסף מלא״, אלא לחזק את פירושו הנ״ל בתיבות ״בכסף מלא״²⁰ (שהוא לשלול ממתנת חינם) ממש״נ בדברי הימים²¹:\nהטעם מדוע רצה דוד לשלם (בעד הגורן) לארונה ״בכסף מלא״ מפורש שם בכתובים: ״כי לא אשא אשר לך לה׳ והעלות עולה חנם״, הרי מוכחא מילתא שמה שאמר ״בכסף מלא״ כוו־נתו שישלם ״כל שווי׳״.\nולכן האריך רש״י בלשונו, ״וכן דוד אמר לארונה״²², להורות על הענין המדובר שם (היינו הטעם שבדבריו של דוד לארונה), כי מזה הוכחתו, כנ״ל.\nו. עוד י״ל במה שנקט רש״י ״וכן דוד אמר לארונה״ (שעפ״ז יומתק מה שדוקא בתיבות אלו מרמז שכוונתו היא על הענין המדובר שם ולא רמזו באופן אחר):\nדהנה מקום לשאול — מאי טעמא דאברהם שרצה לקנות את השדה וה־מערה דוקא ״בכסף מלא״ הלא הי׳ יכול ליטול אותם (בלא תשלומין) ״מן הדין שאמר לו הקב״ה לזרעך אתן את הארץ הזאת״²³? וע״ז ״מ־שיב״ רש״י באמרו שכן מצינו גם אצל דוד, ש״אמר לארונה בכסף מלא״ ומהתם יתבאר להכא:\nדוד המלך כבש את ירושלים מ־ארונה המלך ובמילא זכה בכולה מדין כיבוש²⁴ — ומ״מ כשבא לבנות בה מזבח, לא הסתפק בזכייתו בכיבוש, ואף לא בזה שארונה יתננה לו, אלא שתהי׳ שלו ע״י קנייתו ״בכסף מלא״. והטעם ע״ז אמר דוד: ״כי לא אשא אשר לך²⁵ לה׳ והעלות עולה חנם״.\nכלומר: אם הי׳ דוד לוקח את ה־גורן וכו׳ רק משום שהוא שלו מדין",[["20","20","ראה עד״ז במשכיל לדוד וראה הערה הבאה."],["21","21","במשכיל לדוד דהראי׳ מד״ה היא, ד״אם איתא דכסף מלא אינו ר״ל אלא קנטרין התם אמאי הוצרך לכתוב כסף מלא הא בל״ז פשיטא דקנטרין הן דהא כל כסף דכתובים קנטרין״. אבל בפשוטו של מקרא (שזוהי דרכו של רש״י בפי׳ עה״ת) א״א לפרש כן, דא״כ הול״ל לרש״י להביא ה־כלל דכסף דכתובים קנטרין."],["22","22","ואולי י״ל שלכן כתב רש״י ״וכן דוד אמר לארונה (השם שנק׳ בו בסוף שמואל ב׳) ולא לארנן (השם שנק׳ בד״ה שם נאמר ״בכסף מלא״) שמרמז גם על אותו הסיפור כפי שהוא בשמואל, ששם מפורש (ש״ב כד, כד) שדוד אמר ״לא כי קנה אקנה מאתך במחיר גו׳״."],["23","23","פרש״י פרשתנו כג, ד. ראה פי׳ החזקוני, לבוש האורה וש״ח שם. ומש״כ רש״י ע״ז ״ומ״א״, י״ל שזהו רק בנוגע לפי התיבות ״גר ותושב״, אבל עצם הענין שהי׳ יכול ליטלו מן הדין ס״ל לרש״י גם לפי פשוטו של מקרא, אלא שאי״ז הפי׳ דמה שאמר אברהם גר ותושב. וראה וישלח לה, יב. פרש״י לך טו, יח. פרש״י דברים ג, יג (לענין ארץ עוג). פרש״י ד״ה ואשריהם תשרפון — ע״ז נג, ב. וראה פרשת דרכים דרוש ס."],["24","24","כי גם בפשוטו של מקרא כ״ה, שע״י כיבוש נעשה שלו. ראה פרש״י לך יד, כא. פרש״י חקת כא, כו. וראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051008\" data-slug=\"likkutei-sichot\" data-id=\"1300051008\">לקו״ש ח״ה ע׳ 8</a> ואילך."],["25","25","דלכאורה אין זה נוגע, והול״ל רק שלא יעלה עולה חנם."]]],[1300101071,"כיבוש, אזי אין זה שולל לגמרי²⁶ את שייכותו של ארונה להגורן; ועוד יותר, גם כשיתנו לו ארונה במתנה²⁷ (שנהנן לו גם את שייכותו זו המוע־טת), בכ״ז נשאר הגורן עדיין בבחי׳ ״אשר לך״ שיש לו עוד לארונה איזו אחיזה וזכות בגורן — ״כי לא אשא אשר לך״.\nולכן שילם דוד עבורו ״בכסף מלא״, כל השווי, בכדי לסלק כל זכותו של ארונה מכל וכל, שלא תהי׳ לו שום אחיזה ושייכות למזבח והקרבנות וכו׳.\nועל דרך זה הוא באברהם ש־לא רצה שהמערה שבה יקבור את שרה (ובה יהי׳ קבור גם הוא ושאר האבות והאמהות²⁸), תישאר בה איזו שהיא שייכות לעפרון (באופן ששמו עלי׳ וכיו״ב), ולכן מיאן לקחתה ״מן הדין״ ואף לא במתנת חינם²⁹, כ״א שילם כל שווי׳.\nז. בפירוש רש״י ישנם ענינים מופלאים³⁰ גם הנוגעים לשאר חלקי התורה: ע״י פירושו של רש״י כאן מתיישבת קושיא בחלק ההלכה ש־בתורה:\nהא דקרקע נקנה בכסף נלמד (בגמ־רא³¹) מהכתוב³² ״שדות בכסף יקנו״, ופי׳ בתוס׳³³ ״הא דלא איתי מקרא דכתיב גבי עפרון (היינו שאברהם\nקנה את השדה בכסף מעפרון) משום דדלמא ה״מ מנכרי שכל קנינו בכסף״.\nאבל ע״פ הנ״ל, בביאור דברי רש״י ״אשלם כל שווי׳ כו׳״, מובן בפשטות למה לא ילפינן דין זה מהכתובים שלפנינו (גבי עפרון):\nמלבד זאת, שלא היינו יודעים מיל־פותא זו³⁴ את עיקרו של דין קנין כסף בקרקע — היינו שהוא נקנה בשוה פרוטה אפילו כשהקרקע שוה יותר³⁵ — דהלא אברהם קנה את השדה ״בכסף מלא״, כל שווי׳³⁶;\nהנה נוסף לזה: מה שאברהם נתן את כסף השדה לעפרון לא הי׳ בשביל לקנותה עי״ז³⁷ (שהרי הי׳ יכול ליטול ״מן הדין״ והיתה קנוי׳ לו בלאו הכי³⁸), אלא בכדי שלא תהי׳ לעפרון שום שייכות (אף שאיננה שלו כלל) לשדה. ולכן מובן שא״א ללמוד מכאן קנין כסף בקרקע.",[["26","26","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051013\" data-slug=\"likkutei-sichot\" data-id=\"1300051013\">לקו״ש שם ס״ע 13</a>."],["27","27","ראה ד״ה שם כא, כג: ראה נתתי גו׳."],["28","28","שלכן רצה דוקא את מערת המכ־פלה ״שכפולה בזוגות״, ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051121\" data-slug=\"likkutei-sichot\" data-id=\"1300051121\">לקו״ש ח״ה ע׳ 109</a>."],["29","29","ראה עד״ז ש״ך עה״ת עה״פ."],["30","30","של״ה במס׳ שבועות שלו (קפא, א)."],["31","31","קידושין כו, א."],["32","32","ירמי׳ לב, מד."],["33","33","קידושין שם."],["34","34","ראה עד״ז בספר המקנה קידושין שם."],["35","35","רמב״ם פ״א מהל׳ מכירה ה״ז. טושו״ע חו״מ סי׳ קצ ס״ב. וגם לפי דעת הסמ״ע שם (סק״א), שמה שקונה בכסף הוא מצד דמי שווי׳ הדבר, דנלמד משדה עפרון שהי׳ דמי שווי השדה — הרי א״א ללמוד משדה עפרון פרט זה דגם כשנותן פרוטה קונה בתורת תחלת פרעון, שהרי אברהם שלם ״כל שווי׳״."],["36","36","ראה צפע״נ עה״ת: וקונה בכסף רק בשוה הדבר, וצריך ליתן בב״א, לכך נקט כסף מלא כו׳."],["37","37","להעיר מתוס׳ קידושין ב, ב ד״ה א״נ ובמהרש״א שם."],["38","38","ומ״ש רש״י עה״פ ויקם שדה עפ־רון, תקומה היתה לו היינו בנוגע לרשות. וגם לפי ״פשוטו של מקרא (שכתב רש״י) ויקם השדה גו׳ לאברהם למקנה וגו׳״ הוא בנוגע ״לעיני בני חת בכל באי שער עירו״ היינו הקנאה מצדם (וראה מפרשי רש״י שם) (ועד״ז צ״ל בפירש״י פסוק יח)."]]],[1300101072,"ח. מהענינים ד״יינה של תורה״³⁹ בפירש״י שלפנינו:\nאיתא בזהר⁴⁰ שהמצות צריכות לה־יות לא ב״ריקניא ובמגנא״ (כי אז לא נמשך ע״י המצוה ״רוחא דקוד־שא״) — זהו הסדר בלעו״ז, במצרים וכמ״ש⁴¹ ״אשר נאכל במצרים חנם״ — אלא צריך ״לאשתדלא בי׳ כדקא יאות כפום חילי׳״, ו״באגר שלים״.\nוזהו מה שפרש״י, שאברהם אמר ״אשלם כל שווי׳״, וכן דוד אמר לארו־נה ״בכסף מלא״, ״כי לא אשא גו׳ העלות עולה חנם״; וככה התנהג אברהם במצות גמ״ח⁴², שקיימה באופן של ״לאשתדלא בי׳ . . באגר שלים״⁴³.\nוההוראה מזה בעבודה הרוחנית של כל אחד ואחת מבנ״י, שענינו לברר ולזכך, ע״י עבודתו בתומ״צ, את ה־מקום בו הוא נמצא, שהוא לבדו יהי׳ הבעה״ב שם⁴⁴, דהכוונה היא שיהי׳ ״קנוי״ לו ע״י דיוק בתשלומי ועבודה והשתדלות ולא ״בריקניא וב־מגנא״.\nשלא יאמר בלבו: מכיון שכשרו־נותי טובים בטבעם, והרי התורה נית־נה לי במתנה; וגם נקל לי לקיים את המצות כי הנה״ב והיצה״ר אינם מעלימים כ״כ⁴⁵ — ולכן כל ענין היגיעה ועבודה הוא ממני והלאה!\nע״ז באה ההוראה מאברהם (ודוד) שלא רצו לקנות בחנם גם את חלקם המגיע ושהיו יכולים ליטול בנקל, אלא נתנו עבורו כל שווי׳.\nוהיינו שגם מי שהוא יכול ללמוד תורה ולקיים את המצות בלא עמל ועבודה, בכ״ז⁴⁶ בכדי לברר את חלקו בעולם, שיצא לגמרי מתחת ממשלת הקליפה ויהי׳ דירה לו ית׳ הוא דוקא ע״י השתדלות עבודה ויגיעה.\nועי״ז מגיעים לבחי׳ ״ארבע מאות שקל כסף עובר לסוחר״, ת׳ עלמין (דכסופין) ״דירתי צדיקיא לעלמא דאתי״⁴⁷ — התגלות בחי׳ סוכ״ע⁴⁸ ל״ועמך כולם צדיקים״⁴⁹.\n(משיחות ש״פ חיי שרה, תשכ״ט ותשי״ט)",[["39","39","״היום יום״ ע׳ כד."],["40","40","ח״ב קכח, א."],["41","41","בהעלותך יא, ה. וראה ספרי ורש״י שם."],["42","42","ראה פרש״י פרשתנו כג, יו״ד. פ־רש״י ראה יג, ה."],["43","43","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051092\" data-slug=\"likkutei-sichot\" data-id=\"1300051092\">לקו״ש שם (ע׳ 80</a> ואילך), לענין מצות מילה וכו׳ דאברהם. עיי״ש."],["44","44","יתירה מזו ראה מענה הצ״צ (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300021345\" data-slug=\"likkutei-sichot\" data-id=\"1300021345\">לקו״ש ח״ב ס״ע 621</a>)."],["45","45","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310020\" data-slug=\"tanya\" data-id=\"3401310020\">תניא פט״ו</a>."],["46","46","ונוסף לזה: לא יגעתי ומצאתי אל תאמין (מגילה ו, ב), וראה קונטרס ומעין מט״ז פ״ב. ואין דברי תורה מתקיימין אלא במי שממית עצמו עלי׳ (ברכות סג, ב. וש״נ)."],["47","47","זח״ג קכח, ב."],["48","48","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370114\" data-slug=\"torah-or\" data-id=\"3901370114\">תו״א וישלח כד, ב</a>. תו״ח שם. אוה״ת בראשית קטו, ב ואילך."],["49","49","ישעי׳ ס, כא."]]],[1300101073,"א. בפרשתנו מסופר על המשא ומתן שבין אליעזר ומשפחת רבקה בקשר עם נישואי׳ ליצחק, ובפרש״י בפרשה זו אנו מוצאים כמה ענינים הדורשים ביאור הן בתוכנם והן בהשוואתם זל״ז.\nעה״פ¹ ״ונשאלה את פי׳״ פרש״י: ״מכאן² שאין משיאין את האשה אלא מדעתה״. וצריך להבין:\nא) בהפסוקים שלפנ״ז³ נאמר: ״ויען לבן ובתואל גו׳ הנה רבקה לפניך גו׳ ותהי אשה לבן אדוניך גו׳״ — הרי שכבר הסכימו על השידוך⁴ מקודם — ועפ״ז עכצ״ל לכאורה דמה שאמרו לאח״ז ״נשאלה את פי׳״ אין הכוונה על עצם הדבר (השידוך)⁵, אלא האם תתרצה לילך מיד או שתרצה להתעכב עמהם משך זמן, כדבריהם⁶ — ודלא כפירש״י ששאלתם הי׳ על עצם הנשואין⁷.\nב) עה״פ⁸ ״ויאמר אחי׳ ואמה״ פרש״י: ״ובתואל היכן הי׳⁹ הוא",[["1","1","פרשתנו כד, נז."],["2","2","מה שכותב רש״י ״מכאן שאין משיאין כו׳״ י״ל שכוונתו להדגיש שהלימוד הוא לא מ״והלכה והיתה גו׳״ (ראה הערה 48). — וע״פ פש״מ אין ראי׳ משם — שהרי בא בהמשך ל״ויצאה מביתו״ שהוא גם בע״כ ככתוב לפנ״ז ושלחה מביתו. גם להעיר דשם המדובר בגרושה מן הנישואין שאינה ברשות האב (פרש״י מטות ל, י)."],["3","3","כד, נ-נא."],["4","4","וכדמוכח גם מפרש״י עה״פ (כד, נב) וישתחו ארצה ״שמודים על בשו״ט״ וראה ברא״ם, שרש״י כתבו כאן (ולא על ״ויקד האיש״ שלפנ״ז) כי אין מודים על הבשו״ט עד (שאמרו קח ולך) שהסכימו לגמרי."],["5","5","בעץ יוסף לב״ר (פס׳ יב. וכ״ה במשכיל לדוד): שהשאלה היתה על עצם השידוך, והא דהוצרכו לשאול את פיה עכשיו, הוא מכיון שנעשית יתומה ע״י מיתת בתואל, וכשאחי׳ ואמה משיאים אותה (כי במה שאמר אבי׳ (בתואל) מה׳ יצא הדבר לא קדשה עדיין (דלא הי׳ אלא הסכמה בעלמא) והם צריכים להשיאה עכשיו) צריכים לשאול את פיה, כי אין משיאין את היתומה (בל׳ המדרש) אלא מדעתה. אבל לפרש״י א״א לתרץ כן, כי [נוסף ע״ז שבפשש״מ הי׳ להם דין ב״נ (ראה לקמן הערה 45) ושקו״ט וגם ע״ד ההלכה — אם יש בב״נ הדין דאב מקדש את בתו קטנה בע״כ — ראה בית האוצר מערכת א׳ כלל א אות ב, וראה ג״כ גו״א (פרשתנו כד, נז) הרי] רש״י דייק לכתוב ״אין משיאין את האשה כו׳״ דקאי (גם) על גדולה שהיא ברשות עצמה להתקדש. וראה לקמן סעיף ח. ועוד ועיקר — הרי בן ה׳ למקרא עדיין לא למד כל דינים אלה."],["6","6","וכפי׳ הרשב״ם והספורנו עה״פ."],["7","7","בש״ח כאן כתב: ״דקשה והא לעיל אמר לא נוכל וגו׳ וניכר שמה׳ יצא הדבר״, וע״ז בא הביאור ברש״י דמ״מ הוצרכו לשאול — מכיון דאין משיאין את האשה כו׳, אבל (נוסף על הדוחק, שא״כ איך אמרו לפנ״ז (לפועל) ״הנה רבקה גו׳ קח ולך״, וגם — למה לא שאלוה תיכף, והמתינו עד למחר) — הרי מדברי רש״י (לקמן) ״ואף אם אינכם רוצים״ משמע שהם התנגדו אל הדבר בעת ששאלוה, כדלקמן בפנים."],["8","8","פרשתנו כד, נה."],["9","9","והא דלא הוקשה לו לרש״י ״ובתואל היכן הי׳״ במ״ש לפנ״ז (שם, נג) ״ומגדנות נתן לאחי׳ ולאמה״ — ה״ז מרמז רש״י במה שמעתיק מהכתוב כאן גם תיבת ״ויאמר״ (אף שלכאורה הו״ל להעתיק (בנוגע לקושייתו) רק התיבות ״אחי׳ ואמה״), דמדייק דמכיון שהמדובר הוא על האמירה (בנוגע להשידוך) — הי׳ צריך להזכיר גם את בתואל (וכדלעיל (שם, נ) שכתוב ״ויען לבן ובתואל ויאמרו"]]],[1300101074,"הי׳ רוצה לעכב בא מלאך והמיתו״¹⁰, ומזה משמע, דאחי׳ ואמה לא רצו לעכב; אבל לפירושו כאן משמע שגם בדעתם לא הי׳ עדיין מוסכם (ויתירה מזו: התנגדו לזה) וכפרש״י במענת רבקה: ״אלך¹¹ מעצמי ואף אם אינכם רוצים״¹², שהרגישה שאינם רוצים¹³, ולכן שאלו את רבקה על עצם השידוך.\nג) לאידך צלה״ב:\nמפשטות הכתובים מבואר (כנ״ל) שהסכימו תיכף (ולפועל) על השידוך, וכמו שאמרו ״הנה רבקה גו׳ קח ולך״, ולכאורה לאחרי שלמדנו ש״אין משיאין את האשה אלא מדעתה״, קשה מעיקרא: א) איך החליטו ע״ז מבלי שיבררו דעת רבקה? ב) אמרם ״קח ולך״ שבפש״מ פי׳ תיכף — הרי (כדלקמן) ״נותנין לבתולה יב״ח״?\nב. לעיל בהפסוק⁸ ״תשב הנערה אתנו ימים או עשור״ לאחרי שמפרש רש״י תיבת ״ימים״ שבפסוק, שפירושה שנה, מוסיף טעם לבקשתם: ״שכך נותנין לבתולה זמן י״ב חודש לפרנס את עצמה בתכשיטים״.\nוגם בזה צלה״ב:\nא) פשוט הוא שלבתולה דרוש לה זמן להכנות לנשואי׳, וגם הבן חמש למקרא יודע דבר זה. ומובנת בפשטות בקשת אחי׳ ואמה שרבקה תתעכב עמהם משך זמן — ומה קשה בפשש״מ, שרש״י מתרץ זה ע״י שמבאר הטעם לבקשתם ״שכך נותנין כו׳״. ואם כוונת רש״י לבאר הדיוק די״ב חודש דוקא — א״כ הו״ל לבאר ג״כ למה ״עשור״ דוקא.\nב) לכאורה אפשר לומר בפשוטו ש״מ דזה שבקשו י״ב חודש הוא לפי שכן שיערו שבנדו״ד, היינו לפי מצב ״פרנסתה״ של רבקה — צריכה יב״ח (וע״פ זה גם יתורץ בפשטות דעת אליעזר שתלך תיכף, דלכאורה — במאי פליגי), ומנא לן מן הכתובים ״שכך נותנין לבתולה (סתם)״ דהיינו שהוא מנהג רגיל ומקובל¹⁴ והסתמכו על מנהג זה?",[["","","גו׳״)*, משא״כ בנוגע למגדנות לא קשה הא דלא הזכיר את בתואל, כי מובן ש״מגדנות״ — פירות (לפרש״י (שם), ולא כפי׳ הב׳ שבראב״ע שם שהם בגדים חשובים), ה״ז מתנה קטנה שאינה חשובה ולכן גם אינו ראוי ליתן לבעה״ב עצמו, ולכן לא נתן אלא לאחי׳ ולאמה. וראה עד״ז במשכיל לדוד."],["10","10","בטור הארוך: ולפי הפשט ניחא כי בתואל אמר הנה רבקה לפניך ועל כן אמר אחי׳ ואמה שאינו טוב שתלך מיד כו׳ אבל דוחק הוא, דהרי מפשטות הכתובים משמע שגם לבן אמר (לפנ״ז) הנה רבקה, שהרי פסוק זה בא בהמשך להכתוב שלפניו ויען לבן ובתואל. וראה ג״כ לקמן הערה 17."],["11","11","שם, נח."],["12","12","ברא״ם, באר מים חיים ועוד, כתבו ההכרח לפירושו ממה שאמרה אלך, ולא אמרה הן."],["13","13","בב״ר פ״ס, יב: ״מרמזים בה התלכי״, ובמ״כ (וראה גם עץ יוסף) שם: בלי תימה כדי שתאמר לא אלך. וראה גם ש״ך עה״ת. *) בראב״ע כאן (ובחזקוני כתב על פירוש זה ולפי הפשט): והאב מחורים, ויתכן שלבן הי׳ גדול מאביו בחכמה וכבוד, כי כן מצאנו ויען לבן ובתואל. וע״פ המבואר בפנים ההערה מובן שא״א לרש״י לפרש כן (נוסף על מה שאי״ז מתאים עם פרש״י עה״פ דויען לבן וגו׳. וראה ג״כ לקמן הערה 20) כי אי״ז מספיק לתרץ הקושיא, דמ״מ הרי הי׳ בתואל צריך לומר את דעתו לאחרי לבן — כמו בפסוק דויען לבן ובתואל ויאמרו וגו׳״."],["14","14","בגמרא כתובות (נז, ריש ע״ב) הוכיחו מפסוק זה שכ״ה המנהג, אבל מלשון"]]],[1300101075,"ג) ואדרבא: לפי פירושו — אי״מ אמרם תיכף ״או עשור״, דמכיון דבקשתם היא משום ש״כך נותנין לבתולה י״ב חודש״, מהו הטעם לוותר שני חדשים? ואם יש טעם לעשור — מאי קס״ד בתחלה לדרוש ימים? — שגם מזה מוכח שלא הי׳ בזה סדר קבוע, והגבילו הזמן לפי הצורך המשוער (בעין יפה או בצמצום — ע״ד שמצינו בטענת אברהם: חמשים, ארבעים וחמשה גו׳).\nג. והביאור: בפסוק ״ונשאלה את פי׳״ מוכרח רש״י לפרש שהתכוונו לכללות השידוך (ולא האם תרצה לילך מיד — כדמשמע לכאורה מהמשך הכתובים), כיון שבפסוק שלאח״ז מבוארת שאלתם ״התלכי עם האיש הזה״, ולא ״התלכי עתה עם האיש הזה״, וכדומה — היינו ששאלתם היתה על כללות ההליכה — השידוך.\nוהא דמוכח מן הכתובים שלפנ״ז, שהשידוך בכללותו כבר הי׳ מוסכם — עכצ״ל שבינתיים אירע דבר שגרם לשינוי החלטתם להסכמה, ועד כדי כך שרצו לבטל כל הענין. ומה גרם לשינוי זה? מובן זה מפרש״י בפסוקים הנ״ל, וכדלקמן.\nד. בעניית לבן ובתואל לאליעזר אמרו ״מה׳ יצא הדבר לא נוכל דבר אליך גו׳ (ולכן) הנה רבקה לפניך קח ולך . . כאשר דבר ה׳״, ופרש״י: ״לא נוכל דבר אליך — למאן בדבר הזה . . לפי שניכר שמה׳ יצא הדבר לפי דבריך שזימנה לך״.\nוהיינו שמדברי אליעזר נוכחו לדעת ש״מה׳ יצא הדבר״ וא״כ מובן שלא נוכל גו׳, כי סירובם או סירובה של רבקה לא ימנעו את הדבר מלבוא בפועל¹⁵ — ולכן הסכימו תיכף, גם מבלי לשאול את רבקה — אף שבד״כ צריכים לשאול דעת האשה¹⁶.\nה. והנה בהפסוקים שלאח״ז מסופר שבמענה לדברי אליעזר ״שלחוני לאדוני״ אמרו אחי׳ ואמה ״תשב הנערה אתנו ימים או עשור אחר תלך״ (ז. א. שהדבר בכללותו מוסכם, אלא שמבקשים שתתעכב אצלם משך זמן), אולם כאשר חזר אליעזר על דבריו ובלשון ״אל תאחרו אותי . . שלחוני ואלכה לאדוני״, אמרו: ״נקרא לנערה ונשאלה את פי׳״ (וכנ״ל ס״ג שנשאלה על כללות הדבר) — הרי ששינוי החלטתם נגרם ע״י דברי אליעזר האחרונים.\nומבאר רש״י ומפרש שבאמרם ״תשב הנערה אתנו גו׳ ואחר תלך״ טענתם עם היות שהשידוך נגמר וכנ״ל כי אין שייך למאן בזה כיון",[["","","רש״י ״שכך נותנין״ ולא ״לפי שנותנין״ (ע״ד פרש״י לעיל כד, ב) או ״למדנו שנותנין״ (כפרש״י כא, יב) משמע שבפשש״מ — זהו דבר ידוע. בחזקוני כתב: ״ימים י״ב חדשים, כדכתיב (אסתר ב, יב) כדת הנשים י״ב חדש וגו׳״, אבל אין לומר שרש״י סמך ע״ז, שהרי לא ציין לכתוב זה (שלא למדו התלמיד עדיין). והא דלא הביא רש״י כתוב מפורש וסמך אמנהג — פשוט ע״פ דרכו בפשש״מ — שאין להביא ראי׳ לכל בתולה — ממנהג אחשורוש (ע״ד פי׳ תו״ת כאן)."],["15","15","וכפי׳ הספורנו עה״פ (וראה גם פרש״י שם, נ): ״קח ולך, גם בלתי רשותינו (והטעם — כהמשך הכתוב) כאשר דבר ה׳, שגזר בת פלוני לפלוני, שהרי נתן אות על רצונו בזה״."],["16","16","וכן כתב בגו״א (פרשתנו כד, נז) בתירוץ קושייתו ״דלמה נשא יצחק קטנה, דהא אמרינן אסור לקדש את בתו עד שתגדל כו׳״ — שהוא מכיון ד״מה׳ יצא הדבר ולא שייך כאן כלל שום איסור בדבר, שהקב״ה רצה בזה״. וראה לקמן הערה 33."]]],[1300101076,"ש״מה׳ יצא הדבר״, מ״מ תשב גו׳ כי ״כך נותנין לבתולה זמן י״ב חודש״ — זהו מנהג העולם¹⁷.\nויתירה מזו — מכיון שאליעזר בעת שהציע השידוך לא התנה שבנדו״ד ישתנה מן הרגיל ותלך מיד, הרי בודאי (לדעת לבן כו׳) שגם הוא התכוון (לכתחילה) לשידוך בסדר המקובל ורגיל.\nאך כאשר סירב אליעזר להסכים לסדר הנהוג והוסיף דבר חדש (שאפילו לדברי אליעזר — אין כל ראי׳ מהנסים שאירעו לו *¹⁷ — שמה׳ יצא גם דבר חדש זה) — מובן שזה מטיל ספק בכל¹⁸ דבריו, גם בשטר מתנה שהראה להם¹⁹ וגם בדברי הנפלאות שסיפר (שכדיוק לשון רש״י *¹⁹ ״לפי שניכר כו׳ לפי דבריך״, היינו שרק ממנו ידעו אודותם). וכיון שרק בסבת הנסים החליטו על השידוך מבלי לשאול הסכמתה של רבקה, ואמרו ״הנה רבקה גו׳ קח ולך״ — הרי מוכרחים היו עכשיו לומר ש״נקרא לנערה ונשאלה את פי׳״ על עצם השידוך²⁰ — שהרי אין משיאין את האשה אלא מדעתה.\nו. עפ״ז מובנת כוונת רש״י ב״תשב הנערה אתנו ימים גו׳״ — ״שכך נותנין לבתולה זמן י״ב חודש״, שזהו היסוד לדבריהם, שלא היתה זאת בקשה, אלא טענה: ״תשב הנערה גו׳ (שהרי) כך נותנין כו׳״, כי הוספת דבר חדש ע״י אליעזר גרם שיחזרו מהחלטתם הקודמת, כנ״ל בארוכה.\nז. אמנם, לפי הנ״ל שטענתם ״תשב הנערה אתנו״ היתה כיון ״שכך נותנין לבתולה זמן י״ב חודש״ — מדוע אמרו תיכף ״או עשור״?\nוהביאור:\nטעם הדבר שנותנין לבתולה זמן י״ב חודש מבאר רש״י שהוא ״כדי לפרנס את עצמה בתכשיטים״ — והרי בהפסוקים שלפנ״ז מסופר שלאחר שהסכימו על השידוך הוציא ״העבד כלי כסף וכלי זהב²¹ . . ויתן לרבקה״ *²¹, ומכיון שאליעזר כבר פירנסה",[["17","17","ועפ״ז מובן שא״א לרש״י לפרש לעיל (כד, נה) כפי׳ הטור הארוך שם (הובא לעיל הערה 10), וכן לא כפי׳ החזקוני (שם, נג): ״בתואל . . שמח הי׳ כו׳ לא הי׳ חפץ באיחור כו׳״, כי באם ״תשב גו׳״ הוא סדר הרגיל, אין מסתבר לומר שבתואל אמר להיפך. *17) ומזה ש״ואבא היום — היום יצאתי והיום באתי מכאן שקפצה לו הארץ״ (פרש״י כד, מב), אין שום ראי׳ על דבר חדש זה (ליקח את רבקה מיד), כי בפשוטו י״ל שהוא בכדי להקדים התחלת ההכנות דיב״ח — ובמילא הקדמת לקיחת רבקה ככל האפשרי."],["18","18","להעיר מפרש״י (בראשית ג, ד): כשם כו׳ כך כו׳."],["19","19","פרש״י כד, לו. *19) שם, נ. וראה בראי״ם לפרש״י זה."],["20","20","ואף שהם מצד עצמם לא רצו בכללות השידוך (כמבואר לעיל ס״א, וראה הערה 13) — מ״מ, שאלו את רבקה ולא בטלו השידוך. וי״ל בפשטות, כי מכיון שראו שבתואל רצה לעכב ומת, חששו שאולי זוהי סיבת מיתתו, כי מה׳ יצא הדבר (אבל מכיון שספק הוא, כנ״ל — הוצרכו לשאול את פיה כבכל שידוך רגיל (בעץ יוסף לב״ר (שם): (אבל אי״ז בפשש״מ) ״ואפשר שרמזה להם (רבקה לאחי׳ ולאמה כשאמרה אלך) כי גם המה מוכנים למיתה (כבתואל), ולזה כשמעם עצה טובה שנתנה כו׳ וישלחו את רבקה מרצונם ומדעתה בשמחה״)). ויומתק עפ״ז ג״כ (נוסף על המבואר לעיל בשוה״ג להערה 9, ובהערה 17) מה שרש״י לעיל (כד, נה) בחר הפי׳ שבתואל מת, כי עפ״ז יובן יותר כאן."],["21","21","שהי׳ (לא כהנזם וכו׳ שנתן לה לפנ״ז, כ״א זה הי׳) בשייכות עם ההסכמה (ההכנות) לנשואין וכו׳. *21) שם, נג."]]],[1300101077,"בתכשיטים, הוסיפו לטענתם: ״או עשור״, היינו דאף שבכלל נותנים יב חודש — בנדו״ד י״ל ״או עשור״, כי קצת תכשיטים נתן לה (ומטענתם מובן ששיערו שהתכשיטים שנתן אליעזר (באם²² כוונתו לפרנסה בתכשיטין ולא מתנה סתם — כמו המגדנות) הי׳ בהם כדי שיעור פרנסה של שני חדשים²³), אבל צ״ל ״עשור״ לישב עמהם עשרה חדשים כדי לפרנס עצמה בכל התכשיטים, כנהוג²⁴.\nומ״מ אמר אליעזר שלחוני (גם לדעתם) — שהרי כיון ש״הוי׳ הצליח דרכי״ — אמתי הוא והרי הראה להם שטר מתנה דכל טוב אדוניו (כולל גם תכשיטין דשרה).\nח. והנה דיוק נוסף בפרש״י דילן:\nבפירושו על ״ונשאלה את פי׳״ משנה רש״י מלשון המדרש²⁵ ״אין משיאין את היתומה אלא על פי׳״ וכותב: ״שאין משיאין את האשה אלא מדעתה״, וצלה״ב הטעם, ובפרט, דלכאורה היתה רבקה אז קטנה²⁶.\nוכוונתו של רש״י בזה, שעם היות רבקה רק בת ג׳ שנים, מ״מ היתה כבר גדולה²⁷ (בדעתה):",[["22","22","וכיון שב׳ אפשרויות בפי׳ כוונתו — לכן אמרו ב׳ זמנים: ימים או עשור."],["23","23","ובדרך רמז י״ל, שי״ב חדשים לבתולה הוא מכיון שבכל חודש יש תכשיט מיוחד השייך לאותו הזמן (בכללות יותר: תכשיטים השייכים במיוחד לזמן הקיץ, והשייכים לזמן החורף), וכאן מצינו ב׳ נתינות מאליעזר לרבקה, נתינת הנזם וכו׳ (ואף שלא נתן זה בקשר לנישואין — כדלעיל הערה 21 — הרי בכ״ז היו לה תכשיטין אלה. וק״ל) ונתינת הכלי כסף וכו׳. וי״ל שאלה היו תכשיטים של ב׳ חדשים, ולכן אמרו או עשור, ועד״ז פי׳ ג״כ במשכיל לדוד."],["24","24","וזהו מה שדייק רש״י להוסיף על לשון הגמרא (כתובות נז, א במשנה, נדרים עג, ב, ריש ע״ב) והמדרש (ב״ר פ״ס יב) ״לפרנס עצמה״ ולפרש ״בתכשיטים״ (אף שזהו פשוט הכוונה בהגמרא. ראה פרש״י כתובות שם *). *) ומה שהוצרך רש״י לפרשו שם הוא (בעיקר) מכיון שרוצה לפרש החילוק שבין ״לפרנס את עצמה״ של הבתולה (שהוא ״בתכשיטים״), ו״לפרנס את עצמו״ של הבעל (שהוא ״בצרכי סעודה וחופה״). ולהעיר שבנדרים (שם) שמובא שם (בגמ׳) רק הדין של ״נותנין לבתולה כו׳״, לא פרש״י כלום."],["25","25","ב״ר שם. והרי ״היתומה״ קאי על הקטנה, שהרי בגדולה (שהיא ברשות עצמה) אין חילוק בין יתומה לאשה אחרת. ובילקוט רמז קט: ״אין משיאין את הקטנה אלא על פיה״. וכלי פרש״י הוא במדרש אגדה."],["26","26","כפרש״י (תולדות כה, כ) שהיתה בת ג׳ שנים. אבל לכמה דיעות (ראה דעת זקנים מבעלי התוס׳ שם, תוס׳ יבמות סא, ב — ד״ה וכן. ועוד) היתה אז בת י״ד שנים."],["27","27","וראה בחזקוני (תולדות שם) שהביא בשם פרש״י (פרשתנו): ״אין משיאין את הגדולה כו׳״ (אמנם בחזקוני הוכיח מזה שרבקה היתה בת י״ד). ואין להקשות ע״ז מהלשון ד״אין משיאין״ דמשמעו שאחרים משיאין אותה — וזהו בקטנה (כי בגדולה ה״ה משיאה את עצמה), שהרי מ״מ היתה עוד קטנה בשנים, והמתעסקים בפועל להשיאה הם ראשי המשפחה. יתרה מזה מצינו: ותקח לו אמו אשה (כא, כא) ובנדו״ד בפרש״י (כד, א): מכיון שהי׳ לו בן הי׳ צריך להשיאו אשה — אף שגדולים היו. ועפ״ז מובן (ג״כ) בפשטות שאין להקשות על פרש״י (שרבקה היתה ״גדולה״), שעפ״ז אי״מ מה שבקשו י״ב חדש לפרנס עצמה, שדין זה אינו בגדולה, כמבואר בכתובות שם (וכקושית הפנ״י (ד״ה מנה״מ — כתובות שם, ב) על השיטות (ראה לעיל הערה 26) שרבקה היתה בת י״ד) — כי (נוסף על שמסתימות ל׳ רש״י ״נותנין לבתולה״ — משמע שע״ד פשש״מ לא נחית לחילוק דקטנה וגדולה, הרי) דבר זה אינו"]]],[1300101078,"בפ׳ תולדות עה״פ²⁸ ״ויגדלו הנערים גו׳״ פרש״י ״כל זמן שהיו קטנים לא היו נכרים במעשיהם ואין אדם מדקדק בהם מה טיבם, כיון שנעשו בני י״ג שנה זה פירש לבתי מדרשות וזה פירש כו׳״.\nוהנה מעשיו של אדם מבוגר מוכיחים על תכונות נפשו, ומי שהוא בר דעת ובעל אחריות, הרי מעשיו תוצאה מתכונות נפשו (לטוב או להיפך), אבל אין להוכיח תכונות נפשו של אדם עפ״י מעשיו בקטנותו, כשאינו מבוגר ואינו אחראי על מעשיו.\nועפ״ז יש להבין את האריכות בפרש״י ״כל זמן שהיו קטנים לא היו נכרים במעשיהם ואין אדם מדקדק בהם״²⁹, דלכאורה, למאי נפק״מ הדקדוק בהם — והול״ל בפשטות: דמכיון שנעשו בני י״ג שנה (ובאו לכלל גדלות) ניכר במעשיהם שזה פירש לביהמ״ד וזה כו׳.\nומובן מלשון רש״י, שבאם היו מדקדקים בהם ומכירים מעשיהם קודם שנעשו בני י״ג שנה, אפשר שהיו עומדים על תכונותיהם גם קודם לכן. היינו שבפשש״מ אין ענין קטנות וגדלות תלוי בגיל (י״ג שנה) אלא בטבעו של כל יחיד בפרט — כי יש מתבגר בגיל מוקדם ויש המאחר להתבגר; והגיל י״ג שנה אינו הסיבה לגדלות, אלא כן הוא הטבע ע״פ הרוב — דבן י״ג שנה נעשה גדול בשכל ודעה, ומאז והלאה מדקדקים בו ומכירים במעשיו, משא״כ לפני גיל זה אין מדקדקים בו, מכיון שע״פ הרוב לא נתגדל עוד בשכל ודעה.\nובנדו״ד:\nמסופר בפרשה³⁰ שאליעזר סימן נתן לעצמו ״והי׳ הנערה אשר אמר אלי׳ הטי נא כדך ואשתה ואמרה שתה וגם . . אותה הוכחת לעבדך ליצחק״ וכשראה את רבקה ״וירץ העבד לקראתה ויאמר גו׳״³¹ — הרי שדקדק במעשי׳ של רבקה והכיר אותה ע״י³², ועפ״ז נמצא שהיתה גדולה כבר, שמדקדקים ואפשר להכירה במעשי׳.\nועפ״ז מובן דיוקו של רש״י ש״אין משיאין את האשה כו׳״, שהרי (בפשוטו של מקרא) היתה רבקה כבר גדולה (בדעתה) באותה שעה³³.\nט. ידוע שבפרש״י ישנם ״ענינים מופלאים״³⁴ וגם בהלכה. ובפרש״י דילן:\nבמקור הדין ד״בן שלש עשרה למצות״³⁵ שתי דעות בהלכה: א) למ־",[["","","ענין התלוי בדעת אלא במנין השנים (ראה רש״י ד״ה נותנין ותוד״ה בגרה — כתובות שם)."],["28","28","תולדות כה, כז."],["29","29","ולהעיר שבב״ר (פ׳ ס״ג, י) ועוד, (שבפשטות זהו מקורו של רש״י) — אין לשון זה, ורש״י מוסיפו (והוא ע״ד מ״ש בתנחומא תצא ד)."],["30","30","פרשתנו כד, יד."],["31","31","שם, יז."],["32","32","וראה ג״כ פרש״י (שם, יד): ״ראוי׳ היא לו שתהא גומלת חסדים״."],["33","33","ועפ״ז מובן בפשטות שלפרש״י מלכתחילה אין מקום לקושית הגו״א שבהערה 16. ברא״ם כאן: ״והיינו דאמר כו׳ בפ׳ אע״פ (כתובות נז, ב), אין פוסקין על הקטנה להשיאה כשהיא קטנה כו׳״, ועפ״ז נמצא (לפרש״י) דלא כדבריו דהרי רבקה גדולה היתה."],["34","34","של״ה במס׳ שבועות שלו (קפא, א)."],["35","35","אבות פ״ה מכ״א (ולגירסת אדה״ז בסידורו — מכ״ב). רמב״ם הל׳ שביתת עשור פ״ב הי״א. טושו״ע (אדה״ז) או״ח"]]],[1300101079,"דים³⁶ דבר זה ממ״ש³⁷ ״ויקחו שני בני יעקב שמעון ולוי איש חרבו וגו׳״ — שהיו באותו הזמן בני י״ג שנה³⁸, וקראם הכתוב איש, שמורה על גדלות³⁹. ולפי״ז הוא ענין טבעי שבגיל יג שנה⁴⁰ נעשה גדול בשכל ודעה. ב) שהוא מהשיעורין דהלכה למשה מסיני⁴¹ — ואינו תלוי בטבע.\nונפקא מינא להלכה — מאימתי בני נח מחוייבים בקיום המצות שמצווים עליהן⁴²:\nלהדיעה שי״ג למצות נלמד מהכתוב ומטעם שטבע האדם הוא שבגיל זה נעשה גדול — אז כל ב״נ מחוייב במצות מבן יג שנה ואילך, כי מכיון שהתורה גילתה שבטבע נעשה אז גדול אין נפק״מ בין ישראל לב״נ;\nולהדיעה שזוהי הלכה למשה מסיני א״כ בב״נ שלהם ״לא ניתנו השיעורין״⁴³, הרי״ז תלוי בכאו״א לפי טבעו ומצבו⁴⁴.\nוהנה בפשש״מ⁴⁵ הי׳ להאבות דין ב״נ⁴⁶, ועפ״י הדיעה הב׳ הנ״ל (שי״ל שגם רש״י ס״ל כן⁴⁷) שלפי״ז גדלותם תלוי׳ בכאו״א לפי טבעו הוא — י״ל שדברי רש״י ש״אין משיאין את האשה כו׳״ (היינו שרבקה היתה גדולה) הם גם ע״פ דרך ההלכה⁴⁸.\n(משיחת ש״פ ח״ש, תשל״ג)",[["","","סי׳ תרסו (ס״ב ס״ח). ועוד."],["36","36","רש״י נזיר (כט, ב) ד״ה ור׳ יוסי ברי׳ סבר. רש״י ורע״ב אבות שם."],["37","37","וישלח לד, כה."],["38","38","פסיקתא זוטרתא בראשית שם. ובמקומות שנסמנו בהערה 36 ועוד."],["39","39","כמ״ש (שמות ב, יד) ״מי שמך לאיש״ (וכפרש״י שם — והוא דלא כמ״ש בשמו״ר שם) ״וחזקת והיית לאיש״ (מ״א ב, ב). ועוד."],["40","40","ואשה כשהיא בת יב, דבינה יתירה ניתנה באשה כמבואר בגמרא נדה מה, ב. וראה פירוש המשניות להרמב״ם שם פ״ה מ״ו."],["41","41","שו״ת הרא״ש כלל סז. פי׳ הב׳ שברש״י אבות שם. שו״ת מהרי״ל סי׳ נא. ולפי שיטתם הראי׳ מהכתוב אינה אלא אסמכתא בעלמא."],["42","42","ראה ג״כ <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151434\" data-slug=\"likkutei-sichot\" data-id=\"1300151434\">לקו״ש חי״ה ע׳ 421</a>. חט״ו ע׳ 291."],["43","43","רמב״ם הל׳ מלכים פ״ט ה״י."],["44","44","ראה רמב״ם שם, ושם פ״י ה״ב. שו״ת חת״ס חיו״ד סשי״ז."],["45","45","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051155\" data-slug=\"likkutei-sichot\" data-id=\"1300051155\">לקו״ש ח״ה ע׳ 143</a> ואילך."],["46","46","וראה שקו״ט בזה בפרשת דרכים דרך האתרים דרוש ראשון, בית האוצר בתחלתו. ולהעיר שרש״י בפי׳ על הש״ס (סנה׳ סב, א ד״ה בת יתרו) ס״ל שהי׳ להם (קודם מ״ת) דין ב״נ."],["47","47","בפי׳ עה״ת, וכפי׳ הב׳ באבות שם (ראה לעיל הערה 41), ולהעיר שבפירושו עה״פ ד״ויקחו גו׳ איש גו׳״ לא הביא רש״י דרשת חז״ל שהיו בני יג."],["48","48","ברש״י יבמות (יט, ב ד״ה קדושין דעלמא) מוכיח דקדושין הוי מדעתה מפסוק (תצא כד, ב) ״והלכה והיתה לאיש אחר, מדעתה משמע״. ולכאורה (עפ״י מ״ש בפנים) הו״ל להביא (עכ״פ כסמך לדבר * גם) פסוק דידן, שלדעתו (כאן ובפירושו באבות) מפורש הוא **. אבל י״ל בפשטות, שבפירושו על הש״ס (להלכה) ס״ל כדיעה הא׳ וכדמוכח מזה שבפי׳ בנזיר (ראה לעיל הערה 36) הביא רק דיעה זו. ולפי״ז היתה רבקה קטנה. ועפ״ז מובן ג״כ מ״ש ברש״י על הרי״ף (קדושין רפ״ב) אסור לאדם לקדש את בתו כשהיא קטנה כו׳ וסמך לדבר דכתיב נקרא לנערה ונשאלה את פיה. *) הוכחה (גמורה) אינה, כי י״ל בזה דאין למדין מקודם מ״ת (וראה אנציקלופדי׳ תלמודית בערכו). **) עפ״י מ״ש ברא״ם (עה״פ) ״דהתלכי עם האיש הזה בנשואין קמיירי ולא בקדושין״ (ודלא כמ״ש בעץ יוסף (הובא לעיל הערה 5)) אינה קושי׳ שהרי אין מכאן ראי׳ לקדושין מדעתה. אבל יומתק יותר עפ״י מ״ש בפנים."]]],[1300101080,"<h3>תולדות</h3>\nא. עה״פ ¹ „ויעתק משם ויחפור באר אחרת ולא רבו עלי׳ ויקרא שמה רחובות ויאמר כי עתה הרחיב ה׳ לנו ופרינו בארץ״, מעתיק רש״י: „ופרינו בארץ״ ומפרש: „כתרגומו² וניפוש בארעא״.\nוכתבו המפרשים³ בכוונת רש״י: דלכאורה „ופרינו״ הוא לשון עבר, וכיון שאמר „כי עתה הרחיב ה׳ לנו״, איך יאמר „ופרינו״ — כבר — בארץ״ ? לכן כתב רש״י שפירוש „ופרינו״ כאן הוא „וניפוש״, בעתיד.\nאבל בפשטות אא״פ לומר כן — דהרי מצינו בתורה פעמים הכי רבות⁴ תיבות בלשון עבר והוא״ו שבראשן מהפכתן לעתיד, וא״כ פשוט גם בנ־דו״ד שפי׳ „ופרינו״ (בוא״ו) הוא ש־נפרה בעתיד, ואין כאן קושיא, ואין צורך לרש״י לפרשו (כמו שאינו מפ־רש בשאר המקומות).\nגם צלה״ב: רש״י מפרש תיבת „ופ־רינו״ — ולא תיבת „בארץ״ [כי „בארעא״ המועתק ברש״י — אינו מוסיף ביאור בתיבת „בארץ״], וא״כ למה מעתיק גם תיבת „בארץ״ ?\nב. הביאור בזה:\n„ופרינו״ הוא מלשון „פרי״ ופי׳ הכתוב הוא „ונעשה פירות״. ומכיון שהמדובר הוא ב„לנו״ — בבנ״א, ש־הם יעשו פירות, הכוונה בזה שיפרו בבנים ובנות⁵, ע״ד מ״ש⁶ „פרו ורבו גו׳״.\nלאידך גיסא מובן שנדו״ד אינו דומה להתם:\nבפסוק „פרו ורבו גו׳״ פרש״י: „אם לא אמר אלא פרו הי׳ אחד מוליד אחד ולא יותר, בא ורבו שאחד מו־ליד הרבה״⁷, כלומר שגם על ולד אחד מתאים הלשון „פרו״. אבל בנ־דו״ד ש„ופרינו״ בא בהמשך ל„כי עתה הרחיב ה׳ לנו (וכתוצאה מזה⁸) ופרינו בארץ״, אין מסתבר כלל כי הכוונה היא שאחד מוליד אחד ולא",[["1","1","פרשתנו כו, כב."],["2","2","בכמה דפוסים — „תרגומו כו׳״ (בלא כ״ף). ולהעיר שבדפוס ראשון אין תיבת „כתרגומו״ (וראה לקמן הערה 17), ובדפוס שני חסר כל ד״ה זה."],["3","3","רא״ם, גו״א וש״ח. וראה רע״ב עה״פ."],["4","4","בקאפיטל זה עצמו ראה בפסוקים: ג, ד (ג״פ), כד (ב״פ)."],["5","5","כי זהו בהמשך ל„הרחיב ה׳ לנו״, חיי מנוחה והרחבה — ולכן טבעי שיהי׳ „פרו ורבו״."],["6","6","בראשית א, כב. ובפרש״י שם. וראה רא״ם, גו״א ולבוש האורה שם."],["7","7","שהכוונה בזה (לא ש„פרו״ פירושו שאחד מוליד אחד בפעם א׳ (אבל במשך הזמן מוליד הרבה), ו„רבו״ מוסיף שאחד מוליד כמה בפעם אחת (כבש״ח שם), שהרי אין דיוק זה במשמעות תיבת „רבו״ (ודוחק לומר שההוספה נרמזת רק ביתור תיבת „ורבו״), כ״א) ש„פרו״ פירושו ש„אחד מוליד אחד ולא יותר״ במשך כל ימי חייו ו„רבו״ מוסיף שאחד מוליד (במשך הזמן) הרבה, שעי״ז מתרבה."],["8","8","כי בפשטות פי׳ הכתוב — שכיון שהוי׳ כבר הרחיב לנו (אלא שעבר זה הוא עבר הקרוב — „עתה״), ולכן „ופרינו בארץ״ (משא״כ לפי׳ הרס״ג עה״פ „הרחיב — ירחיב״, אפ״ל שהם ב׳ ענינים נפרדים — אבל גם לפי׳ זה „ירחיב״ „ופרינו״ צ״ל בהתאם זל״ז)."]]],[1300101081,"<h3>תולדות א</h3>\nיותר״, היינו שלא יהי׳ עקר — כי אין זה „הרחיב״ כלל !\nובמילא מובן ש„ופרינו״ כאן הוא בדוגמת מ״ש⁹ „לא אגרשנו מפניך בשנה אחת פן תהי׳ הארץ שממה גו׳ מעט מעט אגרשנו מפניך עד אשר תפרה גו׳״, שפירוש „תפרה״ הוא, שיהיו בארץ הרבה בנ״א. ועד״ז כאן¹⁰ פירוש „ופרינו״ — „שאחד מוליד הרבה״.\nאבל עפ״ז קשה ביותר: הרי לא היו ליצחק ולרבקה רק שני בנים, יעקב ועשו, ואיך נופל ע״ז לשון „ופרינו״ (הבא בהמשך ל„הרחיב״)¹¹ ?\nולכן פרש״י שאין כוונת „ופרינו״ לולדות (כמו „פרו ורבו גו׳״), כ״א „וניפוש״, וכבר כתב רש״י פי׳ תיבה זו עה״פ¹² „שם האחד פישון גו׳״ פרש״י: „וע״ש שמימיו מתברכין ועו־לין ומשקין את הארץ נקרא פישון, כמו¹³ ופשו פרשיו״, היינו שדבר זה עצמו מתרבה ומתגדל. ועד״ז כאן הכוונה שיצחק בעצמו יהי׳ בריבוי וגדלות וכו׳¹⁴, וכמ״ש¹⁵ „ויגדל האיש וילך הלוך וגדול עד כי גדל מאד. ויהי לו מקנה צאן ומקנה בקר וע־בודה רבה גו׳״¹⁶.\nאמנם עפ״ז למה מביאו רש״י בשם התרגום — הו״ל לפרש כן מעצמו מצד הכרח הנ״ל בפשט הכתוב¹⁷ ?\nוהטעם ע״ז: ברוב המקומות שכ־תוב בתורה הלשון „פרו״ וכיו״ב, מפ־רש התרגום „פושו״ וכיו״ב, היינו שלדעת התרגום, גם כשאיירי בהולדת ולדות (— עשיית פירות), יש בזה גם התוכן של „פשיון״ (כי עי״ז מת־רבה גם המוליד עצמו). שמזה מובן — לדעת התרגום — שכשהפי׳ של „ופרינו״ הוא רק ריבוי בעצמו, כב־נדו״ד, אין פי׳ זה יוצא מן הכלל לגבי שאר המקומות, כי בכל מקום כלול תוכן זה בפי׳ התיבה.\nולכן מציין רש״י להתרגום, ללמדנו,",[["9","9","משפטים כג, כט־ל."],["10","10","ואף שענין זה כתוב להלן — אין הכוונה בפנים שהיינו למדים פי׳ זה משם, כ״א לראי׳ ולדוגמא שבלה״ק ג״ז נכלל בפי׳ „פרו״ „ופרינו״, אלא שאינו מוכרח. ולכן ניתוספה תיבת „ורבו״, ובפרשתנו — מובן הוא כיון שבא בהמשך ל„הרחיב״."],["11","11","ואין לומר שהכוונה בזה לדורות הבאים, כמו „לזרעך אתן את הארץ ה־זאת״ (לך יב, ז), „את כל הארץ גו׳ לך אתננה ולזרעך עד עולם, ושמתי את זרעך כעפר הארץ גו׳״ (שם יג, טו־טז) ועוד כו״כ — כי מקדים „כי עתה הרחיב ה׳ לנו״."],["12","12","בראשית ב, יא. ומטעם זה אין רש״י מפרש כלום עה״פ (תזריע יג, ה ועוד) „לא פשה גו׳״, כי כבר פי׳ בבראשית, שהכוונה — שהדבר מתרבה."],["13","13","חבקוק א, ח."],["14","14","וראה פי׳ הרד״ק עה״פ: ונפרה ונרבה במקנה."],["15","15","פרשתנו כו, יג־יד. וראה פרש״י שם: זבל פרדותיו* של יצחק כו׳."],["16","16","ועפ״ז אין הכרח לומר שכוונת הכתוב ב„ופרינו בארץ גו׳״ היא רק לע־תיד, כי ענין זה הי׳ גם בעבר. ומ״ש „עתה הרחיב ה׳ לנו ופרינו גו׳״, ה״ז קאי על החלק של העתיד. ואדרבה: מוכרח לומר שקאי גם על העבר, כי בעתיד לא מצינו זה במפורש בהיותו „בארץ״ (גרר), קודם עלותו לבאר שבע."],["17","17","וי״ל שגם לפי מ״ש בדפוס ה־ראשון (שאין תיבת „כתרגומו״ — ראה הערה 2), מובן שכוונת רש״י להעתיק לשון ה־תרגום, דאל״כ הול״ל „וניפוש בארץ״. *) ולהעיר (בהרמז שבפרש״י) — ש־פרדה אינה מולידה (ב״ר פמ״א, ו. וראה שם, ה. פל״ח, ו), ובמילא לא היו לו פירות מהן, כנ״ל בפנים."]]],[1300101082,"<h3>תולדות א</h3>\nשאין פי׳ זה („וניפוש״) בסוג „ולא מצאתי לו חבר״, כי בכל המקומות יש בו תוכן זה.\nג. אולם לכאורה, כללות פי׳ זה אינו מוכרח: יש לפרש ש„ופרינו״ הכוונה לולדות (פירות), ואעפ״כ מת־אים זה ל„הרחיב ה׳ לנו״, ע״פ מש״כ רש״י כבר בפ׳ וירא¹⁸: „בני בנים הרי הן כבנים״, וא״כ אפ״ל שקאי על בני יעקב¹⁹, שהיו שנים עשר (ודינה²⁰) ?\nלכן מעתיק רש״י בתחלת פירושו „(ופרינו) בארץ״ (ובמילא כותב גם בפירושו — „(וניפוש) בארעא״) — ובני יעקב הרי לא נולדו בארץ (גרר — וגם לא בארץ ישראל בכלל²¹), כ״א בחו״ל, ובמילא לא קאי „ופרינו בארץ״ עליהם.\nעוד יש לדייק בפרש״י זה: למה מעתיק לשון התרגום — הו״ל לכ־תוב „כתרגומו״ ותו לא — כמנהגו במקומות רבים, והלומד יראה בתר־גום פסוק זה ?\nוהביאור: בתרגום כאן שתי גר־סאות: א) ויפשיננא. ב) וניפוש. ומע־תיק רש״י לשון התרגום ללמדנו ש־גירסא הנכונה היא „וניפוש״²² — ואף שאין ענין פירוש רש״י להודיענו גירסת התרגום — כאן ה״ז נפק״מ בפי׳ פשוטו של מקרא: „ויפשיננא״ פירושו שהוא יפיש אותנו, וקאי על „ה׳ ״ המובא לפנ״ז בכתוב, „וניפוש״ פירושו שאנו (מעצמנו) ניפוש²³, וק־אי על יצחק וביתו.\nד. מ„עינה של תורה״ שבפרש״י זה: רש״י מעתיק לשון התרגום „וני־פוש בארעא״ — היינו שבפסוק ישנם ב׳ ענינים: א) „כי עתה הרחיב ה׳ לנו״ — הו״ע הבא מלמעלה. ב) „וני־פוש בארעא״ — הו״ע עבודת האדם. ומרמז רש״י שהתכלית של „הרחיב ה׳ לנו״ היא — „וניפוש בארעא״, שהאדם יעבוד, תכלית כוונת בריאת העולם והאדם²⁴ ע״י הקב״ה („הרחיב ה׳״) היא שהאדם ייגע ויעבוד בזה, וכמ״ש²⁵ „אדם לעמל יולד״. ואופן העבודה הוא: „וניפוש בארעא״, ש־האדם יעבוד עם העולם ועניניו עד שמגיע לדרגא שהאדם כביכול מוסיף („וניפוש״) על הבריאה כפי שהיא נבראה ע״י הקב״ה — היינו שמגלה אלקות (ע״י תומ״צ) גם במקום כזה שמצד הבריאה אין אלקות בגילוי שם²⁶. וכמרז״ל²⁷ „נעשה שותף ל־",[["18","18","כ, יב."],["19","19","ובדוגמת מ״ש (יהושע כד, ג) „וארבה את זרעו ואתן לו את יצחק״."],["20","20","וראה ג״כ פרש״י וישב לז, לה."],["21","21","בנוגע לבנימין, ראה פרש״י וישלח (לה, יח): „נולד בארץ כנען״. אבל ראה פרש״י ויחי (מח, ז) „ולא הולכתי׳ כו׳ להכניס לארץ״. וראה רמב״ן שם. וראה רא״ם, גו״א, וש״ח שם."],["22","22","כמו שפי׳ בש״ת."],["23","23","ומוכרח כן, כי אם גם זה קאי על „ה׳״ הול״ל „כי עתה הרחיב ה׳ לנו והפרה אותנו בארץ״ (אם הכוונה לעבר — ראה לעיל הערה 16) או „כי עתה הרחיב ה׳ לנו ויפרה אותנו בארץ״ (אם הכוונה לעתיד)."],["24","24","וכמ״ש (בראשית ב, טו) „וינ־חהו בג״ע לעבדה ולשמרה״. וראה תיב״ע שם."],["25","25","איוב ה, ז. וראה סנה׳ צט, ב. ד״ה אדם לעמל תרפ״ס."],["26","26","ראה ד״ה גדולים מעשה צדיקים תרפ״ה (ספה״מ קונטרסים ח״ב ע׳ 914 ואילך)."],["27","27","שבת י, א. קיט, ב. טור או״ח סי׳ רסח. שו״ע אדה״ז שם ס״א. וראה או״ת להה״מ בראשית ד״ה כל האומר"]]],[1300101083,"<h3>תולדות א</h3>\nהקב״ה במעשה בראשית״ [ויתרה מזה אחז״ל²⁸ „מה הקב״ה בורא עולמות אף אביכם בורא עולמות״].\nאמנם יש מקום לטעון: איך אפשר הדבר ? מכיון שהקב״ה ברא את ה־עולם, והוא בראו בהגבלות אלו, איך יכול בנ״א או מלאך — נברא — להוסיף בזה ?\nהנה גם זה מרומז תחלה בכתוב: „כי עתה הרחיב ה׳ לנו״, היינו שגם הכח ע״ז שיוכל האדם („לנו״) להר־חיב ולהוסיף בהבריאה, בא מהקב״ה, שהרחיב ונתן לבנ״י כח שלמעלה ממדידות והגבלות, ולכן ביכולתם (ובמילא — תפקידם) לבטל הגבלות העולם ולהרחיבו\nברוחניות ובמילא גם בגשמיות — כי עי״ז מוסיפים ברכה ונתנה הארץ יבולה גו׳, ואה״ק היא כצבי²⁹ שה־מקום הגשמי מתפשט כו׳\nעד ש„וניפוש בארעא״²⁹*.\nה. והנה ענין זה מרומז גם במ״ש³⁰ „אנכי ה״א המעלך מארץ מצרים הרחב פיך ואמלאהו״ — דגם כאן ב׳ ענינים: א) „אנכי ה״א המעלך מארמ״צ״ — הו״ע הבא מלמעלה. ב) „הרחב פיך (ואמלאהו)״ — האדם צריך לעשות — להרחיב את הפה³¹ יותר מכפי",[["","","ויכולו (ג, ג בהוצאת קה״ת תשל״ג). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061022\" data-slug=\"likkutei-sichot\" data-id=\"1300061022\">לקו״ש ח״ו ס״ע 22</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071252\" data-slug=\"likkutei-sichot\" data-id=\"1300071252\">ח״ז ע׳ 240</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300031042\" data-slug=\"likkutei-sichot\" data-id=\"1300031042\">ח״ג ע׳ 42</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041162\" data-slug=\"likkutei-sichot\" data-id=\"1300041162\">ח״ד ע׳ 162</a> ואילך. הגש״פ עם לקוטי טעמים מנהגים וביאורים (קה״ת, תשל״ט) ע׳ תנח."],["28","28","ב״ר פצ״ח, ג. וראה אוה״ת ויחי שס, א. ולהעיר מאוה״ת שמות ע׳ יט."],["29","29","כתובות קיב, א. 29*) וראה פי׳ הרלב״ג עה״פ: „ופרינו מהצרים המצרים לנו״. וראה לקמן בפנים."],["30","30","תהלים פא, יא."],["31","31","ולהעיר שענין זה כתוב במזמור פ״א אל״ף שבתהלים, המורה על הרחבת הפה, כי פ״א מרמז לפה (שבת קד, א. אותיות דר״ע אות פ״א) ופ״א אל״ף מרמז על הרחבה והוספה בהפה. ועפ״מ המנהג שקיבל אדה״ז מרבו בשם רבו מורנו הבעש״ט לאמר הקאפ׳ תהלים המתאים למספר* שנותיו** (קובץ מכ־ *) לדוגמא, כשנמלאו לו יג שנה מת־חיל מזמור יד. **) וראי׳ לחדודי עכ״פ לזה : שני מני־נים במספר (ברכות ט, סע״ב: הני קג* קד הוויין) מזמורי תהלים: קנ (בכל ה־ספרים. וראה מנחת שי לתהלים בהקדמתו), קמז (ירושלמי שבת פט״ז ה״א. מס׳ סופרים פט״ז הי״א. מדרש תהלים מזמור כב) וע״פ מרז״ל (ברכות ט, ב) „אשרי האיש (קאפ׳ א) ולמה רגשו גוים (קאפ׳ ב) חדא פרשה היא״ — ולפי מנין זה — מזמור „לשלמה משפטיך גו׳״ הוא מזמור ע״א, וסיומו „כלו תפלות דוד בן ישי״, היינו שאמרו דוד כשנסתלק, ודוד נסתלק בן ע׳ שנה (ב״ר פצ״י, ד. רות רבה פ״ג, ב. וראה ג״כ במדב״ר פי״ד, יב. זח״א קסח, א. וראה ספה״מ להצ״צ קח, ב ואילך). [עי׳ לקמן ע׳ 77 — הוספה לאחר זמן]. וכאן להעיר: הקשו כו״כ ממפרשי הש״ס (ברכות שם) ומדרש (תהלים שם) מסתירת ב׳ המנינים ותירצו כו׳. ויש להוסיף קושיא על קושיתם — דדוקא ראשוני המפרשים לא עמדו ע״ז כלל (ורק ששקו״ט איזה מזמורים כחדא חשיבי) : ולפענ״ד — קושיא מעיקרא ליתא, כי עד״ז מצינו בנוגע לה׳ ספרי התורה שדרז״ל שנחלקים גם ** לשבע (שבת קטז, א) וגם בנוגע לכ״ד ספרי תנ״ך, שספר אחד מהם הוא — תרי עשר. ולהעיר מנ״ן סדרים דאורייתא (זח״א קד, ב. ובכ״מ) ובפרטן הם נד. ס׳ המה מלכות—מסכתות (שהש״ר עה״פ ו, *) להעיר מסנה׳ קג, ב: קג פנים. ל״ת להאריז״ל ר״פ וישלח. **) שהרי בודאי לא פליג מ״ד זה על חלוקת התורה לה׳ ספרים."]]],[1300101084,"<h3>תולדות א</h3>\nשהוא מצד הבריאה (וכנ״ל שהאדם צריך להוסיף ולהרחיב את הבריאה).\nוגם בזה צלה״ב: מכיון שהקב״ה ברא את הפה באופן מסוים, וכמ״ש³² „מי שם פה לאדם וגו׳ הלא אנכי ה׳ ״ — איך אפשר שבן אדם ירחיב את הפה ?\nע״ז בא התירוץ ב(תחלת) הכתוב: „אנכי ה״א המעלך מארץ מצרים״: „ארץ מצרים״ ארץ מיצרים גבולים וכו׳³³, והקב״ה „העלה״ את בנ״י מ־מצרים וגבולים אלו — (ואדרבא ופרינו בארץ) — שמדייק ואינו כותב „המוציאך״ (כברוב המקומות), כ״א „המעלך״, היינו שהעלה אותם הקב״ה למעלה מהגבלות, ולכן יכול וצ״ל „הרחב פיך״ (והעולם) — לבטל את ההגבלות³⁴.\nזהו רצונו של הקב״ה בבריאת ה־עולם שבנ״י יוסיפו עלי׳ ע״י עבודתם, והוא הנותן להם כח ע״ז, כנ״ל.\n[וזהו גם הביאור (בפנימיות הענ־ינים) בטענת טורנוסרופוס הרשע³⁵ „אם אלקיכם אוהב עניים מפני מה אינו מפרנסם וכו׳ (ונתינת הצדקה) מחייבתן לגיהנם״, ותשובת ר״ע ע״ז: „ואנן קרוין בנים וכו׳ ״ — היינו שהוא טען, דמכיון שהקב״ה ברא את העניים באופן דעניות, איך יתכן ש־מישהו יוסיף בזה (ע״י נתינת ה־צדקה³⁶), וע״ז ענה לו ר״ע שבנ״י הם בניו של הקב״ה, (שעי״ז מובן: א) שצריך לתת צדקה — כפשט הש״ס, ב) איך יכולים לשנות סדר הבריאה, כי) הם „חלק אלוקה ממעל ממש כו׳ כמו שהבן כו׳ ״³⁷, ויש לבנ״י כח שלמע׳ מהגבלות, ובמילא (לא רק שאין זה היפך רצונו, כ״א) זהו רצונו, ואדרבה: הוא הנותן הכח על זה].\nומפורש בכתוב זה שהקב״ה מבטיח ונותן עוד יותר: לא רק שנותן כח לפני העבודה, כ״א שמסייע הוא גם אח״כ, שהעבודה תעשה פרי ותגיע לתכליתה, שתפעול הוספה בהעולם — כדמסיים: „ואמלאהו״ — ע״י שהאדם יעשה חלקו „הרחב פיך״, מובטח הוא כי „ואמלאהו״, שהקב״ה ימלא „פיו״.\nוגם ענין זה מרומז בהכתוב דפר־שתנו: „ופרינו בארץ״ אינו ל׳ של תפלה או בקשה וכיו״ב (שספק אם יהי׳ כן בפועל³⁸), כ״א הוא ל׳ ודאי — כי כנ״ל מובטחים, שאם ממלאים",[["","","תבים לתהלים ע׳ 214) י״ל, שלכן שייך מזמור זה למי שנכנס לשנת שמונים ואחת שלו, כי שמונים שנה מורה על שלימות הטבע וכו׳ כמ״ש (תהלים צ, י) „ואם בגבורות שמונים שנה גו׳״, וכשנכנסים להשנה שלאח״ז, ה״ז ענין של הרחבה והוספה על (הגבלות) הטבע ***, ולכן אומ־רים אז מזמור פ״א אל״ף, כנ״ל (ובו הציווי (ונתינת כח) „הרחב פיך גו׳״)."],["32","32","שמות ד, יא."],["33","33","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370224\" data-slug=\"torah-or\" data-id=\"3901370224\">תו״א מט, סע״ד</a>. נג, סע״ג ועוד. וראה שעהיוה״א (פ״א) שהשם של הדבר מורה על תוכנו."],["34","34","וגם בתורה צ״ל „לאפשא לה״ (וח״ג יב, ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370180\" data-slug=\"torah-or\" data-id=\"3901370180\">תו״א מקץ לט, ד</a>. אגה״ק סכ״ו (קמה, א)). ח״ט. במדב״ר פי״ח, כא) ובפרטן סג (וב־פיה״מ להרמב״ם בהקדמה — סא). ועוד. ***) ולכן אמרז״ל (אבות פ״ה מכ״ב — לגירסת אדה״ז בסידורו) „בן שמונים לגבורה״, כי אמיתית ענין הגבורה הוא ע״ד „גבורות גשמים״."],["35","35","ב״ב י, א."],["36","36","ולהעיר שצדקה היא כללות כל המצות (<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל״ז (מח, ב</a>). וראה אגה״ק סי׳ יז, וראה ב״ב ט, סע״א)."],["37","37","<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ״ב</a>."],["38","38","ראה לעיל ע׳ 41."]]],[1300101085,"<h3>תולדות א</h3>\nרצונו של הקב״ה ועובדים העבודה שהוא דורש, בודאי מגיעים להתכלית,\nופועלים לא רק „ופרינו בארץ״ — בלה״ק, כ״א גם „כתרגומו וניפוש בארעא״,\nוכמבואר בענין³⁹ של׳ תרגום הוא חול ולא קודש, ובנדו״ד — פועלים הרחבה והוספה לא רק בהעולם כפי שהוא בלה״ק (שגם זה — עולם מלשון העלם⁴⁰), כ״א גם בעניני חול וכו׳ של העולם „בארעא״ — לשון תרגום — שגם בהם נעשה דירה לו ית׳.\nוכשתושלם עבודה זו יתקיים ה־יעוד⁴¹ ד„ונגלה כבוד ה׳ וראו כל בשר יחדיו כי פי ה׳ דיבר״⁴².\n(משיחת ש״פ חיי שרה, תש״ל)",[["39","39","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370345\" data-slug=\"torah-or\" data-id=\"3901370345\">תו״א משפטים עז, ד</a>. וראה לעיל ע׳ 50 בארוכה."],["40","40","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380459\" data-slug=\"likkutei-torah\" data-id=\"4001380459\">לקו״ת שלח לו, ד</a>. ש״ש סד, ב. ביאוה״ז להצ״צ ע׳ שנה (ומציין למרז״ל)."],["41","41","ישעי׳ מ, ה."],["42","42","ולהעיר שהבאר הג׳ מרמזת לבי־המ״ק השלישי (ראה רמב״ן, רבינו בחיי, כלי יקר, ועוד עה״פ). ● (הוספה לע׳ 75 להערה הב׳ בהערה 31 :) החילוק כזה (אם „אשרי האיש״ ו„למה רגשו״ „חדא פרשה היא״ או כמו שהוא בכל הספרים שלנו ש„למה רגשו״ הוא מזמור השני) — יש לבאר ע״פ סוגיית הגמרא בברכות שם, שמביא ראי׳ ע״ז ש„אשרי האיש״ ו„למה רגשו״ הם „חדא פרשה״ מזה ש„כל פרשה שהיתה חביבה על דוד פתח בה באשרי וסיים בה באשרי פתח באשרי דכתיב אשרי האיש וסיים באשרי דכתיב אשרי כל חוסי בו״. והביאור: תוכנו של המזמור ד„אשרי האיש״ הוא מעלת ישראל בקיום התומ״צ („לא הלך בעצת רשעים גו׳ כי אם בתורת ה׳ חפצו גו׳״) שעי״ז „והי׳ גו׳ וכל אשר יעשה יצליח״, (והפכם ו)„לא כן הרשעים כי אם כמוץ גו׳״ — התמי׳ במזמור שלאח״ז „למה רגשו״ וכללות תוכנו — הם שלילת השליטה של אוה״ע על בנ״י ואדרבא „אתנה גוים נחלתך ואחוזתך אפסי ארץ״ — באופן שלמעלה מן הטבע (ולכן באה התמי׳: „למה רגשו גוים גו׳״ שהרי) „יושב בשמים ישחק גו׳״. ושני המזמורים „חדא פרשה״ הם (בתקופה אחת) — כאשר בנ״י הם (בגלוי)"]]],[1300101086,"<h3>תולדות א</h3>\nבמצב ד„אשרי . . לא הלך בעצת גו׳״, כי זה מביא (בגלוי) „למה רגשו גוים גו׳ יושב בשמים ישחק גו׳ אתנה גוים נחלתך גו׳ אשרי כל חוסי בו״.\nולכן „חדא פרשה היא״ (בימי דוד) לדוד שבימיו הי׳ מצב הנ״ל בפועל ד„לא הלך בעצת רשעים גו׳״, „רגשו גוים״, „אתנה גוים נחלתך״, וכפרש״י עה״פ „למה רגשו גוים״ — „. . ולפי משמעו יהי׳ נכון לפותרו על דוד עצמו* כענין שנאמר וישמעו הפלשתים . . ונפלו בידו וכו׳״.\n[בימי שלמה לא הי׳ מצב ד„רגשו גוים״, כי ניבא עליו „הוא יהי׳ איש מנוחה והניחותי לו מכל אויביו מסביב גו׳ שלום ושקט״ (דה״י א כב, ט)]\nאבל בהדורות שלאח״ז דלא קיימא סיהרא באשלמותא (ראה זח״ב פה, א. וראה ג״כ שמו״ר פט״ו, כו)\nובפרט בזמן הגלות — חסר באשלמותא דרבים בעניני ד„אשרי האיש גו׳״ אף שהי׳ בעבר (וישנו גם בהווה בכו״כ יחידים) — ולכן גם לא קשה על אשר בהווה „רגשו גוים״,\nאלא שלאחרי זמן, בימות „מלך המשיח״ (פרש״י עה״פ) — יתמהו „למה רגשו גוים״,\nו„אשרי האיש גו׳ והי׳ כעץ שתול גו׳״ מדבר ביחיד בכל זמן — ומזמור (וזמן) בפ״ע ** — באחרית הימים — (שאז יתמהו) למה גו׳.\nועפ״ז מובן ג״כ מה שרש״י מביא פירוש הנ״ל (ד„למה רגשו״ קאי על דוד) כפירוש שני — אף שזהו „לפי משמעו״ — ומה ש„רבותינו דרשו את הענין על מלך המשיח״ מביא כפי׳ ראשון,\nכי פשוטו של מקרא — כל הספרים שלנו — ה״ה ב׳ מזמורים, „למה רגשו״ פרשה בפ״ע (תקופה בפ״ע),\nאלא שע״פ דחז״ל חדא פרשתא היא (באותה התקופה).\nואף שדחז״ל היא, בכ״ז פי׳ גם אליבא (אף שפרש״י בא לפרש פשוטו של מקרא) — כיון שזהו „משמעו״.",[["","","*) שעפ״ז גם סרה קושית המפרשים על אמרו „אשר לא הלך״ ל׳ עבר — אלא דקאי על „דוד עצמו״ הנהגתו שהתחילה בעבר. **) בחדא״ג מהרש״א שם דשינו „למה רגשו גוים״ לפרשה בפ״ע לאחר שהוסיפו ביבנה (ברכות כח, ב) ברכת המינין. — ולא זכיתי להבין — שהרי דוד כתב ספר תהלים (ב״ב יד, ב) ו(למהרש״א) במשך כל הדורות שלאחריו עד דור יבנה — נמנו והיו פרשה אחת, וביבנה — שינו והפרידו ביניהם :"]]],[1300101087,"<h3>תולדות א</h3>\nולהוסיף שכיון שדוד הוא „נעים זמירות ישראל״ דכל הדורות, כלל בספר התהלים ב׳ המנינים: העיקרי — שהם ב׳ פרשיות (כנ״ל); השני — דדורו דדוד, באמירתו בפעם הראשונה ש(לכן — מוכרח שיהי׳ משמעו באופן ש)הם פרשה אחת ***\n(משיחת ש״פ תולדות תש״ל״ד)",[["","","***) וצ״ע דעפ״ז (ובמכש״כ לפי׳ המהרש״א הנ״ל) דהחילוק ד„אשרי״ ו„למה״ פ״א או שתים — תלוי בזמן, משא״כ הטעם דחיבור עוד ב׳ מזמורים — א״כ מצינו עוד מנין (או שני מנינים) במספר מזמורי תהלים, נוסף על קמ״ז וק״נ : וי״ל ביישוב כהנ״ל — דאין הפי׳ שנמנה כפרשה אחת או כשתים בדורות שונים, אלא — במצבים שונים : כשישראל עושים רצונו של מקום (ובמילא אין גם מקום לברכת המינין) אומר התהלה ומתחיל ומסיים באשרי (פרשה אחת), משא״כ כשאין עושין רש״מ. ועד״ז י״ל ג״כ בנוגע לשני המזמורים (ראה מנחת שי בהקדמת פי׳ לתהלים) : לא לנו — דאינו התחלת מזמור (וענין בפ״ע — כ״א המשך ל(המצב ד)בצאת ישראל ממצרים (ראה רד״ק שם), משא״כ כשעושים רש״מ — אדרבא צ״ל „לנו״), הללו גו׳ כי גבר — הוא סיום דהקודמו „אהבתי גו׳ לי יהושיע״ (דכיון שעושים רש״מ — „יהושיע (באופן אשר) גבר עלינו חסדו״). להעיר ממרז״ל דאין השם שלם ואין הכסא שלם עד כו׳ (תנחומא ס״פ תצא) ; מפי׳ הצ״צ בפתח וסיים באשרי (הוספה לתהלים ע״ה בסופו)."]]],[1300101088,"<h3>תולדות ב</h3>\nא. בפרשתינו¹ מסופר, שקודם שנתברך יעקב אבינו בברכת ״ויתן לך האלקים וגו'״ — אמר יצחק אבינו, בתור הקדמה, ״ראה ריח בני כריח שדה אשר ברכו ה'״.\nוארז״ל על פסוק זה בספרי²: ״וכן אתה מוצא ביצחק שראה אותו (הביהמ״ק) בנוי וראה אותו חרב וראה אותו בנוי ומשוכלל לע״ל. ראה ריח בני — הרי בנוי, [״ריח״ קאי על הקרבנות (שענינם ״ריח ניחוח״) שהקריבו בביהמ״ק, ו״בני״ פירושו ״בנוי״] כריח שדה — הרי חרב [כמ״ש³ ״ציון שדה תחרש״] אשר ברכו ה' — הרי בנוי ומשוכלל לע״ל״.\nולכאורה אינו מובן: איך אפשר לומר שכל ג' הדברים הנ״ל שראה יצחק הם הקדמה לברכה שברך ליעקב — ובפרט שאחד מהם הוא ביהמ״ק בחורבנו שסיבת החורבן הוא ״מפני חטאינו כו' יד שנשתלחה במקדשך״ *3 — ואיך יתכן שגם זה (שתוכנו היפך הטוב והברכה) יהי' הקדמה לברכה ?\nגם צ״ל טעם הדבר שחורבנו של ביהמ״ק מרומז כאן ב(תיבת ו)ענין ״שדה״ (שהוא רק ע״פ מש״כ ״ציון שדה תחרש״⁴) ; זה ש״ריח בני״ מרמז לביהמ״ק בבנינו, מובן — כי הקרבנות ענינים ״ריח ניחוח״ כנ״ל והקרבנות הם עיקר בביהמ״ק⁵, וכן מובן היטב זה שהתיבות ״אשר ברכו ה'״ מרמזות לביהמ״ק הבנוי ומשוכלל לעת״ל, דהרי בנינו ושיכלולו של ביהמ״ק דלעתיד זהו תכלית ברכתו של הקב״ה ;\nאבל זה שביהמ״ק בחורבנו מרומז ב״שדה״ אינו מובן. גם חורבנו של הבית באופן זה או אחר מאי נפק״מ כאן ? ועוד ד״שדה תחרש״ הי' לאחרי חורבן (שריפת) ביהמ״ק והוא ענין בפ״ע.\nב. ויובן כ״ז בהקדים משארז״ל⁶ (הובא בפרש״י⁷) עה״פ שלאחרי ה־",[["1","1","כז, כז."],["2","2","ברכה לג, יב."],["3","3","מיכה ג, יב. *3) תפלת מוסף דיו״ט."],["4","4","וגם בפסוק זה — לכאורה ״שממה״ הוא חורבן יותר מאשר ״שדה״. וכמו שמצינו לשון זה בנוגע לחורבן בכ״מ."],["5","5","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300041345\" data-slug=\"likkutei-sichot\" data-id=\"1300041345\">ובפרט ע״פ</a> מש״כ הרמב״ם (ריש הל' בית הבחירה): ״מ״ע לעשות בית לה' מוכן להיות מקריבים בו הקרבנות״, דתכלית ביהמ״ק הוא, ״להיות מקריבים בו הקרבנות״. (ודלא כרמב״ן ר״פ תרומה. אבל עיין השגותיו בסהמ״צ מ״ע לג. וראה לקו״ש ח״ד ע' 1346)."],["6","6","ב״ר פס״ו, ג."],["7","7","ההכרח לפי' זה ע״פ פשוטו של מקרא הוא — יתור הוא״ו (״ויתן״) ; ואעפ״כ מביא רש״י פי' ב' ודוקא עליו כותב שהוא ״ולפי פשוטו״ — מפני הקושיא שבפנים : מה חסר בהנתינה הראשונה [דאפ״ל כפי השפ״ח, שהפי' הוא דאם תפסק הברכה מפני החטא יחזור ויתן — דהרי מפורש אח״כ (שם, מ) היפכו ״והי' כאשר תריד ופרקת עולו מעל צואריך״ ; ואין לומר דיצחק אמר כן (וחזר מאמירתו הקודמת) מפני בקשת עשו ״ברכני גם אני אבי גו' ויבך״ (שם, לח), אבל ה״ויתן״ הי' כולל גם אם יחטא — דאם יש כאן חרטה הרי הי' יכול לברכו גם בשאר הברכות, אף ש״הן גביר שמתיו לך ואת כל אחיו נתתי לו לעבדים ודגן ותירוש סמכתיו״ (שם, לז)],"]]],[1300101089,"הקדמה: ויתן לך האלקים גו' — ״יתן ויחזור ויתן״, דלכאורה קשה:\nמה חסר בנתינה הראשונה (״יתן״) אשר משו״ז ברכו בנתינה נוספת (״ויחזור ויתן״) ? — דבשלמא כשהנתינה היא מיד בו״ד, הנה גם אם היא מתנה גדולה ומרובה⁸, בכ״ז היא מוגבלת (שהרי הנותן הוא מוגבל) ולכן יתכן להשלימה ולהוסיף עלי' בנתינה אחר נתינה⁹ ; משא״כ בעניננו, כשהקב״ה הוא הנותן, הרי בודאי שגם נתינתו הראשונה מחסדי ה'¹⁰ שלימה היא ובלי גבול — כמו שהוא יתברך הוא בל״ג ובתכלית השלימות — וא״כ מה ניתוסף ב״יחזור ויתן ?\nואפילו את״ל גם בהברכה דלמעלה הגבלה ו(במילא) הוספה ״יתן ויחזור ויתן״ — זה יתכן כשהנידון הוא בברכה פרטית לאיש פרטי (ע״ד ברכות השבטים ע״י יעקב אבינו ומשה רבינו, שע״ז נאמר¹¹ ״איש אשר כברכתו ברך אותם״), דמצד הגדרתה כברכה פרטית למתברכים פרטים מקום להוסיף עוד ענינים בברכה עצמה או לצרף בה עוד מתברכים. משא״כ בנדו״ד הלא המתברך הוא יעקב אבינו, שהוא כולל את כל הנשמות כולם (כידוע¹² בענין ״שופרי' דיעקב אבינו מעין שופרי' דאדם הראשון״¹³) ; וגם הברכה ה״ה כוללת את כל הטוב דכל סדר ההשתלשלות : ״מטל השמים ומשמני הארץ״ ; ובפרט שזהו ״מטל השמים — הנעלה והמשובח בשמים (כידוע¹⁴ מעלת טל על מטר), וגם ״משמני הארץ״, המובחר שבארץ — וא״כ מהו זה ש״יחזור ויתן״ עוה״פ¹⁵ ?",[["","","ואעפ״כ הפי' הראשון הוא ״יתן ויחזור ויתן״, כי לפי פי' הב' קשה: מהו ההמשך ד״ויתן לך גו'״ למ״ש לפנ״ז ״אשר ברכו הוי'״ (משא״כ אם הי' כתוב ״אשר נתנו ה'״). נמצא דפי' הא' מתקבל יותר מצד המשך ותוכן הכתובים, ופי' הב' מצד פי' התיבה, ולכן ה״ז פי' השני, אבל דוקא הוא ״לפי פשוטו״ (של התיבה). וגם עפ״י ״יינה של תורה״ שבפרש״י קשה לפי' הב' (שבא בהמשך למ״ש לפנ״ז) — כי מתחלה כתוב ״ברכו הוי'״, וכאן כתוב ״ויתן לך האלקים״."],["8","8","וכמרז״ל (ב״ב נג, א) כל הנותן בעין יפה נותן."],["9","9","וגם כשהנתינה היא למעלה מהגבלות ובל' אדה״ז (אגה״ק ס״י) ״אינו נותן גבול ומדה לנתינתו״ כ״א מתנהג ״בחסדי ה' שהם בלי גבול ותכלית״ — אפשר להוסיף עלי', כי אי״ז בל״ג באמת (להעיר מהמבואר בכ״מ בדא״ח בענין ״בכל מאודך״, מאד שלך). ובפשטות הוא : נתינה הא' ״כל אשר לאיש יתן״ (ראה אגה״ק שם), נתינה הב' — בדוגמת ״לח עלי'״ (ביצה טז, ב. וראה אור תורה להה״מ בסופו). [וכצ״ל בהר״ד דההתעודות ש״פ בראשית תשל״ג, שזהו תורת הה״מ (ולא הבעש״ט)]."],["10","10","ראה אגה״ק ס״י, ובכ״מ."],["11","11","ויחי, מט, כח. ומובן שעד״ז הוא גם בנוגע ברכת משה להשבטים. ואף שפרש״י ״יכול שלא כללן כולם בכל הברכות ת״ל ברך אותם״ — הרי אין הפי' שהם ברכות כלליות (שע״ז הרי אין ראי' ממש״נ ״ברך אותם״), כ״א שבברכות פרטיות אלו ברך את כל אחד ואחד מהשבטים (והחילוק ביניהם הוא מהו העיקר בכאו״א, או ע״ד פרש״י (ויצא לא, יח) שקנה מצאנו)."],["12","12","אגה״ק ס״ז. וראה לקו״ש ח״ד ע' 1051 הערה 18."],["13","13","ב״מ פד, א. זח״א לה, ב."],["14","14","ראה תענית ג, ב. לקו״ת פ' האזינו."],["15","15","אין לומר שהכוונה ב״יתן ויחזור ויתן״ היא להב' פירושים שב״מטל השמים ומשמני הארץ וגו'״ : א) כפשוטו ; ב) ״מטל השמים זו מקרא ומשמני הארץ זו משנה דגן זו תלמוד תירוש זה אגדה״ (ב״ר פס״ו, ג), כי גם לפי פשוטו צ״ל ב' ענינים ב״ויתן״."]]],[1300101090,"גם צ״ל מהו אומרו ״ויתן לך האלקים״ — והלא ענין הברכה הוא משם הוי'¹⁶, שהוא בחי' הרחמים, ולא שם אלקים שענינו דין וצמצום¹⁷ ?\nג. ויובן כ״ז ע״י משל מהשפעת הרב לתלמיד, דאפ״ל בזה שני אופנים : א) שהתלמיד הוא רק מקבל שכל הרב — דהיינו שאפילו אם קבלתו היא באופן הכי נעלה ועד להתעצמות בשכלו של הרב¹⁸, בכ״ז אין השפעה זו פועלת בהתלמיד לחדש בזה בכח עצמו.\nב) שהתלמיד מקבל את כל שכל הרב ובאופן נעלה כ״כ, עד שפועל בו גם היכולת להוסיף ולחדש בזה בכח עצמו.\nוכמבואר חילוק זה במשנה דאבות¹⁹, בתלמידיו של ריב״ז, שר״א בן הורקנוס הוא ״בור סוד שאינו מאבד טיפה״, דרגא הכי נעלית באופני הקבלה של החכמה עצמה ; ור״א בן ערך הוא ״כמעין המתגבר״, היינו שהוא מוסיף ומחדש בכח עצמו.\nומובן שבאופן השני של ההשפעה יש יתרון מעלה לגבי זה של הראשון, וכמפורש שם במשנה : ״אם יהיו כל חכמי ישראל בכף מאזנים ואליעזר בן הורקנוס אף עמהם ור״א בן ערך בכף שני' מכריע את כולם״. והטעם פשוט : עם היות ש״בור סוד שאינו מאבד טיפה״ היא מדריגה נעלית מאד בקבלת וקליטת החכמה [אשר לכן ר״א בן הורקנוס, במעלה זו, הוא מכריע את כל חכמי ישראל, כולל גם ר״א בן ערך²⁰], מ״מ החכמה במקבל היא מוגבלת — לא יותר (אף שגם לא פחות) ממה שקיבל מרבו ; משא״כ מי שהוא ״כמעין המתגבר״, להוסיף חכמה בכח עצמו, הרי יש בכוחו להתגבר יותר ויותר בלי הגבלה²¹.\nאמנם גם מעלתו של תלמיד זה שהוא ״כמעין המתגבר״ בכח עצמו, היא תוצאת ופעולת ההשפעה של הרב, דהרי תפקידה ותכליתה של השפעה אמיתית היא גם בזה, שהרב המשפיע ״מעמידו (את התלמיד) על רגליו״ שיוכל להמציא ולחדש בכח עצמו — ונמצא שגם חידושיו אלו יסודתם בהשפעת הרב [וכמובן גם מסגנון המשנה, שבה נמנה השבח ״כמעין המתגבר״, שבאה בהמשך ובקישור לזה ש״חמשה תלמידים היו לו לר״י בן זכאי״, שגם מעלה זו היא תוצאת היותו תלמיד ריב״ז].\nד. עד״ז הוא גם בההשפעה מלמעלה ע״י הברכה הנ״ל : מלבד ההשפעה עצמה יש בה גם העילוי והיתרון, שפועל במושפע ״ומעמידו״ בדרגא כזו שיוכל לנצל את ההשפעה בכח עצמו²². וזהו ״יתן ויחזור ויתן״ :",[["16","16","וכמ״ש (נשא ו, כד) ״יברכך הוי' וישמרך״."],["17","17","ראה שעהיחו״א פ״ו ואילך. וכן הוא גם לפי פשוטו של מקרא — ראה פרש״י ר״פ בראשית."],["18","18","ע״ד מרז״ל (ע״ז יט, א) עה״פ ״ובתורתו יהגה״ ש״נקראת על שמו״."],["19","19","פ״ב מ״ט (לגירסת אדה״ז בסידורו)."],["20","20","ראה במפרשי המשנה שם (רע״ב ותויו״ט) דלא פליגי ומר אמר חדא ומר אמר חדא."],["21","21","ולכן נקרא ״כמעין המתגבר״ כי אמיתית ענין הגבורה הוא בל״ג, וכידוע בענין ״גבורות גשמים״."],["22","22","ע״ד תורת הבעש״ט (נדפס בקובץ מכתבים א. בסו״ס תהלים אהל יוסף יצחק ע' 193. היום יום כה אלול) : ״החודש השביעי . . הקב״ה בעצמו מברכו . ."]]],[1300101091,"הקב״ה יתן לו כל ההשפעה עצמה (וג״ז דבר שלם הוא וכמו בור סוד שאינו מאבד טיפה) ; ״ויחזור ויתן״ את היכולת להתגבר בכח עצמו בהשפעה זו [וגם זה ״ויתן״, שניתן מהקב״ה, כנ״ל, חלק מההשפעה²³].\nה. שתי מדריגות אלו (״בור סוד שאינו מאבד טיפה״ ו״כמעין המתגבר״) ישנן גם בעבודת האדם, והן : עבודת הצדיקים ועבודת הבע״ת. הצדיק הולך בדרך ישרה ועובד את הוי' בעניני תומ״צ כפי שנתנו ונשפעו מלמעלה, והוא כלי הראוי לקבל כל ההשפעות העליונות שע״י תומ״צ ; הבע״ת עבודתו היא שמהפך את הזדונות לזכיות²⁴, דהיינו שהוא עובד את הוי' באופן דאתהפכא, להפוך הענינים שיהיו לא כפי שנתנו מלמעלה²⁵. לפי הסדר המסודר בעבודת הבירורים א״א לברר ולהעלות את הדברים שהן מגקה״ט לגמרי, כ״א לדחותם בדרך דחי' *25 — אבל ע״י העבודה בכח עצמו דתשובה²⁶ מברר ומעלה גם את הזדונות עד שנעשו זכיות²⁷.\nועכ״ז, גם עבודת הבע״ת, אף שהיא בכח עצמו, גם היא השפעה מלמעלה ; הכח להתעורר מעצמו לשוב בתשובה, ניתן מלמעלה²⁸.\nוהנה כמו שנת״ל, בהמשל דרב ותלמיד, דיש יתרון מעלה בבחי' ״כמעין המתגבר״ לגבי בחי' ״בור סוד שאינו מאבד טיפה״, עד״ז יש יתרון מעלה בעבודת בע״ת לגבי עבודת הצדיקים. וזהו משארז״ל²⁹ : ״במקום שבע״ת עומדים צדיקים גמורים אינם יכולים לעמוד שם״. ומובן, שגם תוכנו של יתרון זה הוא ג״כ ע״ד הנ״ל (במשל דרב ותלמיד) : כשם ש״כמעין המתגבר״ מעלתו בזה הוא שהוא בבחי' בל״ג (משא״כ ״בור סוד״) כמו״כ מעלתם של הבע״ת הוא בבחי' הבל״ג³⁰ שבעבודתן. וכידוע דעבודת הצדיקים היא בהדרגה מסודרת, בעילוי אחר עילוי, משא״כ עבודת הבע״ת שפורצת כל הגדרים והגבלות ועליתו שלא בהדרגה : בשעתא חדא",[["","","ובכח זה ישראל מברכים את החדשים י״א פעמים בשנה״, היינו שמלבד שמברך את חודש תשרי, גם כלול בברכת הקב״ה זה שבנ״י יוכלו לברך את שאר החדשים בכח עצמם."],["23","23","ובהיותו חלק מההשפעה עצמה יומתק הלשון ״ויחזור ויתן״ — חזרה לא רק בנתינה, כ״א גם בדבר הניתן."],["24","24","יומא פו, ב. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא פ״ז</a>."],["25","25","להעיר ממרז״ל (סנה' נס, ב. תקו״ז תמ״א) ״אין דבר טמא יורד מן השמים״ ; (ב״ר פנ״א, ג) ״אין דבר רע יורד מלמעלה״. *25) ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380056\" data-slug=\"likkutei-torah\" data-id=\"4001380056\">לקו״ת פקודי (ד, רע״א</a>)."],["26","26","וכן ע״י הנסיונות (ראה ד״ה אחרי בסו״ס סהמ״צ להצ״צ)."],["27","27","ויומתק עפ״י מרז״ל (ברכות לג, ב) ״הכל בידי שמים חוץ מיראת שמים״ — ועבודת בע״ת היא בעיקר בקו היראה."],["28","28","וכמ״ש (ירמי' ג, יד) ״שובו בנים שובבים נאם הוי'״ וכמרז״ל (חגיגה טו, א) ״יצתה ב״ק ואמרה שובו בנים שובבים״. ובכ״י ויום ג״פ אומרת כו' (ברכות ג, סע״א) וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380334\" data-slug=\"likkutei-torah\" data-id=\"4001380334\">לקו״ת במדבר (ו, ג</a>), <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381229\" data-slug=\"likkutei-torah\" data-id=\"4001381229\">שה״ש (כה, א</a>) : שאין אדם עושה מאומה מצ״ע."],["29","29","ראה ברכות לד, ב."],["30","30","ואף שבנוגע לתשובה נאמר (איוב יא, ו) ״כפלים לתושי׳״ (וראה אגה״ת פ״ס) : כפול ומכופל) — הרי מוכרח לומר שאין הכוונה רק כפלים, ע״פ מרז״ל (שמו״ר רפמ״ו) על פסוק זה : ״בלוחות הראשונות שלא היו אלא עשרת הדברות לבד, ובלוחות השניים אני נותן לך שיהא בהם הלכות מדרש ואגדות״, שזהו הרבה יותר מכפלים — אלא הכוונה ב״כפלים״ : כעין שם המושאל לבחי' בל״ג."]]],[1300101092,"כו' ובחילא סגיא³¹.\nו. ואף שענינים אלו (ההשפעה מלמעלה ; עבודה בכח עצמו) ישנם בכללות גם בעבודת הצדיקים עצמם, ובכל יום ויום :\nתחלתה של עבודת היום הוא ״מודה אני לפניך כו'״ שענינה הודאה על ההשפעה מלמעלה — ״שהחזרת בי נשמתי בחמלה״. וגם אח״כ הרי תומ״י הוא מתפלל תפילתו (כמרז״ל *31 ״תפילתי שתהא סמוכה למטתי״), דהיינו שמבקש מהקב״ה שישפיע לו כל הברכות וההשפעות מלמעלה ; ומכיון שהוא מברך עליהן בשם ומלכות, בודאי שהקב״ה ממלא בקשתו ומשפיען לו³² — הרי שראשיתה של עבודת היום שלו שייכת לקבלת ההשפעות מלמעלה, ואין בזה עדיין עבודתו בכח עצמו ; אמנם לאח״ז מתחלת העבודה בכח עצמו, בלימוד התורה וקיום המצות, שהו״ע ״כמעין המתגבר״ —\nמ״מ, בפרטיות, הנה גם עבודה זו של הצדיקים בלימוד התורה וקיום המצות (במשך כל היום), מכיון שמקיים בזה מה שציוהו (שזהו גם השפעה ונתינת כח מלמעלה), אין זה אמתית העבודה בכח עצמו, שאינה אלא בעבודת התשובה.\nועפ״ז י״ל שבהברכה ליעקב ״יתן ויחזור ויתן״ כלולות לא רק השפעות עליונות מלמעלה בענינים גשמיים ורוחניים (ובב' הפרטים : (א) קבלת ההשפעה עצמה ; (ב) שיוכל לנצלה בכח עצמו), כ״א גם ההשפעה ונתינת הכח מלמעלה לעבודת ה'³³ בב' סוגי העבודה הנ״ל : עבודת הצדיקים (״יתן״) ועבודת הבע״ת (״ויחזור ויתן״).\nז. ע״פ כל הנ״ל יתבאר עוד ענין, והוא — שעד הברכה הלזו שע״י יצחק איננו מוצאים שמי שהוא יברך בנוסח של ״ויתן לך האלקים גו'״ : עד אז לא הייתה עדיין האפשריות וההזדמנות לעבודת התשובה כמו שהיא אצל בנ״י³⁴ : אברהם אבינו הלא הי' צדיק גמור, ובנ״א שקדמוהו *34, הרי אינם בגדר בנ״י³⁵ ; ואף שישמעאל, בנו של א״א חזר בתשובה³⁶ — לא הייתה בבחי' התשובה של האיש הישראלי (שמובנה : הוא שחטא, ואעפ״כ בעת שחטא ״ישראל הוא״³⁷,",[["31","31","זח״א (קכט, סע״א ושם) עיי״ש. ולהעיר מלקוטי לוי יצחק שם. *31) ברכות ה, ב."],["32","32","כמבואר באגה״ת (פי״א)."],["33","33","ואף ש״הכל בידי שמים חוץ מיר״ש״ — הרי מבואר (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380368\" data-slug=\"likkutei-torah\" data-id=\"4001380368\">לקו״ת במדבר טו, א</a>) בענין ״מי יתן והי' לבבם גו'״ שמצד דרגת ״מי״ (שלמעלה מבחי' ״שמים״) נמשך הכח גם ליר״ש."],["34","34","וחילוק גדול בין התשובה של בנ״י לשל אוה״ע — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061053\" data-slug=\"likkutei-sichot\" data-id=\"1300061053\">לקו״ש ח״ג ע' 981</a> הערה 10. ח״ו ע' 53 ואילך. *34) שהרי קין ואדה״ר עשו תשובה (ב״ר ספכ״ב)."],["35","35","משא״כ בנוגע לאברהם הרי ישנן דעות שהי' לו דין של בנ״י (ראה פרשת דרכים דרך האתרים דרוש ראשון. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051155\" data-slug=\"likkutei-sichot\" data-id=\"1300051155\">לקו״ש ח״ה ע' 143</a> ואילך) ; ואפילו להדעות שהי' לו דין ב״נ, עכ״ז הרי יש לו שייכות וכו' לעבודת בנ״י, וכדמוכח ממה שאמרו רז״ל (ע״ז ט, א) שמאברהם הותחלו השני אלפים תורה (וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370049\" data-slug=\"torah-or\" data-id=\"3901370049\">תו״א לך יא, ב</a>) שממנו הותחלה בחי' התיקון בדוגמת מ״ת), וגם מזה ש״מעשה אבות סימן לבנים״ (ראה ב״ר פ״מ, ו. רמב״ן בראשית יב, ו. אוה״ת ר״פ לך)."],["36","36","פרש״י ח״ש (כה, ט)."],["37","37","סנה' מד, א."]]],[1300101093,"והוא ששב בתשובה) כי עליו ארז״ל³⁸ ״אברהם יצא ממנו ישמעאל״, שיצא ופירש ממנו³⁹, וכיון שכן, הרי בתשובתו אינו הוא עצמו ששב, אלא כאילו מציאות אחרת.\nמשא״כ בעת הברכה אשר בירך יצחק כבר באה האפשריות לענין התשובה — בבנו, בעשו, שאע״פ שגם בו נאמר ״יצחק יצא ממנו עשו״ בכ״ז ביארו חז״ל⁴⁰ אופן יציאתו שהי' ״ישראל מומר״⁴¹ ותשובה שפיר שייכת לו⁴².\nובזה גם יומתק מה שרצה יצחק⁴³ לברך את עשו⁴⁴ (בברכה זו ד״ויתן לך״) — כי רצה להמשיך עליו⁴⁵ את הכח לתשובה⁴⁶ (אבל יעקב, שהוא איש תם — הרי עבודת הצדיקים עבודתו).\nאבל באמת גם ברכה זו שייכת רק ליעקב, כי גם עבודת התשובה בפנימיותה ועצמיותה לא תתכן אלא ביעקב⁴⁷ ובניו⁴⁸.\nח. עפ״י המבואר לעיל יובן מ״ש בספרי שראה יצחק ביהמ״ק בבנינו, בחורבנו, וכמו שהוא בנוי ומשוכלל לעת״ל : ביהמ״ק בבנינו הראשון (שלא קדמו החורבן) הו״ע עבודת הצדי־",[["38","38","פסחים נו, א. ויק״ר פל״ו, ה. ספרי דברים ו, ד. שם לב, ט."],["39","39","ראה אוה״ת וירא צג, ב."],["40","40","קדושין יח, א."],["41","41","דבישמעאל כתיב (וירא כא, י) ״לא יירש בן האמה הזאת עם בני יצחק״, משא״כ בנוגע לעשו נאמר בו כי ירושה לעשו נתתי (קדושין שם), ועוד דכתיב (שם, יב) ״ביצחק יקרא לך זרע״, וארז״ל ע״ז (נדרים לא, א. סנה' נס, ב) ״ולא כל יצחק״, הרי שהוא נכלל ביצחק. וי״ל טעם החילוק ביניהם, ע״פ מ״ש בכתוב זה עצמו : ״בן האמה הזאת״, משא״כ עשו שהי' בן רבקה. וראה בארוכה לקו״ש הט״ו ע' 192 ואילך."],["42","42","ולהעיר דרישא דעשו בעטפוי דיצחק (לאחר שרצה למנוע דבר טוב (קבורת יעקב במערת המכפלה)) ונמצא במערת המכפלה (תרגום יב״ע ויחי נ, יג), וראה לקמן הערה 47. ובארוכה — לקו״ש שם."],["43","43","ועפ״י משנת״ל שעבודת התשובה היא בבחי' בל״ג, בחי' הגבורה האמיתית (ראה לעיל הערה 21), י״ל עוד טעם למה הותחל ענין התשובה מיצחק דוקא, כי ענינו של יצחק הוא קו הגבורה."],["44","44","מתאים עם המבואר בתו״א ובתו״ח (פרשתנו) שכוונת יצחק היתה להמשיך עליו אור עליון, ועי״ז יתברר — כי גם הכח לתשובה נמשך מדרגא עליונה זו."],["45","45","ועפ״י משנת״ל (בהערה 43) שענין התשובה שייך ליצחק דוקא, יומתק ה״יינה של תורה״ דפרש״י (ח״ש כה, יא) : ״אעפ״י שמסר הקב״ה את הברכות לאברהם נתיירא לברך את יצחק מפני שצפה את עשו יוצא ממנו״, ולכאורה, הרי גם יצחק ידע ענינו של עשו, ואעפ״כ רצה לברכו, כדי להמשיך עליו אור עליון, ולמה נתיירא אברהם להמשיך עליו אור עליון (עד שבשביל זה לא רצה לברך גם את יצחק) ? אמנם עפ״י מ״ש בפנים שיצחק רצה לברך את עשו בעבודת התשובה — והרי זה שייך ליצחק דוקא (כבהערה 43) — מובן שאי״ז ענינו דאברהם, שעבודתו היתה בקו החסד."],["46","46","ואף שב״ויתן לך גו'״ כלולה גם עבודת הצדיקים כנ״ל (שאינה שייכת לעשו, לכאורה) — הרי מובן שגם בעבודת התשובה צ״ל כלולה עבודת הצדיקים (קיום התומ״צ וכו') כדלהלן (סעיף ט). ועפ״ז יומתק זה שבכתוב מפורש רק ״ויתן״ בוא״ו המוסיף, הנתינה השני' — כי לפי סברת יצחק שזה עשו, הרי עבודת הצדיקים רק כלולה בעבודת התשובה ; אבל הפי' בזה הוא ״יתן ויחזור ויתן״, ב' הענינים, כי לפי האמת הי' יעקב, ולו שייכים ב' העבודות."],["47","47","ול״רישא דעשו״ ראה ביאורו ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370094\" data-slug=\"torah-or\" data-id=\"3901370094\">תו״א (תולדות כ, ב</a>) ובאוה״ת (שם ע' קנו)."],["48","48","וראה לקמן ע' 88 ואילך."]]],[1300101094,"קים⁴⁹, ישר הולך וכו' ; משא״כ ביהמ״ק בחורבנו ואח״כ שוב בבנינו ושיכלולו לעת״ל הוא כענין עבודת התשובה שלאחרי הירידה והחורבן⁵⁰.\nויובן מה שגם ראיית ביהמ״ק בחורבנו באה בהקדמה לברכה זו, כי היא מתאימה עם כוונת הברכה, שהקב״ה ״יתן ויחזור ויתן״ ההשפעה ונתינת כח הן לעבודת הצדיקים והן לעבודת הבע״ת.\nומוסבר ג״כ למה נרמז ״ביהמ״ק בחורבנו״ דוקא בתיבות ״כריח שדה״, המרמזות ל״ציון שדה תחרש״, ולא בענין הקרוב יותר לתוכנו של חורבן :\nכללות ענין התשובה באה ע״י המרירות ולב נשבר, ע״י שמרגיש איך ש״רע ומר עזבך את ה'״⁵¹, נשבר לבו בקרבו ומתמרמר ומתחרט על מעשיו הקודמים ומתעורר בתשובה שלימה על העבר וקבלה טובה על להבא.\n[וכן הוא גם במדריגה הנעלית של תשובה דצדיקים, בבחי' ״והרוח תשוב אל האלקים אשר נתנה״⁵² — דהרי גם צדיק גמור הוא בבחי' ״יש מי שאוהב״⁵³, ובמילא גם עבודת התשובה שלו היא תוצאה מההרגש ד״רע ומר עזבך״].\nז. א. מרגיש איך שמצבו, הנהגתו ומעשיו כפי שהם עד עתה, אינם כדבעי, ומוכרח לשנותם, ז. א. לבטל את מציאותו וציורו הקודם בכדי להתחיל עבודה חדשה, להעשות מציאות חדשה.\nוזהו״ע ״שדה תחרש״ : ״תחרש״, ענינו ״דמרפי ארעא״⁵⁴, היינו שמבטל המציאות שהי' לפני זה — והרי זהו״ע עבודת התשובה⁵⁵.\nולכן מרומז ״ביהמ״ק בחורבנו״, המורה על עבודת התשובה, בענין ״שדה תחרש״, כי בזה מתבטאת כללות עבודת התשובה.\nט. אמנם מובן שתכלית המרירות והתשובה הוא בכדי שעי״ז יתעלה אח״כ בעבודתו, בקיום התומ״צ בפו״מ ביתר זהירות ובתוספות חיות. — דהרי אפ״ל שיתמרמר באמת על הנהגתו הקודמת, ויתעורר בתשובה אמיתית, ואעפ״כ ישאר גם להבא במצבו הקודם בנוגע לעבודתו בתומ״צ, יהי' גם אח״כ מושקע בעניני משא ומתן וכו' כמקודם [ועד״ז אפ״ל גם במי שהתשובה שלו היא בדרגא נעלית : שלאחרי ההתעוררות כו' עבודתו בתומ״צ תהי' כבעבר, מבלי שתורגש תנועת התשובה].\nולזה ממשיך ומוסיף ״שראה אותו (הביהמ״ק דלעתיד) בנוי ומשוכלל״, היינו שבברכתו כלולה אמיתית ושלימות ענין התשובה — תוצאותי' הטובות והנעלות בקיום התורה ומצות באופן משוכלל ובחיות נוספת, שזה מרומז דוקא בביהמ״ק השלישי שלאחרי החורבן.",[["49","49","ולכן מרומז בתיבת ״בני״, הו״ע האהבה (<a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ״א</a>), והרי זוהי בעיקר עבודת הצדיקים."],["50","50","ולכן ״גדול יהי' כבוד הבית הזה האחרון מן הראשון״ (חגי ב, ט) שקאי על ביהמ״ק השלישי (זח״א כה, א — ובש״ס דילן (ב״ב ג, סע״א ואילך) שקאי על בית־המקדש השני. וראה בזה ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091028\" data-slug=\"likkutei-sichot\" data-id=\"1300091028\">לקו״ש ח״ט ע' 28</a> הערה 29) — כי הוא בדוגמת מעלת בע״ת על צדיקים כנ״ל (סעי' ה)."],["51","51","לשון הכתוב ירמי' ב, ט."],["52","52","ראה לקו״ת ר״פ האזינו."],["53","53","<a class=\"ft-cite\" href=\"#/read/tanya/3401310040\" data-slug=\"tanya\" data-id=\"3401310040\">תניא פל״ה (מה, ב</a>)."],["54","54","פרש״י שבת עג, ב ד״ה משום."],["55","55","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380711\" data-slug=\"likkutei-torah\" data-id=\"4001380711\">לקו״ת מסעי צו, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381026\" data-slug=\"likkutei-torah\" data-id=\"4001381026\">האזינו עה, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381283\" data-slug=\"likkutei-torah\" data-id=\"4001381283\">שה״ש לח, ד</a>."]]],[1300101095,"אמנם, מאידך גיסא : בכדי שתוצאות התשובה תהיינה כדבעי, כנ״ל, צ״ל התשובה באופן הנעלה והמתאים לתכליתה, היינו שגם בהמרירות ובתשובתו תורגש כוונתה ותכליתה בקיום התומ״צ דלהבא⁵⁶ — ולכן גם תוצאות התשובה מרומזות בהתיבה ״שדה (תחרש)״⁵⁷ :\nכלומר, אין תכליתה של התשובה הענין ד״תחרש״ שבה (המרירות והביטול), כ״א ענין ה״שדה״, העומדת ומיועדת לזריעה, צמיחה והבאת פירות — קיום התומ״צ שלאח״כ.\nיו״ד. ועפי״ז גם יובן מה שנאמר בברכה זו שם אלקים ולא שם הוי' — מכיון שעיקר הברכה ליעקב הוא שיתברך בעבודת התשובה, הקשורה בענין המרירות, שהו״ע הדין והצמצום — שם אלקים⁵⁸.\nאמנם אי״ז בחי' ״אלקים״ סתם, כ״א ״האלקים״ בה״א הידיעה, שהו״ע הידיעה והגילוי הבא לאחרי ההעלם והצמצום — שהו״ע עבודת התשובה שבאה לאחרי הריחוק, והוא הכנה לגילוי הענינים עליהם נאמר עין לא ראתה אלקים זולתך⁵⁹, שיתגלו לעת״ל בביאת משיח צדקנו.\n(משיחת ש״פ תולדות, תשכ״ד)",[["56","56","ע״ד המבואר (ראה לקו״ש ח״ג ע' 990) בענין ״נכנס בשלום ויצא בשלום״ (חגיגה יד, ב. ירושלמי שם פ״ב ה״א) — שאפשריות היציאה בשלום היא דוקא אם הכניסה בשלום, היינו שנרגש בהכניסה ש־תכליתה — היציאה."],["57","57","ועפי״ז יומתק מה שכפשוטו ״אשר ברכו ה'״ קאי על ה״שדה״ שעלי' דרז״ל ״תחרש״."],["58","58","ועוד י״ל, ע״פ משנת״ל (הערה 21) שאמיתית ענין הבל״ג הוא בקו הגבורה — לכן הברכה לענין התשובה, שהיא בחי' בל״ג, באה מבחי' ״האלקים״. וראה תו״א ס״פ תולדות."],["59","59","ראה ברכות (לד, ב) ד״ל דלרי' אבוהו לבע״ת נאמר. וראה המשך רס״ו ע' יו״ד ואילך."]]],[1300101096,"<h3>ויצא</h3>\nא. עה\"פ ויצא יעקב מבאר שבע וגו' איתא במדרש<sup data-n=\"1\">1</sup>: \"מבאר שבע — מבארה של שבועה, אמר (יעקב) שלא יעמוד עלי אבימלך ויאמר השבע לי כשם שנשבע לי זקנך, ונמצאתי משהא בשמחת בני ז' דורות\" — שהיות ואברהם נשבע לאבימלך וע\"י השבועה עכב את כניסתם של בנ\"י לא\"י ז' דורות, כמבואר במדרש פ' וירא<sup data-n=\"2\">2</sup> [כי מאברהם עד כיבוש ארץ סיחון ועוג ע\"י משה רבינו עברו ז' דורות], ויצחק גם הוא נשבע לאבימלך ועי\"ז עכבם עוד דור אחד [כי מיצחק עד כיבוש הארץ ע\"י יהושע עברו ג\"כ ז' דורות, ונמצא שנתעכבה כניסתם בעוד דור אחד לאחרי הז' דורות מאברהם], לכן חשש יעקב שמא יצטרך גם הוא לישבע לאבימלך ועי\"ז תתעכב כני־סתם של בנ\"י לא\"י (\"ז' דורות\", ז. א. עוד) דור נוסף<sup data-n=\"3\">3</sup>.\nוצריך להבין:\nמאחר דבין אברהם ובין יצחק נשבעו לאבימלך, ולא חששו לזה שנתעכבה כניסתם של בנ\"י לא\"י ע\"י השבועה, והם לא יצאו מהמקום בו גר אבימלך כדי שלא יצטרכו לישבע לו — למה דוקא יעקב הוא שיירא לישבע לאבימלך ולכרות ברית עמדו, עד שבשביל כך<sup data-n=\"4\">4</sup> יצא מבאר שבע — \"מבארה של שבועה\" זו?\nוכן קשה לאידך גיסא:\nאיך יתכן שאברהם ויצחק נשבעו לאבימלך מבלי לחשוש להעכבת כני־סתם של בנ\"י לארץ?\nב. והביאור: מצינו דחלוקה דרגת מעלתם של אברהם ויצחק לדרגת מעלתו של יעקב אשר עפ\"ז יבואר ג\"כ הפרש יסודי שבין עבודתם של אברהם ויצחק לזו של יעקב:\n\"אברהם — יצא ממנו ישמעאל, יצחק יצא ממנו עשו\"<sup data-n=\"5\">5</sup>, היינו שיש־מעאל ועשו, אף שהיו בני אברהם ויצחק, בכ\"ז \"יצאו\" משייכותם לאבו־",[["1","1","ב\"ר פס\"ח, ז."],["2","2","שם פנ\"ד, ד."],["3","3","כפי' הב' במתנות כהונה שם פס\"ח, ולפי' הא' (שיצחק לא עכבם כלל כי \"לא נשבע מחדש רק אמר לו השבועה הקדומה שהיא בינותינו מאביך תהא בינותינו אל תפר אותה\" ויעקב הי' מתיירא שיעכבם עוד ז' דורות) קשה: א) למה לא הי' יכול גם יעקב לחדש את שבועת אברהם כפי שעשה יצחק? ובפרט לפי לשון המדרש: ויאמר (אבימלך) השבע לי כשם שנשבע לי זקנך. ב) במדרש בראשית זוטא שם הגירסא היא: \"כשם שנשבע לי זקנך ואביך\", מזה מוכח שגם יצחק עכבם עכ\"פ דור אחד, ואבימלך רצה שיעקב יעשה ג\"כ כפי שעשה יצחק."],["4","4","ביפ\"ת פי' שלא בשביל זה יצא, שהרי הי' מוכרח לצאת מפני עשו ובשביל מצות אביו ואמו, אלא שאגב זה הרויח עוד כי נמלט מבארה של שבועה. אבל ממה שבב\"ר שם מביא פי' \"מבארה של ברכות\" ביחד עם פי' זה, משמע שכמו שלפי' \"מבארה של ברכות\" הרי בש־ביל זה יצא, כ\"ה ג\"כ לפי' \"מבארה של שבועה\", וכמו שמשמע במ\"כ שם, וכפש־טות לשון המדרש. ואי\"ז סתירה למשמעות הכתובים שיצא מפני עשו וכו' כי אפ\"ל שיצא מחמת כמה טעמים, וכאו\"א מהם דיו."],["5","5","ויק\"ר פל\"ו, ה. פסחים נו, א. ספרי דברים ו, ד. שם לב, ט."]]],[1300101097,"תיהם ונפרדו מהם<sup data-n=\"6\">6</sup>, כי הקדושה של אברהם ויצחק ועבודתם לא \"הגיעו\" לבניהם אלו ולא פעלו בהם שייהפכו לטוב<sup data-n=\"7\">7</sup>. אבל יעקב — מעלה שלו \"מטתו שלימה\"<sup data-n=\"8\">8</sup>, כי עבודתו פעלה בכל י\"ב בניו שיהיו \"שלמים\" ושל־מים בשייכותם ליעקב ומדריגתו. ועם היות ש\"האבות (כולם) הן הן המר־כבה\"<sup data-n=\"9\">9</sup>, ונשמתו של כל אחד מהאבות היא מעולם האצילות 9*), יש חילוק ביניהם, וגם בנוגע לעבודתם בענינים של היפך הטוב והקדושה: יעקב עסק בעיקר בבירור וזיכוך הרע והיפוכו לטוב לתמיד, משא\"כ אברהם ויצחק. ולכן אף שעשה ישמעאל תשובה<sup data-n=\"10\">10</sup> וי\"א שכאשר וירץ עשו לקראתו (ד־יעקב) וישקהו — נשקו בכל לבו<sup data-n=\"11\">11</sup> — לא הי' לזה קיום.\nואעפ\"י שאברהם ויצחק עסקו ב־עבודת הבירורים, וכמשארז\"ל 11*) (ב־אברהם) עה\"פ \"ויקרא שם בשם ה' א־ל עולם<sup data-n=\"12\">12</sup>: אל תקרא ויקרא אלא ויקריא מלמד שהקריא אברהם אבינו לשמו של הקב\"ה בפי כל עובר ושב כו' \"; ועד\"ז מבואר בנוגע לעבודתו של יצחק בחפירת בארות 12*) — בכ\"ז\nהיתה עבודתם זו בעניני רע וקליפה בדרך דחי' ושלילה — שלא ינגדו ויפריעו לעניני קדושה, אבל לא שהם עצמם ייהפכו לטוב וקדושה<sup data-n=\"13\">13</sup>. הרי תכליתה ומטרתה של התעסקותם ב־עניני רע ופעולתם בהם היתה באופן של שלילה: ביטול ההתנגדות ולא בירור מציאותם<sup data-n=\"14\">14</sup>; משא\"כ ביעקב",[["6","6","ראה אוה\"ת וירא צג, ב."],["7","7","ראה לעיל ע' 85 ובהערה 41, שיש חילוק בענין זה בין ישמעאל ועשו."],["8","8","ויק\"ר שם. וראה בשאר המקומות שנסמנו לעיל הערה 5."],["9","9","ב\"ר פמ\"ז, ו. פפ\"ב, ו. וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא פכ\"ג</a> ופל\"ד, ותו\"א יתרו ד\"ה להבין. 9*) אגה\"ק סי' כה. תו\"א שם."],["10","10","פרש\"י ח\"ש כה, ט."],["11","11","ראה פרש\"י וישלח לג, ד. 11*) סוטה י', ב."],["12","12","וירא כא, לג. 12*) ראה תו\"א ותו\"ח ר\"פ תולדות. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300011029\" data-slug=\"likkutei-sichot\" data-id=\"1300011029\">לקו\"ש ח\"א ע' 29</a>. ועוד."],["13","13","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010010\" data-slug=\"or-hatorah-hb\" data-id=\"8159010010\">וע\"ד</a> מציאות הקליפות קודם חטא עה\"ד שהיו בבחי' קליפה השומרת לפרי, לפי שהיו חוץ לגבול בי\"ע דקדושה, אבל מ\"מ היו מציאות של קליפה (ראה של\"ה יח, ב. אוה\"ת וישלח ע' רנא, בראשית ע' 1162)."],["14","14","ואף דאברהם מגייר (רש\"י לך יב, ה — מב\"ר שם. זח\"א עט, ב. ובכ\"מ). וברמב\"ם הל' ע\"ז פ\"א ה\"ג, ויקרא שם בשם ה' א־ל עולם כו' עד שנתקבצו אליו אלפים ורבבות והם אנשי בית אברהם ושתל בלבם \"העיקר הגדול הזה\" — הרי לא הי' להם המשך וקיום ורק בני' נעשו \"בעולם אומה שהיא יודעת את ה'\" (עיין רמב\"ם שם), ובל' הרה\"ח וכו' הרר\"א מהאמלי (חנה אריאל וירא לג, סע\"א) וע\"י עבודתו כו' של אאע\"ה כו' להודיע לבנה\"א מב\"נ טבעו של הקב\"ה בחי' א־ל עולם לפי שעה (כי לא נתקיימו בזאת האמונה והידיעה כ\"א ביתו אחריו של אאע\"ה). — ועייג\"כ <a class=\"ft-cite\" href=\"#/read/torah-or/3901370051\" data-slug=\"torah-or\" data-id=\"3901370051\">תו\"א לך יא, ד</a>. תו\"ח ואוה\"ת שם (וצע\"ק מתו\"א ד\"ה משה ידבר — הא' והב'. תו\"ח שם), ואכ\"מ. ולהעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051155\" data-slug=\"likkutei-sichot\" data-id=\"1300051155\">לקו\"ש ח\"ה ע' 143</a> הערה 16*, שמ\"ש רש\"י \"אברהם מגייר את האנשים ושרה מגיירת את הנשים\" י\"ל דאין הכוונה לגירות ממש ושינוי המציאות שלהם — כ\"א למה \"שהכניסן תחת כנפי השכינה\". לכאורה אפשר לבאר גם ע\"פ הידוע אשר הגר יש בו ניצוץ של נשמה דקדושה גם קודם שנתגייר (ראה תשובות מהר\"ם מרוטנבורג (הובא בספר תשובות בעלי התוס' מכת\"י נויארק תשי\"ד — ע' רפו, סי\"ט) בשם ר\"י החסיד) — ועפ\"ז מובן דיוק לשון חז\"ל בכ\"מ \"גר שנתגייר\" ולא \"גוי שנתגייר\" וכיו\"ב (חיד\"א בס' מדבר קדמות מע' ג' אות ג') — וא\"כ מה שאברהם"]]],[1300101098,"וילך חרנה, חרון אף של מקום 14*) ב־עולם — ושם עבודתו ופעולתו פעולה חיובית — לבררם ולהפכם לקדושה.\nוע\"ד<sup data-n=\"15\">15</sup> ההפרש שבין עבודת ה־צדיקים ועבודת בעלי תשובה: הצדיק אין לו שייכות לעניני רע, עד שגם מחשבה זרה, אשר לא להוי', אינה נופלת במחשבתו; כמבואר בתניא ב־ארוכה<sup data-n=\"16\">16</sup>; משא\"כ בעל תשובה ענינו להפוך גם את הרע לקדושה, ועד ש־זדונות נעשו לו כזכיות<sup data-n=\"17\">17</sup>.\nג. ולהיות שבעבודת אברהם ו־יצחק לא נתבררה עדיין מציאותו של הרע (שבפלשתים וכו') ורק הת־נגדותו בטלה, הרי היתה גם האפ־שריות שעצם מציאותם והלא טוב של (בניהם אפילו) ישמעאל ועשו ישאר בתקפו ולא יתברר בעבודתם של אבותיהם (ואדרבה: \"יצא ממנו\" שיצאו משייכות כל שהי לעבודתם וקדושתם), אלא שהם גם לא הת־נגדו לעניני אבותיהם ולא הפריעו אותם בעבודתם<sup data-n=\"18\">18</sup>. עכ\"פ, הרי מהות הקליפה עצמה, כאשר אין לה שייכות לקדושה ואינה מנגדת לה, לא נגעה בה עבודתם של אברהם ויצחק וא\"כ אין מציאותה כשלעצמה מושללת מצד עבודתם זו.\nוכמו שמצינו באברהם שנתיישב בתוך בני חת<sup data-n=\"19\">19</sup>, והם אף הכירוהו כ\"נשיא אלקים\" ו\"בתוכנו\"<sup data-n=\"20\">20</sup>, ובכ\"ז לא פעל זה בהם שהם עצמם ייהפכו לטוב, ונשארו בתוארם \"בני חת\"<sup data-n=\"21\">21</sup> גם לאחרי ההתיישבות ביניהם. וגם מה שנענו לבקשתו במכירת מערת המכפלה, ה\"ז רק שלא הפריעו לו בביצוע עניניו הוא, אבל מהותם ש־להם לא נהפכה למציאות של קדושה<sup data-n=\"22\">22</sup>.\nמשא\"כ בעבודתו של יעקב שתכ־ליתה לברר ולהפוך ולזכך גם את עניני העולם שמצד הקליפה וסט\"א, היינו שבעבודתו נשללת גם עצם מציאותו של הרע — לכן היתה \"מטתו שלימה\".\nד. ועפ\"ז יובן מה שאברהם ויצחק כרתו ברית עם אבימלך והשלימו עמו ע\"י השבועה.\nכי תכליתה של שבועה וכריתת־ברית כזו ה\"ה לפעול בכל תוקף על כל אחד מהצדדים שלא יתנגד לשני",[["","","מגייר וכו' אי\"ז ענין בירור והיפוך הקלי' לקדושה — אבל אינו, דבכל אתהפכא כיו\"ב — ה\"ז פדיית ובירור הניצוץ דקדושה שבו. 14*) רש\"י ס\"פ נח. וראה זח\"ג קמז, א."],["15","15","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370101\" data-slug=\"torah-or\" data-id=\"3901370101\">תו\"א ויצא כא, ג</a>. תו\"ח שם כו, ב. וראה לעיל ע' 83 ואילך בארוכה."],["16","16","<a class=\"ft-cite\" href=\"#/read/tanya/3401310015\" data-slug=\"tanya\" data-id=\"3401310015\">תניא פ\"י</a> ואילך."],["17","17","יומא פו, ב."],["18","18","וי\"ל שגם זה מרומז בל' \"יצא ממנו\" למעליותא — ע\"ד הפי' (אוה\"ת — נסמן לעיל הערה 6) יצא ונפרד מאברהם."],["19","19","ראה חיי שרה כג, ו ורש\"י שם ד."],["20","20","ח\"ש שם. וראה ראב\"ע שם: \"בעבור כי אתה נביא\"."],["21","21","ראה תולדות כז, מו."],["22","22","וי\"ל עפ\"ז מ\"ש רש\"י (ח\"ש כד, ז) שמה שאמר אברהם לאליעזר \"ואלקי הארץ\" הוא לפי \"שהרגלתיו בפי הבריות\", שכוונתו, שאברהם הסביר לאליעזר שאף שהי' \"יושב בקרבו\" (של הכנעני), מ\"מ השפעתו עליו היתה רק מה \"שהרגלתיו בפי הבריות\" אבל לא נשתנו בעצם מ־מהותם הקודם, ולכן \"לא תיקח אשה לבני מבנות הכנעני\" (ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151159\" data-slug=\"likkutei-sichot\" data-id=\"1300151159\">לקו\"ש חט\"ו ע' 159</a> ואילך). וי\"ל שעפ\"ז מובן מה שלא מצינו שאברהם השתדל לפעול על לוט שייהפך לטוב. ורק כשהפריעו אותו בעבודתו — וכמו שאמר \"אל נא תהי מריבה בינֵי וביניך וגו' \" — בקש וגם פעל שעכ\"פ \"ויפרדו איש מעל אחיו\"."]]],[1300101099,"ולא יתקוטט וילחום עמו — והיא הלא היתה כוונתם של אברהם ויצחק במה שנשבעו לאבימלך וכרתו עמו את הברית: שלא יתנגד להם ולא יפריעם בעבודתם; אבל, מאידך, אין ענינה של השבועה וכריתת הברית לפעול שינוי במהותו של אבימלך ול־הפכו למציאות של קדושה<sup data-n=\"23\">23</sup>.\nאמנם כל זה הוא אופן עבודתם של אברהם ויצחק, כנ\"ל. משא\"כ ביעקב, שלהיות שאופן עבודתו הי' בשלילת מציאות הקליפה, ע\"י אתכפיא ואת־הפכא של הקליפה וסט\"א, הרי לא הי' יכול לכרות ברית ולהשלים עם אבימלך כפי שנמצא בציורו הוא<sup data-n=\"24\">24</sup>.\nובזה יבואר המשך הכתוב \"ויצא יעקב מבאר שבע וילך חרנה\" — לפי פי' המדרש ש\"מבאר שבע\" פירו־שו \"מבארה של שבועה\"<sup data-n=\"25\">25</sup> — כי יציאתו מ\"בארה של שבועה\" ענינה מה שמצד עבודתו לא הי' יכול להש־לים עם מציאות הרע בעולם, כנ\"ל, ולכן לא נשאר במקומו הוא, ב\"ארץ אשר גו' עיני ה\"א בה וגו' \"<sup data-n=\"26\">26</sup> — כ\"א \"וילך חרנה\" \"חרון אף של מקום\"\nבעולם, לברר ולהפכו לקדושה<sup data-n=\"27\">27</sup>.\nה. ועפ\"ז יובן גם מה שאברהם ויצחק לא חששו לישבע לאבימלך, עם היות שעי\"ז \"משהא בשמחת בני\": כי באמת לא השבועה עצמה (שהיא היא דרגת עבודתם) היא הסיבה לעי־כוב כניסתם של בנ\"י לא\"י, אלא שמצד עבודתם באופן של שבועה וכריתת־ברית עם אבימלך, נשארה עדיין מציאות הקליפה בתקפה וישותה — וכל זמן שהרע דהעולם הוא ב־מעמדו ואיתנו, הרי זה מניעה ועיכוב לביאתן של בנ\"י לארץ<sup data-n=\"28\">28</sup>.\nודוקא לאחרי גלותו של יעקב ב־\"חרון אף של מקום בעולם\", ועבודתו בבירור עניני הקליפה והיפוכם ל־קדושה, יכולה להיות \"שמחת בני\" בגאולתם ובכניסתם של בנ\"י לא\"י.\nו. וכן הוא הענין גם בנוגע לגאו־לה העתידה, שתבוא דוקא ע\"י אופן עבודתו של יעקב<sup data-n=\"29\">29</sup>: שע\"י עבודתינו במשך זמן הגלות בבירור וזיכוך \"חרון אף של מקום בעולם\" נזכה לבנין ביהמ\"ק השלישי — \"לא כאברהם שכתוב בו הר כו' ולא כיצחק שכתוב בו שדה כו' אלא כיעקב שקראו בית\"<sup data-n=\"30\">30</sup> — בביאת משיח צדקנו.\n(משיחת ש\"פ ויצא, יו\"ד כסלו, תשכ\"ו)",[["23","23","וכמובן גם מזה שיצחק הוצרך לחדש את הכריתת־ברית, וכן יעקב חשש שיצטרך לעשות כן."],["24","24","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051141\" data-slug=\"likkutei-sichot\" data-id=\"1300051141\">לקו\"ש ח\"ג ע' 794</a> ובהערה 28* שמה שיעקב כרת ברית עם לבן (ויצא לא, מד), הי' זה מלכתחילה באופן ש\"אתה לא תעבור אלי וגו' לרעה — לרעה אי אתה עובר אבל אתה עובר לפרקמטיא\" (ויצא שם נב. ב\"ר הובא בפרש\"י שם), וענין הפרקמטיא ומסחר הו\"ע בירור הניצוצות ואתהפכא חשוכא לנהורא (ראה תו\"א ר\"פ וישב). וראה לקו\"ש ח\"ה ע' 129 ואילך."],["25","25","ראה קיצורים והערות לס' התניא ע' נז."],["26","26","דברים יא, יב."],["27","27","ראה תו\"א ותו\"ח שם כה, א ואילך."],["28","28","וזהו גם דיוק הלשון \"משהא ב־שמחת בני\" ולא \"דוחה\" או \"מעכב\" וכיו\"ב, כי ע\"י השבועה לא דחו את ה־כניסה לארץ כ\"א שלא היתה ראוי' להיות עדיין."],["29","29","ראה תו\"א ותו\"ח שם."],["30","30","פסחים פח, א ובמהרש\"א שם. וראה ד\"ה איכה תשל\"א ובהע' 5 שם."]]],[1300101100,"א. בהפסוק<sup data-n=\"1\">1</sup> „ותהר לאה ותלד בן ותקרא שמו ראובן כי אמרה כי ראה ה' בעניי כי עתה יאהבני אישי\", מעתיק רש\"י „ותקרא שמו ראובן\", ומפרש<sup data-n=\"2\">2</sup>: „רבותינו פירשו אמרה ראו מה בין בני לבן חמי שמכר הבכורה ליעקב וזה לא מכרה ליוסף ולא ערער עליו ולא עוד שלא ערער עליו אלא שבקש להוציאו מן הבור\".\nוצריך להבין:\nא) רש\"י הודיע כלל יסודי בפירושו: „אני לא באתי לפרש אלא פשוטו של מקרא\"<sup data-n=\"3\">3</sup>, היינו שכוונתו לפרש ולבאר (רק) דבר שאינו מובן ומוסבר כל צרכו בפשט הכתובים — ומה קשה כאן בפשט הכתוב שרש\"י צריך ל־פרשו?\nב) יתירה מזו: רש\"י מפרש שהטעם לקריאת שם ראובן הוא משום ש־„אמרה ראו מה בין בני וכו'\", היפך פשוטו של מקרא: „ותקרא שמו ראו־בן\" — „כי ראה ה' בעניי כי עתה יאהבני אישי\"?\nואף שפירושו זה של רש\"י, בכללות, מקורו בגמרא<sup data-n=\"4\">4</sup>, הרי ידוע הכלל שנקט לו רש\"י בפירושו (וחוזר עליו כמה פעמים)<sup data-n=\"5\">5</sup>: „ואני לא באתי לפרש אלא\nפשוטו של מקרא ולאגדה המיישבת דברי המקרא דבר דבור על אופניו\"<sup data-n=\"6\">6</sup>, היינו שצ\"ל צורך ביישוב והיישוב צ\"ל על אופניו (כנו וסדר התיישבותו) של המקרא.\nב. והנה יש מפרשים 6*) דהטעם המפורש בקרא „כי ראה ה' בעניי גו'\" אינו מספיק, כי בזה מוסבר רק חלק משם ראובן, תיבת „ראו\" שבו, אבל לא — „בן\" שבו; וע\"כ דרשו רבותינו עוד<sup data-n=\"7\">7</sup> טעם, ש„אמרה ראו מה בין בני לבן חמי וכו'\", שענינו מרומז בשם „ראובן\" כולו.\nאבל בפרש\"י א\"א לפרש כן, כי\n[נוסף לזה שאם זהו הכרחו של רש\"י להביא טעם אחר על שם ראו־בן מהמפורש בקרא 7*), הו\"ל לרש\"י לפרשו<sup data-n=\"8\">8</sup>]",[["5","5","ראה גם פרש\"י בראשית שם, כב. ד, ח. ו, ג. וירא יט, טו. כ, טז."],["6","6","ראה רש\"י משלי כה, יא. 6*) חדא\"ג מהרש\"א ברכות שם. ובדבק טוב כתב שזהו טעמו של רש\"י שהביא רבותינו פירשו."],["7","7","ואין להקשות דא\"כ הטעם שבכתוב למה לה — כי כמה שמות מצינו שיש בהם ב' (ויותר) רמזים, וכמו „שמים\" (דלקמן בפנים) ד„שא מים\" מובן מהכתוב והשאר — בדחז\"ל. ובפרט בנדו\"ד — שהטעם שבכתוב הוא — גלוי לכל, אבל דרבותינו — נבואה. 7*) וגם לפי\"ז „אכתי קשה להיפך על לישנא דקרא גופא דכתיב „כי אמרה כי ראה ה' בעניי\" כיון שאי\"ז עיקר בשם ראובן\" (פני' בברכות שם)."],["8","8","ואף שאין דרכו של רש\"י להביא הקושיא המכריחה הפי' בהכתוב, אמנם בנדו\"ד שרש\"י מפרש היפך המפורש בהכתוב, הי' צריך רש\"י לבאר."],["1","1","פרשתנו כט, לב."],["2","2","בדפוס ראשון ושני ליתא כל פרש\"י זה. ובכת\"י רש\"י יש בפרש\"י זה עוד פי': „ד\"א איש טוב תואר וחכם הי' ואמרה ראו בן שנתן לי הקב\"ה וכו' בברית של ר' אליעזר\" (כנראה הכוונה לפדר\"א פל\"ו). אבל בכל הדפוסים אינו."],["3","3","בראשית ג, ח. ועד\"ז שם ג, כה. ובכ\"מ."],["4","4","ברכות ז, ב. וראה לקמן ס\"ג."]]],[1300101101,"בפשוטו של מקרא אי\"ז קושיא מעיקרא דמילתא, שהרי אפשר לומר שהאותיות „בן\" שבשם ראובן מרמזות לה„ב\" וה„נ\"<sup data-n=\"9\">9</sup> של „בעניי\"<sup data-n=\"10\">10</sup>; ואף שבשם (ראו)בן אין בו ה„עין\" וה„יוד\" של בעניי<sup data-n=\"11\">11</sup>, וגם ניקוד ה„בי\"ת\" הוא באו\"א, הרי כבר למדנו כיו\"ב במ\"א בפרש\"י<sup data-n=\"12\">12</sup>: „שמים\" הוא ר\"ת „שא מים, שם מים, אש ומים\", אף שה־„אלף\" של „שא\" ושל „אש\" ליתא בתיבת „שמים\", וגם ניקוד ה„שין\" של אש הוא באופן אחר — אלא שדי לנו באות „שין\" שב„שמים\" (ובפרט שאות זו היא המורגשת בעיקר בביטוין של התיבות „שא\" ו„אש\"), ועד\"ז מובן גם בנדון תיבת „בעניי\" (שהאותיות „ב\" ו„נ\" (בן) הן המור־גשות בה בעיקר<sup data-n=\"13\">13</sup>, ולכן לא איכפת לן החסרון של שאר האותיות<sup data-n=\"14\">14</sup>. וא\"כ\nהדרא קושי' לדוכתא: פירושו של רש\"י כאן למה לן<sup data-n=\"15\">15</sup>?",[["9","9","ובכלל: כפי הנראה עיקר קושייתם הוא על ה„ב\" ולא על ה„נו\"ן\", כיון שר־גיל להוסיפו בכמה שמות וכמו פישון וגיחון (בראשית ב, יא־יג) ובנדו\"ד השם שמעון שהוא ע\"ש „כי שמע ה'\" שאין בו נו\"ן (אף שבדוחק י\"ל שה„נו\"ן\" שבשם שמעון הוא הנו\"ן ש„בשנואה\"). וראה פירוש באר יצחק עפרש\"י שכ' שהקושיא בהכתוב היא ש־הול\"ל ראיון."],["10","10","ראה חידושי הרש\"ש לב\"ר פע\"א, ג."],["11","11","ראה פירוש מהרז\"ו (ב\"ר שם): „דאי משום כי ראה בעניי הו\"ל לקרותו ראו בען\". ובביאור הרד\"ל לפדר\"א שם „שא\"כ (לפי טעם הכתוב) הי' לה לקרותו ראו עני\"."],["12","12","בראשית א, ח."],["13","13","ואף שה„ב\" של בעניי אינו מעיקר התיבה „עניי\", מ\"מ מכיון שבפועל צריכה לומר „כי ראה ה' בעניי\" הרי מתאים שתהי' בהשם התחלת התיבה לידע למה היא מכוונת."],["14","14","ובכלל אינו מוכרח בדרך הפשט *) שאותיות השם תהיינה בדומה ממש לאותיות שבטעם השם כ\"א רק לתוכן הטעם. וכמוכח משם „בבל\" שהוא „כי שם בלל ה' שפת כל הארץ\" (נח יא, ט). ועד\"ז בכ\"מ. ומה שהוצרך רש\"י לפרש עה\"פ (בראשית ה, כט) ויקרא את שמו נח לאמר זה ינחמנו ממעשנו ומעצבון ידינו גו' — „יניח ממנו את עצבון עד שלא בא נח כו' ובימי נח נחה וזהו ינחמנו, ואם לא תפרשהו כך אין טעם הלשון נופל על השם כו'\", הוא לפי שהיינו טועים בפי' התיבה ינחמנו (וראה ב\"ר פכ\"ה ב. ובמפרשי המדרש). *) משא\"כ בדרך הרמז והדרוש שיש לרמז ולדרוש כו\"כ באותיות השם."],["15","15","ואין לומר שרש\"י הוצרך להביא פירוש רבותינו, כי לפי טעם הכתוב, „כי ראה ה'\" הו\"ל ראה בן בל' יחיד ולא ראובן בל' רבים (כביפ\"ת ונזר הקודש לב\"ר פע\"א שם. וראה גם ב„הכותב\" בע\"י). או דקשה: ראובן הוא ל' עתיד והו\"ל ראה בן בל' עבר (ראה אלשיך עה\"פ), כי א) לפי הנ\"ל קשה עד\"ז גם בשם שמ־עון (ראה יפ\"ת ונזר הקודש שם) ומכיון שאין רש\"י מפרש כלום בשם שמעון מובן שאין זה קושיא בפשש\"מ, וכבהערה ש־לפ\"ז. ב) הו\"ל לרש\"י להעתיק גם התיבות „כי ראה ה'\" או עכ\"פ לרמז ב„וגו'\", כיון שזוהי הקושיא בכתוב המכריחה לפ־רש באו\"א. במשכיל לדוד כאן (וכ\"ה במירא דכיא) דהטעם שהביא רש\"י פירוש רבותינו הוא „דבכולהו כתיב בקרא תחילה הטעם ואח\"כ השם כו', משא\"כ הכא גבי ראובן דבתחלה כתיב ותקרא שמו ראובן ואח\"כ כתיב כי אמרה, ש\"מ דה\"ק ותקרא שמו ראובן אפי' בלא טעם המבורר בקרא והיינו הך דקאמרי רבנן\" *). אמנם ג\"ז אינו מספיק דהלא במ־קום זה טרם ידעינן שבשאר השמות **) נאמר *) ועד\"ז כתב בעיון יעקב (בע\"י בר־כות שם. וראה גם מושב זקנים עה\"ת) במה שרבותינו בגמרא (ברכות) דרשו עוד טעם (הנ\"ל) על קריאת שמו ראובן. ובביאור ה־רד\"ל בהדרשא ראו בן שבפדר\"א (הובא לעיל הערה 2). **) תולדות (כה, ל): ויאמר גו' ה־אדום גו' ע\"כ קרא שמו — אינו שייך"]]],[1300101102,"ג. גם צריך להבין:\nא) בהטעם ע\"ש שאמרה „ראו מה בין בני כו'\": למה פירש רש\"י ב־פשט הכתוב (כרבותינו בגמרא) שה־הפרש „בין בני לבן חמי\" הוא בזה ש„בן חמי מכר הבכורה וזה לא מכרה ולא ערער עליו ולא עוד שלא ערער עליו כו'\" — (א) במאורע העתיד לבוא לאחר כמה וכמה שנים, ובמילא (ב) נבואה רחוקה<sup data-n=\"16\">16</sup>, (ג) ובשייכות לגנותו של ראובן: נטילת הבכורה מראובן עבור חטאו<sup data-n=\"17\">17</sup>; והורדת יוסף לבור — הרי אפשר לפרשו באופן דשבחו של „בני\" ובדבר שיארע בזמן קרוב יותר: ראו מה בין בני לבן חמי שגזל וחמס<sup data-n=\"18\">18</sup> וכו' ואילו בני\nלא פשט ידו בגזל<sup data-n=\"19\">19</sup> (וכמו שפרש\"י עה\"פ<sup data-n=\"20\">20</sup> וילך ראובן בימי קציר חטים)?\nב) גם בפירושו של רש\"י גופא אי\"מ, שתוכן פירושו הוא שונה מהפי' שבגמרא. בגמרא איתא: דאילו בן חמי אע\"ג שמדעתי' זבני' לבכורותי' דכתיב כו' חזו מה כתוב בי' וישטם עשו את יעקב<sup data-n=\"21\">21</sup> כו' ויעקבני זה פעמים<sup data-n=\"22\">22</sup> וגו' ואילו בני אע\"ג דעל כרחי' שקלי' יוסף לבכורותי' מני' דכתיב כו' אפילו הכי לא אקנא בי' דכתיב כו'\" — היינו שההפרש בין עשו לראובן הוא: עשו שנא את יעקב עבור הבכורה שהועברה לו (אע\"ג דמ־דעתי' זבני' לי'), וראובן לא „אקנא\" ביוסף; משא\"כ לפי פירש\"י תוכן החילוק ביניהם הוא (לא בשייכות ה־קנאה והשנאה, והעדרן, מצד הבכורה, כ\"א) בנוגע לגוף המכירה (שרק זה נזכר בנוגע לבן חמי), שעשו מכר הבכורה, העילוי של ראובן לעומתו הוא בזה שלא מכר הבכורה — דבר שלא נזכר כלל בגמרא כמעלתו של ראובן.\nג) רש\"י מוסיף „ולא ערער עליו ולא עוד שלא ערער עליו אלא שבקש להוציאו מן הבור\" — ולכאורה, כשם שהודגש בהנוגע למעלתו של „בני\", שהיתה בתכלית הטוב, כמו\"כ הול\"ל להזכיר בהגריעותא של בן חמי, שעשו ערער על הבכורה<sup data-n=\"23\">23</sup> (ע\"ד מה דאי'",[["","","תחלה הטעם, ומצד סדר הכתוב כאן (בלי השינוי משאר השמות) אין משמעות כלל שותקרא שמו ראובן הוא גם בלי טעם, ועוד ועיקר: מפורש „ותקרא שמו ראובן כי אמרה כי ראה גו'\". ופשיטא ששינוי הסדר אינו טעם מספיק שרש\"י יפרש טעם אחר מהמפורש בקרא."],["16","16","בחדא\"ג מהרש\"א שם (ועד\"ז הוא ב„הכותב\" בע\"י שם, ובנזר הקודש (לב\"ר שם) בטעם המדרש „ראו בן בין הבנים\" „דשלא מדעת שם השי\"ת בפי' עתידות זה ראו מה בין בני\", והוצרך לזה משום דקשי' לי' דהא לא חשיב לאה בכלל הנביאות במגילה (יד א). אבל בפרש\"י מפורש „אמ־רה (לאה)\" ובפרש\"י (בפסוק שלאח\"ז) כתב גם על לאה „לפי שהאמהות נביאות היו\" כדבר הידוע כבר, וי\"ל שזהו מפרש\"י דילן שהביא: „אמרה ראו מה בין בני כו'\". ראה מפרשי רש\"י שם. וראה תו\"ת פרשתנו כט, לה."],["17","17","וכמ\"ש (דה\"א ה, א) „ובחללו יצועי אביו נתנה בכורתו לבני יוסף\". ובהזמן שנטל ממנו וניתן ליוסף ראה ב\"ב קכג, א. ובחדא\"ג מהרש\"א שם."],["18","18","ראה פרש\"י תולדות כו, לד. לנדו\"ד כיון דשם הרי הי' קדימה בזמן."],["19","19","להעיר שדרשא זו אי' במדרש ה־גדול."],["20","20","פרשתנו ל, יד."],["21","21","תולדות כז, מא."],["22","22","שם, לו."],["23","23","בכת\"י רש\"י „שבן חמי מכר את הבכורה ועירער עלי'\", אבל בכל הדפוסים אינו."]]]]});
